import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { getDefaultWorkspace, getUserWorkspaces } from "@/lib/workspace/queries";
import { getUserContext } from "@/lib/auth/permissions";
import { getWorkspaceProjects } from "@/lib/project/queries";
import { AppShell } from "@/components/app/app-shell";
import { getNavVisibility } from "@/lib/auth/permissions";
import { UserContext } from "@/types/permissions";

export const metadata = {
  title: "Workspace | Ropimo",
  description: "Ropimo unified team workspace",
  icons: {
    icon: [
      { url: "/logo/favicon.png", type: "image/png" },
      { url: "/favicon.ico" },
    ],
    apple: "/logo/favicon.png",
    shortcut: "/logo/favicon.png",
  },
};

export default async function ProtectedAppLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const headerList = await headers();
  const currentPath = headerList.get("x-pathname") || "";
  if (currentPath.includes("_kit") || currentPath.includes("/kit")) {
    return <div className="app-root min-h-screen bg-canvas text-ink">{children}</div>;
  }

  const supabase = await createClient();

  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    redirect("/login");
  }

  // Check if the user belongs to at least one workspace
  const workspace = await getDefaultWorkspace();

  if (!workspace) {
    // Redirect to onboarding if user has no workspace yet
    redirect("/onboarding");
  }

  const [userCtx, projects, allWorkspaces] = await Promise.all([
    getUserContext(workspace.id),
    getWorkspaceProjects(workspace.id),
    getUserWorkspaces(),
  ]);

  const userData = {
    email: user.email,
    fullName: (user.user_metadata?.full_name as string) || null,
  };

  const navVisibility = userCtx ? getNavVisibility(userCtx) : undefined;

  return (
    <AppShell
      user={userData}
      workspace={workspace}
      allWorkspaces={allWorkspaces}
      userContext={userCtx}
      navVisibility={navVisibility}
      projects={projects}
    >
      {children}
    </AppShell>
  );
}

import * as React from "react";
import { createClient } from "@/lib/supabase/server";
import { getDefaultWorkspace } from "@/lib/workspace/queries";
import { getUserContext } from "@/lib/auth/permissions";
import { getOverviewData } from "@/lib/overview/queries";
import { OverviewDashboard } from "@/components/app/overview-dashboard";

export const metadata = {
  title: "Overview — Ropimo",
  description: "Company command center for active projects and team deliverables",
};

export default async function OverviewPage() {
  const supabase = await createClient();

  const [{ data: authData }, workspace] = await Promise.all([
    supabase.auth.getUser(),
    getDefaultWorkspace(),
  ]);

  const user = authData?.user;
  const workspaceId = workspace?.id || "";
  const workspaceName = workspace?.name || "Workspace";
  const userId = user?.id || "";
  const userName =
    (user?.user_metadata?.full_name as string) ||
    (user?.email ? user.email.split("@")[0] : "there");
  const userEmail = user?.email || "";

  const overviewData = await getOverviewData(workspaceId, workspaceName, userId);

  return (
    <OverviewDashboard
      workspaceId={overviewData.workspaceId}
      workspaceName={overviewData.workspaceName}
      userId={userId}
      userName={userName}
      userEmail={userEmail}
      projects={overviewData.projects}
      myOpenTasks={overviewData.myOpenTasks}
      allTasks={overviewData.allTasks}
      openTasksCount={overviewData.openTasksCount}
      dueTodayCount={overviewData.dueTodayCount}
      overdueCount={overviewData.overdueCount}
      completedCount={overviewData.completedCount}
      people={overviewData.people}
      departments={overviewData.departments}
      recentActivities={overviewData.recentActivities}
      upcomingDeadlines={overviewData.upcomingDeadlines}
      jobOpenings={overviewData.jobOpenings}
      openJobsCount={overviewData.openJobsCount}
      pendingLeaves={overviewData.pendingLeaves}
      pendingLeavesCount={overviewData.pendingLeavesCount}
      candidates={overviewData.candidates}
      interviews={overviewData.interviews}
      upcomingEvents={overviewData.upcomingEvents}
    />
  );
}

import * as React from "react";
import Link from "next/link";
import { notFound } from "next/navigation";
import { getDefaultWorkspace } from "@/lib/workspace/queries";
import { getJobOpeningById } from "@/lib/recruitment/queries";
import { getWorkspaceDepartments } from "@/lib/department/queries";
import { ShareJobButton } from "@/components/app/recruitment/share-job-button";

export const metadata = {
  title: "Job Opening Details — Ropimo",
};

export default async function JobDetailPage(props: {
  params: Promise<{ jobId: string }>;
}) {
  const params = await props.params;
  const workspace = await getDefaultWorkspace();
  const workspaceId = workspace?.id || "";

  if (!workspaceId) {
    notFound();
  }

  const [job, departments] = await Promise.all([
    getJobOpeningById(params.jobId, workspaceId),
    getWorkspaceDepartments(workspaceId),
  ]);

  if (!job) {
    notFound();
  }

  return (
    <div className="mx-auto max-w-[1200px] space-y-6 pb-24 text-[#18221E]">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-xs text-[#65706A]">
        <Link href="/app" className="hover:text-[#18221E]">
          {workspace?.name || "Workspace"}
        </Link>
        <span>/</span>
        <Link href="/app/people" className="hover:text-[#18221E]">
          People
        </Link>
        <span>/</span>
        <span className="font-semibold text-[#18221E]">{job.title}</span>
      </div>

      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 rounded-[16px] border border-[#D8DDD4] bg-white p-6 shadow-2xs">
        <div>
          <div className="flex items-center gap-2.5">
            <h1 className="text-2xl font-bold tracking-tight text-[#18221E]">{job.title}</h1>
            <span
              className={`rounded-full border px-2.5 py-0.5 text-xs font-semibold ${
                job.status === "Open"
                  ? "bg-[#EAF4E2] text-[#246244] border-[#246244]/20"
                  : "bg-stone-100 text-stone-700 border-stone-200"
              }`}
            >
              {job.status}
            </span>
          </div>
          <p className="mt-1 text-xs text-[#65706A]">
            {job.department_name || "General Department"} • {job.employment_type} • {job.location}
          </p>
        </div>

        <div className="flex items-center gap-2">
          <ShareJobButton jobId={job.id} isPublic={job.status === "Open"} />
          <Link
            href="/app/people"
            className="rounded-[8px] border border-[#D8DDD4] bg-white px-3.5 py-1.5 text-xs font-semibold text-[#18221E] hover:bg-[#FAF9F5]"
          >
            ← Back to People
          </Link>
        </div>
      </div>

      {/* Metrics Row */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="rounded-[12px] border border-[#D8DDD4] bg-white p-4 shadow-2xs">
          <span className="text-[10px] font-bold uppercase tracking-wider text-[#65706A] block">
            Total Applicants
          </span>
          <p className="text-2xl font-bold tracking-tight text-[#18221E] mt-1">
            {job.applicants_count || 0}
          </p>
        </div>

        <div className="rounded-[12px] border border-[#D8DDD4] bg-white p-4 shadow-2xs">
          <span className="text-[10px] font-bold uppercase tracking-wider text-[#65706A] block">
            Interviews Conducted
          </span>
          <p className="text-2xl font-bold tracking-tight text-[#18221E] mt-1">
            {job.interviews_count || 0}
          </p>
        </div>

        <div className="rounded-[12px] border border-[#D8DDD4] bg-white p-4 shadow-2xs">
          <span className="text-[10px] font-bold uppercase tracking-wider text-[#65706A] block">
            Compensation Range
          </span>
          <p className="text-lg font-bold tracking-tight text-[#18221E] mt-1">
            {job.salary_range || "Not specified"}
          </p>
        </div>
      </div>

      {/* Job Details Content */}
      <div className="rounded-[16px] border border-[#D8DDD4] bg-white p-6 shadow-2xs space-y-6 text-xs text-[#18221E]">
        {job.description && (
          <div className="space-y-2">
            <h3 className="text-sm font-bold text-[#18221E]">About the Role</h3>
            <p className="text-xs text-[#65706A] leading-relaxed whitespace-pre-wrap">
              {job.description}
            </p>
          </div>
        )}

        {job.responsibilities && job.responsibilities.length > 0 && (
          <div className="space-y-2">
            <h3 className="text-sm font-bold text-[#18221E]">Key Responsibilities</h3>
            <ul className="list-disc list-inside space-y-1 text-[#65706A]">
              {job.responsibilities.map((resp, i) => (
                <li key={i}>{resp}</li>
              ))}
            </ul>
          </div>
        )}

        {job.requirements && job.requirements.length > 0 && (
          <div className="space-y-2">
            <h3 className="text-sm font-bold text-[#18221E]">Requirements & Qualifications</h3>
            <ul className="list-disc list-inside space-y-1 text-[#65706A]">
              {job.requirements.map((req, i) => (
                <li key={i}>{req}</li>
              ))}
            </ul>
          </div>
        )}

        {job.skills && job.skills.length > 0 && (
          <div className="space-y-2">
            <h3 className="text-sm font-bold text-[#18221E]">Required Skills</h3>
            <div className="flex flex-wrap gap-1.5">
              {job.skills.map((skill) => (
                <span
                  key={skill}
                  className="rounded-[6px] border border-[#D8DDD4] bg-[#FAF9F5] px-2 py-0.5 text-xs font-semibold text-[#18221E]"
                >
                  {skill}
                </span>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import * as React from "react";
import { getDefaultWorkspace } from "@/lib/workspace/queries";
import {
  getWorkspacePeople,
  getWorkspaceMemberProjectsAndActivitiesMaps,
  MemberActivitySummary,
  MemberProjectSummary,
} from "@/lib/people/queries";
import { getWorkspaceDepartments } from "@/lib/department/queries";
import {
  getWorkspaceJobOpenings,
  getWorkspaceCandidates,
  getWorkspaceInterviews,
  getRecruitmentStats,
} from "@/lib/recruitment/queries";
import { getWorkspaceInvitations } from "@/lib/invitations/queries";
import { PeopleDirectory } from "@/components/app/people-directory";

export const dynamic = "force-dynamic";

export const metadata = {
  title: "People & Recruitment — Ropimo",
  description: "Manage your team, employee information, recruitment pipeline, job openings, and interviews.",
};

export default async function PeoplePage() {
  const workspace = await getDefaultWorkspace();
  const workspaceId = workspace?.id || "";

  if (!workspaceId) {
    return (
      <PeopleDirectory
        workspaceId=""
        workspaceName="brnnd"
        userRole="member"
        people={[]}
        departments={[]}
        invitations={[]}
        jobOpenings={[]}
        candidates={[]}
        interviews={[]}
        recruitmentStats={{
          openJobsCount: 0,
          activeCandidatesCount: 0,
          interviewsScheduledCount: 0,
          offersPendingCount: 0,
          hiredThisQuarterCount: 0,
        }}
      />
    );
  }

  const [
    people,
    departments,
    invitations,
    jobOpenings,
    candidates,
    interviews,
    recruitmentStats,
    { memberActivitiesMap, memberProjectsMap },
  ] = await Promise.all([
    getWorkspacePeople(workspaceId),
    getWorkspaceDepartments(workspaceId),
    getWorkspaceInvitations(workspaceId),
    getWorkspaceJobOpenings(workspaceId),
    getWorkspaceCandidates(workspaceId),
    getWorkspaceInterviews(workspaceId),
    getRecruitmentStats(workspaceId),
    getWorkspaceMemberProjectsAndActivitiesMaps(workspaceId),
  ]);

  return (
    <PeopleDirectory
      workspaceId={workspaceId}
      workspaceName={workspace?.name || "brnnd"}
      userRole={workspace?.role || "owner"}
      people={people}
      departments={departments}
      invitations={invitations}
      memberActivitiesMap={memberActivitiesMap}
      memberProjectsMap={memberProjectsMap}
      jobOpenings={jobOpenings}
      candidates={candidates}
      interviews={interviews}
      recruitmentStats={recruitmentStats}
    />
  );
}

import * as React from "react";
import { PageHeader } from "@/components/app/page-header";
import { getDefaultWorkspace } from "@/lib/workspace/queries";
import { WorkspaceSettingsForm } from "@/components/app/settings/workspace-settings-form";

export const metadata = {
  title: "Workspace Settings — Ropimo",
  description: "Configure workspace name, details, and membership preferences.",
};

export default async function SettingsPage() {
  const workspace = await getDefaultWorkspace();

  const workspaceName = workspace?.name || "Workspace";
  const workspaceSlug = workspace?.slug || "workspace";
  const workspaceIcon = workspace?.icon && !/[\u{1F300}-\u{1F9FF}]/u.test(workspace.icon)
    ? workspace.icon
    : workspaceName[0]?.toUpperCase() || "W";
  const workspaceRole = workspace?.role
    ? workspace.role.charAt(0).toUpperCase() + workspace.role.slice(1)
    : "Owner";
  const createdDate = workspace?.created_at
    ? new Date(workspace.created_at).toLocaleDateString("en-US", {
        month: "short",
        day: "numeric",
        year: "numeric",
      })
    : "Recently";

  return (
    <div className="space-y-8">
      <PageHeader
        title="Workspace Settings"
        description="Configure workspace name, details, and membership preferences."
      />

      <WorkspaceSettingsForm
        initialWorkspace={{
          id: workspace?.id || "",
          name: workspaceName,
          slug: workspaceSlug,
          logoUrl: (workspace as any)?.logo_url || null,
          icon: workspaceIcon,
          role: workspaceRole,
          createdAt: createdDate,
        }}
      />
    </div>
  );
}

import * as React from "react";
import Link from "next/link";
import { notFound } from "next/navigation";
import { Metadata } from "next";
import { getPublicJobById } from "@/lib/recruitment/public-queries";
import { PublicApplyForm } from "@/components/public/public-apply-form";
import { LogoIcon } from "@/components/landing/icons";

interface Props {
  params: Promise<{ jobId: string }>;
}

export async function generateMetadata(props: Props): Promise<Metadata> {
  const params = await props.params;
  const job = await getPublicJobById(params.jobId);

  if (!job) {
    return {
      title: "Apply for Position — Careers",
    };
  }

  return {
    title: `Apply for ${job.title} — Careers at ${job.company_name || "Ropimo"}`,
    description: `Submit your candidate application and resume for the ${job.title} position.`,
  };
}

export default async function PublicJobApplyPage(props: Props) {
  const params = await props.params;
  const job = await getPublicJobById(params.jobId);

  if (!job) {
    return (
      <div className="min-h-screen bg-[#F4F3EE] flex flex-col justify-between text-[#18221E]">
        <header className="border-b border-[#D8DDD4] bg-white h-16 flex items-center px-6">
          <Link href="/jobs" className="flex items-center gap-2">
            <LogoIcon size={24} />
            <span className="font-bold">Ropimo Careers</span>
          </Link>
        </header>

        <div className="mx-auto max-w-md p-8 rounded-[16px] border border-[#D8DDD4] bg-white text-center space-y-3 shadow-2xs">
          <h1 className="text-xl font-bold">Position Unavailable</h1>
          <p className="text-xs text-[#65706A]">
            This position is no longer accepting public applications.
          </p>
          <div className="pt-2">
            <Link
              href="/jobs"
              className="inline-block rounded-[10px] bg-[#10251F] text-white px-4 py-2 text-xs font-semibold"
            >
              View Open Positions →
            </Link>
          </div>
        </div>

        <footer className="py-6 text-center text-xs text-[#65706A]">
          © {new Date().getFullYear()} Ropimo Inc.
        </footer>
      </div>
    );
  }

  return <PublicApplyForm job={job} />;
}

import * as React from "react";
import Link from "next/link";
import { notFound } from "next/navigation";
import { Metadata } from "next";
import { getPublicJobById } from "@/lib/recruitment/public-queries";
import { PublicJobDetail } from "@/components/public/public-job-detail";
import { LogoIcon } from "@/components/landing/icons";

interface Props {
  params: Promise<{ jobId: string }>;
}

export async function generateMetadata(props: Props): Promise<Metadata> {
  const params = await props.params;
  const job = await getPublicJobById(params.jobId);

  if (!job) {
    return {
      title: "Position Not Found — Careers",
    };
  }

  return {
    title: `${job.title} — Careers at ${job.company_name || "Ropimo"}`,
    description:
      job.description?.substring(0, 160) ||
      `Apply for the ${job.title} position at ${job.company_name || "Ropimo"}. ${job.location} • ${job.employment_type}`,
  };
}

export default async function PublicJobDetailPage(props: Props) {
  const params = await props.params;
  const job = await getPublicJobById(params.jobId);

  if (!job) {
    return (
      <div className="min-h-screen bg-[#F4F3EE] flex flex-col justify-between text-[#18221E]">
        <header className="border-b border-[#D8DDD4] bg-white h-16 flex items-center px-6">
          <Link href="/jobs" className="flex items-center gap-2">
            <LogoIcon size={24} />
            <span className="font-bold">Ropimo Careers</span>
          </Link>
        </header>

        <div className="mx-auto max-w-md p-8 rounded-[16px] border border-[#D8DDD4] bg-white text-center space-y-3 shadow-2xs">
          <h1 className="text-xl font-bold">Position Unavailable</h1>
          <p className="text-xs text-[#65706A]">
            This job opening is either closed, in draft, or no longer accepting applications.
          </p>
          <div className="pt-2">
            <Link
              href="/jobs"
              className="inline-block rounded-[10px] bg-[#10251F] text-white px-4 py-2 text-xs font-semibold"
            >
              Explore Open Positions →
            </Link>
          </div>
        </div>

        <footer className="py-6 text-center text-xs text-[#65706A]">
          © {new Date().getFullYear()} Ropimo Inc.
        </footer>
      </div>
    );
  }

  return <PublicJobDetail job={job} />;
}

"use client";

import * as React from "react";
import { motion, AnimatePresence } from "motion/react";
import { useRouter } from "next/navigation";
import { WorkspacePerson } from "@/types/people";
import { DepartmentRole } from "@/types/department";
import { addDepartmentMemberAction } from "@/lib/department/actions";
import { PrimaryButton } from "@/components/ui/primary-button";

export interface AddDepartmentMemberModalProps {
  isOpen: boolean;
  onClose: () => void;
  departmentId: string;
  departmentName: string;
  workspaceId: string;
  availablePeople: WorkspacePerson[];
  onSuccess?: () => void;
}

function AddDepartmentMemberForm({
  departmentId,
  departmentName,
  workspaceId,
  availablePeople,
  onClose,
  onSuccess,
}: {
  departmentId: string;
  departmentName: string;
  workspaceId: string;
  availablePeople: WorkspacePerson[];
  onClose: () => void;
  onSuccess?: () => void;
}) {
  const router = useRouter();

  const [selectedUserId, setSelectedUserId] = React.useState(
    availablePeople[0]?.user_id || ""
  );
  const [role, setRole] = React.useState<DepartmentRole>("member");
  const [jobTitle, setJobTitle] = React.useState("");
  const [loading, setLoading] = React.useState(false);
  const [errorMsg, setErrorMsg] = React.useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedUserId || loading) return;

    setLoading(true);
    setErrorMsg(null);

    try {
      const res = await addDepartmentMemberAction({
        departmentId,
        workspaceId,
        userId: selectedUserId,
        role,
        jobTitle: jobTitle?.trim() || undefined,
      });

      if (!res.success) {
        setErrorMsg(res.error || "Failed to add member.");
        setLoading(false);
        return;
      }

      onClose();
      router.refresh();
      if (onSuccess) onSuccess();
    } catch (err: any) {
      setErrorMsg(err?.message || "An unexpected error occurred.");
      setLoading(false);
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.96, y: 10 }}
      animate={{ opacity: 1, scale: 1, y: 0 }}
      exit={{ opacity: 0, scale: 0.96, y: 10 }}
      transition={{ duration: 0.2, ease: [0.25, 0.1, 0.25, 1] }}
      className="relative w-full max-w-md rounded-[18px] border border-[#D8DDD4] bg-white p-6 sm:p-8 shadow-xl text-[#18221E] my-8"
    >
      {/* Header */}
      <div className="flex items-center justify-between pb-4 border-b border-[#D8DDD4]">
        <div>
          <h3 className="text-xl font-bold tracking-tight text-[#18221E]">
            Add to {departmentName}
          </h3>
          <p className="mt-0.5 text-xs text-[#65706A]">
            Assign an existing workspace member to this department workspace.
          </p>
        </div>

        <button
          type="button"
          onClick={onClose}
          className="rounded-[8px] p-1.5 text-[#65706A] hover:bg-[#FAF9F5] hover:text-[#18221E] transition-colors focus:outline-none"
        >
          <svg
            width="18"
            height="18"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <line x1="18" y1="6" x2="6" y2="18" />
            <line x1="6" y1="6" x2="18" y2="18" />
          </svg>
        </button>
      </div>

      {/* Error Message */}
      <AnimatePresence>
        {errorMsg && (
          <motion.div
            initial={{ opacity: 0, y: -6 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -6 }}
            className="mt-4 rounded-[10px] border border-red-200 bg-red-50 p-3 text-xs font-medium text-red-800"
          >
            {errorMsg}
          </motion.div>
        )}
      </AnimatePresence>

      {availablePeople.length === 0 ? (
        <div className="py-6 text-center text-xs text-[#65706A]">
          All workspace members are already assigned to this department.
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="mt-5 space-y-4">
          <div>
            <label
              htmlFor="selectMember"
              className="block text-xs font-semibold uppercase tracking-wider text-[#65706A] mb-1.5"
            >
              Select Person
            </label>
            <select
              id="selectMember"
              value={selectedUserId}
              onChange={(e) => setSelectedUserId(e.target.value)}
              className="w-full rounded-[10px] border border-[#D8DDD4] bg-[#FAF9F5] px-3.5 py-2 text-xs font-medium text-[#18221E] focus:border-[#10251F] focus:bg-white focus:outline-none transition-colors"
            >
              {availablePeople.map((p) => (
                <option key={p.user_id} value={p.user_id}>
                  {p.full_name || p.email} ({p.role})
                </option>
              ))}
            </select>
          </div>

          <div>
            <label
              htmlFor="deptRole"
              className="block text-xs font-semibold uppercase tracking-wider text-[#65706A] mb-1.5"
            >
              Department Role
            </label>
            <select
              id="deptRole"
              value={role}
              onChange={(e) => setRole(e.target.value as DepartmentRole)}
              className="w-full rounded-[10px] border border-[#D8DDD4] bg-[#FAF9F5] px-3.5 py-2 text-xs font-medium text-[#18221E] focus:border-[#10251F] focus:bg-white focus:outline-none transition-colors"
            >
              <option value="member">Member — Standard access to tasks & work</option>
              <option value="manager">Manager — Can create projects & assign tasks</option>
              <option value="lead">Department Lead — Full department leadership</option>
            </select>
          </div>

          <div>
            <label
              htmlFor="deptRoleTitle"
              className="block text-xs font-semibold uppercase tracking-wider text-[#65706A] mb-1.5"
            >
              Role Title (optional)
            </label>
            <input
              id="deptRoleTitle"
              type="text"
              value={jobTitle}
              onChange={(e) => setJobTitle(e.target.value)}
              placeholder="e.g. Senior Backend Engineer, Lead Product Designer"
              className="w-full rounded-[10px] border border-[#D8DDD4] bg-[#FAF9F5] px-3.5 py-2 text-sm text-[#18221E] placeholder:text-[#65706A]/60 focus:border-[#10251F] focus:bg-white focus:outline-none transition-colors"
            />
          </div>

          <div className="flex items-center justify-end gap-3 pt-4 border-t border-[#D8DDD4]">
            <button
              type="button"
              onClick={onClose}
              className="rounded-[10px] px-4 py-2 text-xs font-semibold text-[#65706A] hover:bg-[#FAF9F5] hover:text-[#18221E] transition-colors"
            >
              Cancel
            </button>
            <PrimaryButton
              type="submit"
              size="sm"
              disabled={loading || !selectedUserId}
            >
              {loading ? "Adding..." : "Add to Department"}
            </PrimaryButton>
          </div>
        </form>
      )}
    </motion.div>
  );
}

