                ]}
              />

              {/* Status Filter */}
              <RopimoSelect
                value={selectedStatus}
                onChange={(val) => setSelectedStatus(val)}
                options={[
                  { value: "all", label: "All Statuses" },
                  { value: "Present", label: "Present" },
                  { value: "Late", label: "Late" },
                  { value: "On Leave", label: "On Leave" },
                  { value: "Absent", label: "Absent" },
