                      <th className="py-3 px-4 font-bold">DATE</th>
                      <th className="py-3 px-4 font-bold text-center">STATUS</th>
                      <th className="py-3 px-4 font-bold">CHECK IN</th>
                      <th className="py-3 px-4 font-bold">CHECK OUT</th>
