                  {weekGridDays.map((col) => (
                    <div
                      key={col.dateString}
                      className={cn(
                        "flex flex-col items-center gap-0.5 py-1 px-2 rounded-md mx-1",
                        col.isToday ? "bg-[#E7EADF]/60" : ""
                      )}
                    >
                      <span className="uppercase tracking-wider text-[10px] font-bold text-[#65706A]">
                        {col.dayName}
                      </span>
                      <span
                        className={cn(
