                      >
                        {col.dayNumber}
                      </span>
                    </div>
                  ))}
                </div>

                {/* Week Columns */}
                <div className="grid grid-cols-7 divide-x divide-[#D8DDD4] min-h-[500px] p-2 bg-[#FAF9F5]/30">
                  {weekGridDays.map((col) => (
                    <div
