                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-[#18221E] mb-1">
                  Date *
                </label>
                <DatePicker
                  value={startDate}
                  onChange={(val) => {
                    setStartDate(val);
                    setEndDate(val);
                  }}
