function CreateDocumentModal({
  isOpen,
  onClose,
  workspaceId,
  projects,
  departments,
  onSuccess,
}: {
  isOpen: boolean;
  onClose: () => void;
  workspaceId: string;
  projects: Project[];
  departments: Department[];
  onSuccess: (newDoc: DocumentItem) => void;
}) {
  const [title, setTitle] = React.useState("");
  const [subtitle, setSubtitle] = React.useState("");
  const [category, setCategory] = React.useState<DocumentCategory>("HR");
  const [departmentId, setDepartmentId] = React.useState("");
  const [projectId, setProjectId] = React.useState("");
  const [accessLevel, setAccessLevel] = React.useState<DocumentAccessLevel>("company");
  const [content, setContent] = React.useState("");
  const [loading, setLoading] = React.useState(false);

  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    if (isOpen) window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose]);

  const handleSubmit = async (publishStatus: DocumentStatus = "Published") => {
    if (!title.trim()) return;
    setLoading(true);

    try {
      const result = await createDocumentAction({
        workspaceId,
        title: title.trim(),
        subtitle: subtitle.trim() || undefined,
        content: content || `# ${title.trim()}\n\nStart writing here...`,
        category,
        status: publishStatus,
        departmentId: departmentId || undefined,
        projectId: projectId || undefined,
        accessLevel,
      });

      if (result.success && result.document) {
        onSuccess(result.document);
      } else {
        console.error("Create document failed:", result.error);
        // Still close modal so user isn't stuck
        onSuccess({
          id: `local-${Date.now()}`,
          workspace_id: workspaceId,
          title: title.trim(),
          subtitle: subtitle.trim() || null,
          description: subtitle.trim() || null,
          content: content || `# ${title.trim()}\n\nStart writing here...`,
          category,
          status: publishStatus,
          department_id: departmentId || null,
          department_name: departments.find((d) => d.id === departmentId)?.name || null,
          project_id: projectId || null,
          project_name: projects.find((p) => p.id === projectId)?.name || null,
          author_id: null,
          author_name: "You",
          author_avatar: null,
          access_level: accessLevel,
          word_count: (content || "").split(/\s+/).filter(Boolean).length || 5,
          read_time_minutes: 1,
          last_updated: "Just now",
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
          versions: [],
          comments: [],
        });
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

