                </div>
                <div>
                  <p className="text-[10px] font-semibold uppercase tracking-wider text-[#65706A] leading-none mb-0.5">Location</p>
                  <p className="text-xs font-medium text-[#18221E]">
                    {meeting.location_type === "Physical"
