"use client";

import * as React from "react";
import { useRouter } from "next/navigation";
import {
  Bell,
  Check,
  CheckCheck,
  CheckSquare,
  CalendarDays,
  FolderKanban,
  UserCheck,
  Video,
  X,
  ArrowRight,
  ExternalLink,
  Sparkles,
  Inbox,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { AppNotification, NotificationFilterTab, NotificationCategory } from "@/types/notification";
import {
  markNotificationReadAction,
  markAllNotificationsReadAction,
  dismissNotificationAction,
  clearAllNotificationsAction,
} from "@/lib/notifications/actions";

export interface NotificationCenterProps {
  workspaceId: string;
  initialNotifications?: AppNotification[];
  isOpen: boolean;
  onClose: () => void;
}

export function NotificationCenter({
  workspaceId,
  initialNotifications = [],
  isOpen,
  onClose,
}: NotificationCenterProps) {
  const router = useRouter();
  const [notifications, setNotifications] = React.useState<AppNotification[]>(initialNotifications);
  const [activeTab, setActiveTab] = React.useState<NotificationFilterTab>("all");

  // Sync initial notifications if updated
  React.useEffect(() => {
    if (initialNotifications && initialNotifications.length > 0) {
      setNotifications(initialNotifications);
    }
  }, [initialNotifications]);

  const unreadCount = notifications.filter((n) => !n.read).length;

  const handleMarkAllRead = async () => {
    // Optimistic UI update
    setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
    await markAllNotificationsReadAction(workspaceId);
  };

  const handleDismissNotification = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    // Optimistic UI update
    setNotifications((prev) => prev.filter((n) => n.id !== id));
    await dismissNotificationAction(id, workspaceId);
  };

  const handleItemClick = async (notif: AppNotification) => {
    if (!notif.read) {
      setNotifications((prev) =>
        prev.map((n) => (n.id === notif.id ? { ...n, read: true } : n))
      );
      markNotificationReadAction(notif.id, workspaceId);
    }
    onClose();
    if (notif.action_url) {
      router.push(notif.action_url);
    }
  };

  const handleClearAll = async () => {
    setNotifications([]);
    await clearAllNotificationsAction(workspaceId);
  };

  // Filtered notifications
  const filteredNotifications = React.useMemo(() => {
    if (activeTab === "unread") return notifications.filter((n) => !n.read);
    if (activeTab === "requests") {
      return notifications.filter((n) =>
        n.type === "leave_requested" ||
        n.type === "leave_approved" ||
        n.type === "leave_rejected" ||
        n.type === "invitation_accepted"
      );
    }
    return notifications;
  }, [notifications, activeTab]);

  // Group by category (Today, Yesterday, Older)
  const groupedNotifications = React.useMemo(() => {
    const today: AppNotification[] = [];
    const yesterday: AppNotification[] = [];
    const older: AppNotification[] = [];

    for (const notif of filteredNotifications) {
      const cat = notif.category || "today";
      if (cat === "today") today.push(notif);
      else if (cat === "yesterday") yesterday.push(notif);
      else older.push(notif);
    }

    return { today, yesterday, older };
  }, [filteredNotifications]);

  const getNotifIcon = (type: AppNotification["type"]) => {
    switch (type) {
      case "task_assigned":
        return (
          <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-[7px] border border-[#C2E0C8] bg-[#EAF4E2] text-[#246244]">
            <CheckSquare className="h-3.5 w-3.5" />
          </div>
        );
      case "project_member_added":
        return (
          <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-[7px] border border-[#BFDBFE] bg-[#EBF3FE] text-[#1E40AF]">
            <FolderKanban className="h-3.5 w-3.5" />
          </div>
        );
      case "leave_requested":
      case "leave_approved":
      case "leave_rejected":
        return (
          <div
            className={cn(
              "flex h-7 w-7 shrink-0 items-center justify-center rounded-[7px] border text-xs",
              type === "leave_approved"
                ? "border-[#C2E0C8] bg-[#EAF4E2] text-[#246244]"
                : type === "leave_rejected"
                ? "border-[#FECACA] bg-[#FEF2F2] text-[#DC2626]"
                : "border-[#FDE68A] bg-[#FEF9C3] text-[#B45309]"
            )}
          >
            <CalendarDays className="h-3.5 w-3.5" />
          </div>
        );
      case "invitation_accepted":
        return (
          <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-[7px] border border-[#E9D5FF] bg-[#F3E8FF] text-[#6B21A8]">
            <UserCheck className="h-3.5 w-3.5" />
          </div>
        );
      case "meeting_scheduled":
        return (
          <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-[7px] border border-[#F8E3B6] bg-[#FEF6E4] text-[#B58500]">
            <Video className="h-3.5 w-3.5" />
          </div>
        );
      default:
        return (
          <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-[7px] border border-[#D8DDD4] bg-[#FAF9F5] text-[#65706A]">
            <Bell className="h-3.5 w-3.5" />
          </div>
        );
    }
  };

  const renderSection = (title: string, items: AppNotification[]) => {
    if (items.length === 0) return null;
    return (
      <div key={title} className="space-y-1">
        <div className="px-2 pt-2 pb-1">
          <p className="text-[10px] font-bold uppercase tracking-wider text-[#8A958F]">{title}</p>
        </div>
        <div className="space-y-0.5">
          {items.map((notif) => {
            const isUnread = !notif.read;
            return (
              <div
                key={notif.id}
                onClick={() => handleItemClick(notif)}
                className={cn(
                  "group relative flex items-start gap-3 p-2.5 rounded-[10px] transition-all cursor-pointer text-xs",
                  isUnread ? "bg-[#FAF9F5] hover:bg-[#F4F3EE]" : "hover:bg-[#FAF9F5]"
                )}
              >
                {getNotifIcon(notif.type)}

                <div className="flex-1 min-w-0 space-y-0.5">
                  <div className="flex items-center justify-between gap-1">
                    <p
                      className={cn(
                        "text-xs truncate",
                        isUnread ? "font-bold text-[#18221E]" : "font-medium text-[#18221E]"
                      )}
                    >
                      {notif.title}
                    </p>
                    {isUnread && (
                      <span className="h-1.5 w-1.5 rounded-full bg-[#246244] shrink-0" />
                    )}
                  </div>

                  {notif.subtitle && (
                    <p className="text-[11px] text-[#65706A] leading-tight line-clamp-2">
                      {notif.subtitle}
                    </p>
                  )}

                  <div className="flex items-center justify-between pt-0.5">
                    <span className="text-[10px] text-[#8A958F]">
                      {notif.time_ago || "recently"}
                    </span>
                    <span className="inline-flex items-center gap-0.5 text-[10px] font-semibold text-[#246244] opacity-0 group-hover:opacity-100 transition-opacity">
                      <span>View</span>
                      <ArrowRight className="h-2.5 w-2.5" />
                    </span>
                  </div>
                </div>

                {/* Quick Dismiss Button */}
                <button
                  type="button"
                  onClick={(e) => handleDismissNotification(e, notif.id)}
                  className="opacity-0 group-hover:opacity-100 rounded-[4px] p-0.5 text-[#8A958F] hover:text-[#D9383A] hover:bg-white transition-all shrink-0 ml-0.5 cursor-pointer"
                  aria-label="Dismiss notification"
                  title="Dismiss"
                >
                  <X className="h-3 w-3" />
                </button>
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  if (!isOpen) return null;

  return (
    <div className="absolute right-0 top-full mt-2 z-40 w-88 sm:w-96 rounded-[16px] border border-[#D8DDD4] bg-white p-3.5 shadow-elevated animate-in zoom-in-95 duration-150 space-y-3">
      {/* Header with Title, Unread Badge, and Mark All Read */}
      <div className="flex items-center justify-between pb-2 border-b border-[#E7EADF]">
        <div className="flex items-center gap-2">
          <span className="text-xs font-bold text-[#18221E]">Notifications</span>
          {unreadCount > 0 ? (
            <span className="text-[10px] font-bold text-[#246244] bg-[#EAF4E2] px-2 py-0.5 rounded-full border border-[#C2E0C8]">
              {unreadCount} new
            </span>
          ) : (
            <span className="text-[10px] font-medium text-[#65706A] bg-[#F4F3EE] px-2 py-0.5 rounded-full border border-[#D8DDD4]">
              All caught up
            </span>
          )}
        </div>

        {unreadCount > 0 && (
          <button
            type="button"
            onClick={handleMarkAllRead}
            className="inline-flex items-center gap-1 text-[11px] font-semibold text-[#65706A] hover:text-[#18221E] transition-colors cursor-pointer"
          >
            <CheckCheck className="h-3.5 w-3.5 text-[#246244]" />
            <span>Mark read</span>
          </button>
        )}
      </div>

      {/* Filter Tabs */}
      <div className="flex items-center gap-1 rounded-[8px] bg-[#FAF9F5] p-0.5 border border-[#D8DDD4] text-[11px]">
        <button
          type="button"
          onClick={() => setActiveTab("all")}
          className={cn(
            "flex-1 py-1 text-center font-medium rounded-[6px] transition-all cursor-pointer",
            activeTab === "all"
              ? "bg-white text-[#18221E] font-bold shadow-2xs"
              : "text-[#65706A] hover:text-[#18221E]"
          )}
        >
          All ({notifications.length})
        </button>
        <button
          type="button"
          onClick={() => setActiveTab("unread")}
          className={cn(
            "flex-1 py-1 text-center font-medium rounded-[6px] transition-all cursor-pointer",
            activeTab === "unread"
              ? "bg-white text-[#18221E] font-bold shadow-2xs"
              : "text-[#65706A] hover:text-[#18221E]"
          )}
        >
          Unread ({unreadCount})
        </button>
        <button
          type="button"
          onClick={() => setActiveTab("requests")}
          className={cn(
            "flex-1 py-1 text-center font-medium rounded-[6px] transition-all cursor-pointer",
            activeTab === "requests"
              ? "bg-white text-[#18221E] font-bold shadow-2xs"
              : "text-[#65706A] hover:text-[#18221E]"
          )}
        >
          Requests
        </button>
      </div>

      {/* Notification Items List grouped by Time */}
      <div className="max-h-[340px] overflow-y-auto space-y-2 divide-y divide-[#E7EADF] pr-0.5">
        {filteredNotifications.length === 0 ? (
          <div className="py-10 flex flex-col items-center justify-center text-center">
            <div className="h-9 w-9 rounded-full bg-[#FAF9F5] border border-[#E7EADF] flex items-center justify-center mb-2">
              <Inbox className="h-4 w-4 text-[#8A958F]" />
            </div>
            <p className="text-xs font-semibold text-[#18221E]">
              {activeTab === "unread" ? "No unread notifications" : "No notifications"}
            </p>
            <p className="text-[11px] text-[#65706A] mt-0.5">
              {activeTab === "unread"
                ? "You've read all your updates."
                : "New task, project, and leave notifications will appear here."}
            </p>
          </div>
        ) : (
          <>
            {renderSection("Today", groupedNotifications.today)}
            {renderSection("Yesterday", groupedNotifications.yesterday)}
            {renderSection("Older", groupedNotifications.older)}
          </>
        )}
      </div>

      {/* Footer Actions */}
      <div className="pt-2 border-t border-[#E7EADF] flex items-center justify-between text-[11px]">
        <button
          type="button"
          onClick={() => {
            onClose();
            router.push("/app");
          }}
          className="font-bold text-[#246244] hover:underline cursor-pointer"
        >
          Workspace overview →
        </button>

        {notifications.length > 0 && (
          <button
            type="button"
            onClick={handleClearAll}
            className="text-[#8A958F] hover:text-[#18221E] transition-colors cursor-pointer"
          >
            Clear all
          </button>
        )}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  Plus,
  Check,
  Calendar,
  User,
  MoreHorizontal,
  ChevronRight,
  Clock,
  Video,
} from "lucide-react";
import { Project } from "@/types/project";
import { Task } from "@/types/task";
import { WorkspacePerson } from "@/types/people";
import { Department } from "@/types/department";
import { LeaveRequest } from "@/types/leave";
import { CalendarEvent } from "@/types/calendar";
import { JobOpening, Interview, Candidate } from "@/types/recruitment";
import { WorkspaceActivityItem } from "@/lib/task/queries";
import { toggleTaskCompletionAction } from "@/lib/task/actions";
import { toast } from "sonner";
import { CreateProjectModal } from "@/components/app/create-project-modal";
import { CreateTaskModal } from "@/components/app/create-task-modal";
import { TaskPeekPanel } from "@/components/app/task-peek-panel";
import {
  Button,
  IconButton,
  Avatar,
  AvatarStack,
  Kbd,
  Tabs,
  StatusDot,
  Tooltip,
  EmptyLine,
} from "@/components/app/ui";

export interface OverviewDashboardProps {
  workspaceId: string;
  workspaceName: string;
  userId?: string;
  userName?: string;
  userEmail?: string;
  projects: Project[];
  myOpenTasks: Task[];
  allTasks?: Task[];
  openTasksCount: number;
  dueTodayCount: number;
  overdueCount: number;
  completedCount: number;
  people: WorkspacePerson[];
  departments: Department[];
  recentActivities?: WorkspaceActivityItem[];
  upcomingDeadlines?: Task[];
  jobOpenings?: JobOpening[];
  openJobsCount?: number;
  pendingLeaves?: LeaveRequest[];
  pendingLeavesCount?: number;
  candidates?: Candidate[];
  interviews?: Interview[];
  upcomingEvents?: CalendarEvent[];
}

export function OverviewDashboard({
  workspaceId,
  workspaceName,
  userId,
  userName = "there",
  userEmail,
  projects = [],
  myOpenTasks = [],
  allTasks = [],
  openTasksCount = 0,
  dueTodayCount = 0,
  overdueCount = 0,
  completedCount = 0,
  people = [],
  departments = [],
  recentActivities = [],
  upcomingDeadlines = [],
  jobOpenings = [],
  openJobsCount = 0,
  pendingLeaves = [],
  pendingLeavesCount = 0,
  candidates = [],
  interviews = [],
  upcomingEvents = [],
}: OverviewDashboardProps) {
  const router = useRouter();

  // Modals and Peek state
  const [createTaskModalOpen, setCreateTaskModalOpen] = React.useState(false);
  const [createProjectModalOpen, setCreateProjectModalOpen] = React.useState(false);
  const [selectedTask, setSelectedTask] = React.useState<Task | null>(null);

  // Active Tab in left column: Tasks / Projects / Approvals
  const [activeTab, setActiveTab] = React.useState<string>("tasks");

  // Local task list for instant optimistic completion updates
  const [tasks, setTasks] = React.useState<Task[]>(
    myOpenTasks.length > 0 ? myOpenTasks : allTasks
  );

  React.useEffect(() => {
    setTasks(myOpenTasks.length > 0 ? myOpenTasks : allTasks);
  }, [myOpenTasks, allTasks]);

  // Global 'C' shortcut to create task
  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement;
      if (
        target.tagName === "INPUT" ||
        target.tagName === "TEXTAREA" ||
        target.isContentEditable
      ) {
        return;
      }
      if (e.key.toLowerCase() === "c" && !e.metaKey && !e.ctrlKey) {
        e.preventDefault();
        setCreateTaskModalOpen(true);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  // Format first name
  const firstName = userName.trim().split(" ")[0] || "there";

  // Today's formatted date string e.g. "Friday, Oct 9"
  const formattedTodayDate = React.useMemo(() => {
    return new Date().toLocaleDateString("en-US", {
      weekday: "long",
      month: "short",
      day: "numeric",
    });
  }, []);

  // Toggle completion optimistically
  const handleToggleTask = async (task: Task, e: React.MouseEvent) => {
    e.stopPropagation();
    const isCompleted = task.status === "completed";
    const nextStatus = isCompleted ? "todo" : "completed";

    setTasks((prev) =>
      prev.map((t) => (t.id === task.id ? { ...t, status: nextStatus } : t))
    );

    try {
      await toggleTaskCompletionAction(task.id, workspaceId, !isCompleted);
    } catch {
      // Rollback on error
      setTasks((prev) =>
        prev.map((t) => (t.id === task.id ? { ...t, status: task.status } : t))
      );
      toast.error("Failed to update task. Please try again.");
    }
  };

  // Group tasks into Overdue, Today, Upcoming
  const { overdueTasks, todayTasks, upcomingTasks } = React.useMemo(() => {
    const now = new Date();
    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
    const endOfToday = startOfToday + 86400000;

    const overdue: Task[] = [];
    const today: Task[] = [];
    const upcoming: Task[] = [];

    const activeList = tasks.filter((t) => t.status !== "completed");

    for (const task of activeList) {
      if (!task.due_date) {
        upcoming.push(task);
        continue;
      }
      const due = new Date(task.due_date).getTime();
      if (due < startOfToday) {
        overdue.push(task);
      } else if (due >= startOfToday && due < endOfToday) {
        today.push(task);
      } else {
        upcoming.push(task);
      }
    }

    return {
      overdueTasks: overdue,
      todayTasks: today,
      upcomingTasks: upcoming,
    };
  }, [tasks]);

  // Tasks requiring approvals
  const approvalTasks = React.useMemo(() => {
    return tasks.filter((t) => t.requires_approval || t.status === "in_review");
  }, [tasks]);

  // Needs attention items: ONLY rendered if items exist!
  const attentionItems = React.useMemo(() => {
    const items: Array<{
      id: string;
      title: string;
      label: string;
      href: string;
    }> = [];

    if (overdueTasks.length > 0) {
      items.push({
        id: "overdue",
        title: `${overdueTasks.length} ${overdueTasks.length === 1 ? "task is" : "tasks are"} past due`,
        label: "Overdue",
        href: "/app/my-tasks",
      });
    }

    if (pendingLeavesCount > 0 || pendingLeaves.length > 0) {
      const count = pendingLeavesCount || pendingLeaves.length;
      items.push({
        id: "leaves",
        title: `${count} leave ${count === 1 ? "request" : "requests"} pending approval`,
        label: "Approval needed",
        href: "/app/leave",
      });
    }

    if (approvalTasks.length > 0) {
      items.push({
        id: "approvals",
        title: `${approvalTasks.length} ${approvalTasks.length === 1 ? "task waiting" : "tasks waiting"} for review`,
        label: "Deliverables",
        href: "/app/my-tasks",
      });
    }

    return items;
  }, [overdueTasks, pendingLeavesCount, pendingLeaves, approvalTasks]);

  // Today's meetings / events for "Up next"
  const todayEvents = React.useMemo(() => {
    if (!upcomingEvents || upcomingEvents.length === 0) return [];
    return upcomingEvents.slice(0, 4);
  }, [upcomingEvents]);

  // Format activity feed item text
  const formatActivityText = (act: WorkspaceActivityItem) => {
    const actor = act.actorName || "Team member";
    const target = act.targetName || "item";
    if (act.type === "task_completed") {
      return `${actor} completed ${target}`;
    }
    return `${actor} created ${target}`;
  };

  const tabsConfig = [
    { id: "tasks", label: "Tasks", count: tasks.filter((t) => t.status !== "completed").length },
    { id: "projects", label: "Projects", count: projects.length },
    { id: "approvals", label: "Approvals", count: approvalTasks.length },
  ];

  const renderTaskRow = (task: Task, isOverdue: boolean = false) => {
    const isCompleted = task.status === "completed";
    const projectColor = task.project?.color || "#7ED08A";
    const projectName = task.project?.name || "General";

    const formattedDue = task.due_date
      ? new Date(task.due_date).toLocaleDateString("en-US", {
          month: "short",
          day: "numeric",
        })
      : null;

    return (
      <div
        key={task.id}
        onClick={() => setSelectedTask(task)}
        className="group relative flex h-11 items-center justify-between border-b border-hairline px-2 text-[13px] hover:bg-hover transition-colors duration-120 cursor-pointer select-none rounded-lg"
      >
        {/* Left: Circle Checkbox + Title */}
        <div className="flex items-center gap-3 min-w-0 flex-1 pr-3">
          <button
            type="button"
            onClick={(e) => handleToggleTask(task, e)}
            className={`h-4 w-4 rounded-full border transition-colors duration-120 flex items-center justify-center shrink-0 cursor-pointer ${
              isCompleted
                ? "bg-ink border-ink text-white"
                : "border-hairline hover:border-ink bg-surface"
            }`}
            aria-label={isCompleted ? "Mark incomplete" : "Mark complete"}
          >
            {isCompleted && <Check className="h-2.5 w-2.5 stroke-[2]" />}
          </button>

          <span
            className={`truncate font-normal ${
              isCompleted ? "text-ink-3 line-through" : "text-ink"
            }`}
          >
            {task.title}
          </span>
        </div>

        {/* Middle/Right: Project dot + Due date + Hover actions */}
        <div className="flex items-center gap-4 shrink-0">
          {/* Project Color Dot + Name */}
          <div className="hidden sm:flex items-center gap-1.5 max-w-[120px] truncate">
            <span
              className="h-1.5 w-1.5 rounded-full shrink-0"
              style={{ backgroundColor: projectColor }}
              aria-hidden="true"
            />
            <span className="text-[12px] text-ink-2 truncate">{projectName}</span>
          </div>

          {/* Due date */}
          {formattedDue && (
            <span
              className={`text-[12px] tabular-nums ${
                isOverdue ? "text-status-overdue font-normal" : "text-ink-3"
              }`}
            >
              {formattedDue}
            </span>
          )}

          {/* Hover actions */}
          <div className="opacity-0 group-hover:opacity-100 transition-opacity duration-120 flex items-center gap-0.5">
            <Tooltip content="Assignee">
              <IconButton
                aria-label="Assignee"
                onClick={(e) => {
                  e.stopPropagation();
                  setSelectedTask(task);
                }}
              >
                <User className="h-3.5 w-3.5 stroke-[1.5]" />
              </IconButton>
            </Tooltip>
            <Tooltip content="Due date">
              <IconButton
                aria-label="Due date"
                onClick={(e) => {
                  e.stopPropagation();
                  setSelectedTask(task);
                }}
              >
                <Calendar className="h-3.5 w-3.5 stroke-[1.5]" />
              </IconButton>
            </Tooltip>
            <Tooltip content="More">
              <IconButton
                aria-label="More"
                onClick={(e) => {
                  e.stopPropagation();
                  setSelectedTask(task);
                }}
              >
                <MoreHorizontal className="h-3.5 w-3.5 stroke-[1.5]" />
              </IconButton>
            </Tooltip>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="mx-auto max-w-5xl px-8 py-6 space-y-8 font-sans text-ink">
      {/* 1. Header */}
      <header className="flex flex-col sm:flex-row sm:items-baseline justify-between gap-4 pb-2">
        <div className="flex items-baseline flex-wrap">
          <h1 className="text-[20px] font-semibold text-ink tracking-tight">
            Good morning, {firstName}
          </h1>
          <span className="text-[13px] font-normal text-ink-3 ml-3 tabular-nums select-none">
            {formattedTodayDate}
          </span>
        </div>

        {/* Right buttons: ONE black "New task" (with C hint) and ghost "New project" */}
        <div className="flex items-center gap-2 shrink-0">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setCreateProjectModalOpen(true)}
          >
            <span>New project</span>
          </Button>

          <Button
            variant="primary"
            size="sm"
            onClick={() => setCreateTaskModalOpen(true)}
            className="gap-2"
          >
            <Plus className="h-3.5 w-3.5 stroke-[1.5]" />
            <span>New task</span>
            <Kbd className="bg-white/20 text-white border-transparent">C</Kbd>
          </Button>
        </div>
      </header>

      {/* 2. Stat Strip: Single row, no card, no icons, 5 items separated by vertical hairlines */}
      <section className="grid grid-cols-2 sm:grid-cols-5 divide-y sm:divide-y-0 sm:divide-x divide-hairline border-y border-hairline py-3">
        {/* Item 1: Open tasks */}
        <Link
          href="/app/my-tasks"
          className="group block p-2 rounded-lg hover:bg-hover/60 transition-colors"
        >
          <div className="flex items-baseline">
            <span className="text-[24px] font-semibold text-ink tabular-nums leading-tight">
              {openTasksCount || tasks.filter((t) => t.status !== "completed").length}
            </span>
            {overdueCount > 0 && (
              <span className="text-[11px] text-status-overdue ml-2 tabular-nums">
                {overdueCount} overdue
              </span>
            )}
          </div>
          <p className="text-[12px] font-normal text-ink-2 mt-0.5">Open tasks</p>
        </Link>

        {/* Item 2: Due this week */}
        <Link
          href="/app/my-tasks"
          className="group block p-2 rounded-lg hover:bg-hover/60 transition-colors"
        >
          <div className="flex items-baseline">
            <span className="text-[24px] font-semibold text-ink tabular-nums leading-tight">
              {dueTodayCount || todayTasks.length}
            </span>
            {todayTasks.length > 0 && (
              <span className="text-[11px] text-ink-3 ml-2 tabular-nums">
                today
              </span>
            )}
          </div>
          <p className="text-[12px] font-normal text-ink-2 mt-0.5">Due this week</p>
        </Link>

        {/* Item 3: Active projects */}
        <Link
          href="/app/projects"
          className="group block p-2 rounded-lg hover:bg-hover/60 transition-colors"
        >
          <div className="flex items-baseline">
            <span className="text-[24px] font-semibold text-ink tabular-nums leading-tight">
              {projects.length}
            </span>
          </div>
          <p className="text-[12px] font-normal text-ink-2 mt-0.5">Active projects</p>
        </Link>

        {/* Item 4: Open roles */}
        <Link
          href="/app/people"
          className="group block p-2 rounded-lg hover:bg-hover/60 transition-colors"
        >
          <div className="flex items-baseline">
            <span className="text-[24px] font-semibold text-ink tabular-nums leading-tight">
              {openJobsCount || jobOpenings.length}
            </span>
            {candidates.length > 0 && (
              <span className="text-[11px] text-ink-3 ml-2 tabular-nums">
                +{candidates.length} candidates
              </span>
            )}
          </div>
          <p className="text-[12px] font-normal text-ink-2 mt-0.5">Open roles</p>
        </Link>

        {/* Item 5: Pending leave */}
        <Link
          href="/app/leave"
          className="group block p-2 rounded-lg hover:bg-hover/60 transition-colors"
        >
          <div className="flex items-baseline">
            <span className="text-[24px] font-semibold text-ink tabular-nums leading-tight">
              {pendingLeavesCount || pendingLeaves.length}
            </span>
          </div>
          <p className="text-[12px] font-normal text-ink-2 mt-0.5">Pending leave</p>
        </Link>
      </section>

      {/* 3. Two columns below (65% / 35%), separated by vertical hairline */}
      <section className="grid grid-cols-1 lg:grid-cols-12 gap-0 pt-2">
        {/* Left Column (65%): "My tasks" with Tabs */}
        <div className="lg:col-span-8 lg:pr-8 lg:border-r lg:border-hairline space-y-4">
          <div className="flex items-center justify-between pb-1">
            <h2 className="text-[14px] font-semibold text-ink">My tasks</h2>
          </div>

          {/* Underline Tabs: Tasks / Projects / Approvals */}
          <Tabs
            tabs={tabsConfig}
            activeId={activeTab}
            onChange={setActiveTab}
          />

          {/* Tab 1: Tasks list grouped by Overdue, Today, Upcoming */}
          {activeTab === "tasks" && (
            <div className="space-y-6 pt-2">
              {/* Group 1: Overdue */}
              {overdueTasks.length > 0 && (
                <div className="space-y-1">
                  <div className="flex items-center justify-between px-2 pb-1">
                    <span className="text-[12px] font-medium text-status-overdue">
                      Overdue ({overdueTasks.length})
                    </span>
                  </div>
                  <div>
                    {overdueTasks.map((task) => renderTaskRow(task, true))}
                  </div>
                  <button
                    type="button"
                    onClick={() => setCreateTaskModalOpen(true)}
                    className="h-8 flex items-center gap-2 px-2 text-[12px] text-ink-3 hover:text-ink hover:bg-hover/60 rounded-lg cursor-pointer transition-colors duration-120 w-full"
                  >
                    <Plus className="h-3 w-3 stroke-[1.5]" />
                    <span>Add task</span>
                  </button>
                </div>
              )}

              {/* Group 2: Today */}
              {todayTasks.length > 0 && (
                <div className="space-y-1">
                  <div className="flex items-center justify-between px-2 pb-1">
                    <span className="text-[12px] font-medium text-ink-2">
                      Today ({todayTasks.length})
                    </span>
                  </div>
                  <div>
                    {todayTasks.map((task) => renderTaskRow(task, false))}
                  </div>
                  <button
                    type="button"
                    onClick={() => setCreateTaskModalOpen(true)}
                    className="h-8 flex items-center gap-2 px-2 text-[12px] text-ink-3 hover:text-ink hover:bg-hover/60 rounded-lg cursor-pointer transition-colors duration-120 w-full"
                  >
                    <Plus className="h-3 w-3 stroke-[1.5]" />
                    <span>Add task</span>
                  </button>
                </div>
              )}

              {/* Group 3: Upcoming */}
              {upcomingTasks.length > 0 && (
                <div className="space-y-1">
                  <div className="flex items-center justify-between px-2 pb-1">
                    <span className="text-[12px] font-medium text-ink-2">
                      Upcoming ({upcomingTasks.length})
                    </span>
                  </div>
                  <div>
                    {upcomingTasks.map((task) => renderTaskRow(task, false))}
                  </div>
                  <button
                    type="button"
                    onClick={() => setCreateTaskModalOpen(true)}
                    className="h-8 flex items-center gap-2 px-2 text-[12px] text-ink-3 hover:text-ink hover:bg-hover/60 rounded-lg cursor-pointer transition-colors duration-120 w-full"
                  >
                    <Plus className="h-3 w-3 stroke-[1.5]" />
                    <span>Add task</span>
                  </button>
                </div>
              )}

              {/* If no tasks in any group */}
              {overdueTasks.length === 0 &&
                todayTasks.length === 0 &&
                upcomingTasks.length === 0 && (
                  <EmptyLine
                    message="No open tasks right now."
                    actionText="Create one"
                    onAction={() => setCreateTaskModalOpen(true)}
                  />
                )}
            </div>
          )}

          {/* Tab 2: Projects */}
          {activeTab === "projects" && (
            <div className="space-y-1 pt-2">
              {projects.length > 0 ? (
                projects.map((proj) => (
                  <div
                    key={proj.id}
                    onMouseEnter={() => router.prefetch(`/app/projects/${proj.id}`)}
                    onClick={() => router.push(`/app/projects/${proj.id}`)}
                    className="flex h-11 items-center justify-between border-b border-hairline px-2 text-[13px] hover:bg-hover transition-colors duration-120 cursor-pointer rounded-lg"
                  >
                    <div className="flex items-center gap-2.5 truncate">
                      <span
                        className="h-2 w-2 rounded-full shrink-0"
                        style={{ backgroundColor: proj.color || "#3B63F0" }}
                      />
                      <span className="text-ink font-normal truncate">
                        {proj.name}
                      </span>
                    </div>
                    <span className="text-[12px] text-ink-3">
                      {proj.status || "Active"}
                    </span>
                  </div>
                ))
              ) : (
                <EmptyLine
                  message="No active projects."
                  actionText="New project"
                  onAction={() => setCreateProjectModalOpen(true)}
                />
              )}
            </div>
          )}

          {/* Tab 3: Approvals */}
          {activeTab === "approvals" && (
            <div className="space-y-1 pt-2">
              {approvalTasks.length > 0 ? (
                approvalTasks.map((task) => renderTaskRow(task, false))
              ) : (
                <EmptyLine
                  message="No items awaiting approval."
                />
              )}
            </div>
          )}
        </div>

        {/* Right Column (35%): "Up next" & optional "Needs attention" */}
        <div className="lg:col-span-4 lg:pl-8 space-y-6 pt-6 lg:pt-0">
          {/* Up next: Today's meetings as simple vertical timeline */}
          <div className="space-y-3">
            <h2 className="text-[14px] font-semibold text-ink">Up next</h2>

            {todayEvents.length > 0 ? (
              <div className="space-y-2.5">
                {todayEvents.map((evt) => {
                  const time = evt.start_time
                    ? evt.start_time.includes("T") || evt.start_time.includes("-")
                      ? (() => {
                          const d = new Date(evt.start_time);
                          return isNaN(d.getTime())
                            ? evt.start_time
                            : d.toLocaleTimeString("en-US", {
                                hour: "numeric",
                                minute: "2-digit",
                              });
                        })()
                      : evt.start_time
                    : "Today";

                  return (
                    <div
                      key={evt.id}
                      onMouseEnter={() => router.prefetch("/app/calendar")}
                      onClick={() => router.push("/app/calendar")}
                      className="flex items-center gap-3 p-2 rounded-lg hover:bg-hover transition-colors duration-120 cursor-pointer"
                    >
                      <span className="text-[12px] tabular-nums text-ink-3 w-14 shrink-0 font-normal">
                        {time}
                      </span>
                      <div className="min-w-0 flex-1">
                        <p className="text-[13px] font-normal text-ink truncate">
                          {evt.title}
                        </p>
                      </div>
                      <Video className="h-3.5 w-3.5 stroke-[1.5] text-ink-3 shrink-0" />
                    </div>
                  );
                })}
              </div>
            ) : (
              <EmptyLine
                message="No upcoming events today."
                actionText="Schedule one"
                onAction={() => router.push("/app/calendar")}
              />
            )}
          </div>

          {/* Needs attention: rendered ONLY if there are items */}
          {attentionItems.length > 0 && (
            <div className="space-y-3 pt-4 border-t border-hairline">
              <h2 className="text-[14px] font-semibold text-ink">Needs attention</h2>

              <div className="space-y-2">
                {attentionItems.map((item) => (
                  <Link
                    key={item.id}
                    href={item.href}
                    className="flex items-center justify-between p-2.5 rounded-lg border border-hairline bg-surface hover:bg-hover transition-colors duration-120 text-[13px]"
                  >
                    <div className="space-y-0.5 min-w-0 pr-2">
                      <p className="font-normal text-ink truncate">{item.title}</p>
                      <span className="text-[11px] text-ink-3">{item.label}</span>
                    </div>
                    <ChevronRight className="h-4 w-4 stroke-[1.5] text-ink-3 shrink-0" />
                  </Link>
                ))}
              </div>
            </div>
          )}
        </div>
      </section>

      {/* 4. Bottom: "Activity" as a compact feed (6 items with View all) */}
      <section className="pt-6 border-t border-hairline space-y-3">
        <div className="flex items-center justify-between">
          <h2 className="text-[14px] font-semibold text-ink">Activity</h2>
          <Link
            href="/app/my-tasks"
            className="text-[12px] font-medium text-ink-2 hover:text-ink transition-colors"
          >
            View all
          </Link>
        </div>

        {recentActivities && recentActivities.length > 0 ? (
          <div className="divide-y divide-hairline">
            {recentActivities.slice(0, 6).map((act) => {
              const actorName = act.actorName || "Team member";
              const timeAgo = act.createdAt
                ? new Date(act.createdAt).toLocaleDateString("en-US", {
                    month: "short",
                    day: "numeric",
                  })
                : "recently";

              return (
                <div
                  key={act.id}
                  className="flex items-center gap-3 py-2.5 text-[13px]"
                >
                  <Avatar name={actorName} size={20} accent="blue" />
                  <span className="text-ink truncate font-normal">
                    {formatActivityText(act)}
                  </span>
                  <span className="text-[12px] tabular-nums text-ink-3 shrink-0 ml-auto pl-3">
                    {timeAgo}
                  </span>
                </div>
              );
            })}
          </div>
        ) : (
          <EmptyLine message="No recent team activity." />
        )}
      </section>

      {/* Side Peek Panel for task detail */}
      <TaskPeekPanel
        task={selectedTask}
        isOpen={selectedTask !== null}
        onClose={() => setSelectedTask(null)}
        workspaceId={workspaceId}
        onTaskUpdated={(updated) => {
          setTasks((prev) =>
            prev.map((t) => (t.id === updated.id ? updated : t))
          );
        }}
        onTaskDeleted={(taskId) => {
          setTasks((prev) => prev.filter((t) => t.id !== taskId));
        }}
      />

      {/* Modals */}
      <CreateTaskModal
        isOpen={createTaskModalOpen}
        onClose={() => setCreateTaskModalOpen(false)}
        workspaceId={workspaceId}
        people={people}
        projects={projects}
        departments={departments}
        onSuccess={() => {
          setCreateTaskModalOpen(false);
          router.refresh();
        }}
      />

      <CreateProjectModal
        isOpen={createProjectModalOpen}
        onClose={() => setCreateProjectModalOpen(false)}
        workspaceId={workspaceId}
        departments={departments}
        people={people}
        onSuccess={() => {
          setCreateProjectModalOpen(false);
          router.refresh();
        }}
      />
    </div>
  );
}

"use client";

import * as React from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  Users,
  UserPlus,
  Search,
  SlidersHorizontal,
  Briefcase,
  Building2,
  CalendarDays,
  Clock,
  Mail,
  MoreHorizontal,
  ChevronRight,
  CheckCircle2,
  XCircle,
  Clock3,
  Calendar,
  UserCheck,
  ChevronDown,
  X,
  ExternalLink,
  Edit,
  UserX,
  Star,
  FileText,
  FolderKanban,
  Check,
  Phone,
  Shield,
  Filter,
  ArrowUpDown,
} from "lucide-react";
import { WorkspaceInvitation, WorkspacePerson } from "@/types/people";
import { Department } from "@/types/department";
import { JobOpening, Candidate, Interview, RecruitmentStats } from "@/types/recruitment";
import { MemberActivitySummary, MemberProjectSummary } from "@/lib/people/queries";
import { toggleMemberStatusAction, assignPersonToDepartmentAction } from "@/lib/people/actions";
import { useDebounce } from "@/hooks/use-debounce";
import { toast } from "sonner";
import { RopimoUserAvatar } from "@/components/ropimo/ropimo-user-avatar";
import { RopimoSelect } from "@/components/ropimo/ropimo-select";
import { EditPersonModal } from "@/components/app/edit-person-modal";
import { InvitePersonModal } from "@/components/app/invite-person-modal";
import { JobOpeningsView } from "./recruitment/job-openings-view";
import { CandidatesView } from "./recruitment/candidates-view";
import { InterviewsView } from "./recruitment/interviews-view";
import { OnboardingInvitationsView } from "./recruitment/onboarding-invitations-view";
import { cn } from "@/lib/utils";

export interface PeopleDirectoryProps {
  workspaceId: string;
  workspaceName?: string;
  userRole: string;
  people: WorkspacePerson[];
  departments: Department[];
  invitations?: WorkspaceInvitation[];
  memberActivitiesMap?: Record<string, MemberActivitySummary[]>;
  memberProjectsMap?: Record<string, MemberProjectSummary[]>;
  jobOpenings?: JobOpening[];
  candidates?: Candidate[];
  interviews?: Interview[];
  recruitmentStats?: RecruitmentStats;
}

type MainSectionTab = "team" | "onboarding" | "candidates" | "jobs" | "interviews";

export function PeopleDirectory({
  workspaceId,
  workspaceName = "brnnd",
  userRole,
  people = [],
  departments = [],
  invitations = [],
  memberActivitiesMap = {},
  memberProjectsMap = {},
  jobOpenings = [],
  candidates = [],
  interviews = [],
  recruitmentStats,
}: PeopleDirectoryProps) {
  const router = useRouter();

  // Top Section Tab
  const [activeSection, setActiveSection] = React.useState<MainSectionTab>("team");

  // Filter & Search State
  const [searchQuery, setSearchQuery] = React.useState("");
  const debouncedSearch = useDebounce(searchQuery, 200);
  const [selectedDeptId, setSelectedDeptId] = React.useState<string>("all");
  const [selectedRoleFilter, setSelectedRoleFilter] = React.useState<string>("all");
  const [selectedStatusFilter, setSelectedStatusFilter] = React.useState<string>("all");
  const [sortBy, setSortBy] = React.useState<string>("recent");
  const [currentPage, setCurrentPage] = React.useState(1);

  // Selected person for the slide-over profile drawer
  const [drawerPerson, setDrawerPerson] = React.useState<WorkspacePerson | null>(null);
  const [activeProfileTab, setActiveProfileTab] = React.useState<"overview" | "projects" | "activity">("overview");

  // Modals & Menu
  const [editingPerson, setEditingPerson] = React.useState<WorkspacePerson | null>(null);
  const [inviteModalOpen, setInviteModalOpen] = React.useState(false);
  const [rowMenuPersonId, setRowMenuPersonId] = React.useState<string | null>(null);
  const [isStarred, setIsStarred] = React.useState(false);

  const canManage = ["owner", "admin", "manager"].includes(userRole);
  const canEditRole = ["owner", "admin"].includes(userRole);

  const pendingInvsCount = React.useMemo(() => {
    return invitations.filter((i) => (i.status || "Pending").toLowerCase() === "pending").length;
  }, [invitations]);

  // Close drawer on Escape
  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && drawerPerson) {
        setDrawerPerson(null);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [drawerPerson]);

  // Close row menus on outside click
  React.useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (!(e.target as HTMLElement).closest("[data-row-menu]")) {
        setRowMenuPersonId(null);
      }
    };
    window.addEventListener("click", handleClickOutside);
    return () => window.removeEventListener("click", handleClickOutside);
  }, []);

  // Filtering & Sorting
  const filteredPeople = React.useMemo(() => {
    let result = people.filter((person) => {
      const query = debouncedSearch.toLowerCase().trim();
      const matchesSearch =
        !query ||
        (person.full_name && person.full_name.toLowerCase().includes(query)) ||
        person.email.toLowerCase().includes(query) ||
        (person.job_title && person.job_title.toLowerCase().includes(query)) ||
        person.departments.some((d) => d.name.toLowerCase().includes(query));

      const matchesDept =
        selectedDeptId === "all" ||
        person.departments.some((d) => d.id === selectedDeptId || d.name === selectedDeptId);

      const matchesRole =
        selectedRoleFilter === "all" ||
        person.role?.toLowerCase() === selectedRoleFilter.toLowerCase();

      const matchesStatus =
        selectedStatusFilter === "all" ||
        (person.employment_status || "Active").toLowerCase() === selectedStatusFilter.toLowerCase() ||
        (person.employment_type || "Full-time").toLowerCase() === selectedStatusFilter.toLowerCase();

      return matchesSearch && matchesDept && matchesRole && matchesStatus;
    });

    if (sortBy === "name-asc") {
      result = [...result].sort((a, b) =>
        (a.full_name || a.email).localeCompare(b.full_name || b.email)
      );
    } else if (sortBy === "name-desc") {
      result = [...result].sort((a, b) =>
        (b.full_name || b.email).localeCompare(a.full_name || a.email)
      );
    } else if (sortBy === "role") {
      result = [...result].sort((a, b) => (a.role || "").localeCompare(b.role || ""));
    }

    return result;
  }, [people, debouncedSearch, selectedDeptId, selectedRoleFilter, selectedStatusFilter, sortBy]);

  // Pagination
  const pageSize = 12;
  const totalCount = filteredPeople.length;
  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize));
  const paginatedPeople = React.useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return filteredPeople.slice(start, start + pageSize);
  }, [filteredPeople, currentPage]);

  const handleToggleStatus = async (person: WorkspacePerson) => {
    const prevStatus = person.employment_status || "Active";
    const newStatus = prevStatus === "Inactive" ? "Active" : "Inactive";
    try {
      await toggleMemberStatusAction(
        workspaceId,
        person.user_id || person.id,
        newStatus
      );
      router.refresh();
    } catch (err) {
      console.error(err);
      toast.error("Failed to update member status");
    }
  };

  const getStatusBadge = (status?: string) => {
    const s = (status || "Active").toLowerCase();
    if (s === "active") {
      return (
        <span className="inline-flex items-center gap-1.5 rounded-full border border-[#D8DDD4] bg-[#EAF4E2] px-2.5 py-0.5 text-[11px] font-semibold text-[#246244]">
          <span className="h-1.5 w-1.5 rounded-full bg-[#246244]" />
          Active
        </span>
      );
    }
    if (s === "pending" || s === "invited") {
      return (
        <span className="inline-flex items-center gap-1.5 rounded-full border border-[#F8E3B6] bg-[#FEF6E4] px-2.5 py-0.5 text-[11px] font-semibold text-[#B58500]">
          <Clock3 className="h-3 w-3" />
          Pending
        </span>
      );
    }
    if (s === "on leave" || s === "on_leave") {
      return (
        <span className="inline-flex items-center gap-1.5 rounded-full border border-[#F8CBC2] bg-[#FDECE8] px-2.5 py-0.5 text-[11px] font-semibold text-[#D9383A]">
          <Calendar className="h-3 w-3" />
          On leave
        </span>
      );
    }
    if (s === "inactive" || s === "terminated") {
      return (
        <span className="inline-flex items-center gap-1.5 rounded-full border border-[#D8DDD4] bg-[#F4F3EE] px-2.5 py-0.5 text-[11px] font-semibold text-[#65706A]">
          <span className="h-1.5 w-1.5 rounded-full bg-[#8A958F]" />
          Inactive
        </span>
      );
    }
    return (
      <span className="inline-flex items-center gap-1.5 rounded-full border border-[#D8DDD4] bg-[#EAF4E2] px-2.5 py-0.5 text-[11px] font-semibold text-[#246244]">
        <span className="h-1.5 w-1.5 rounded-full bg-[#246244]" />
        Active
      </span>
    );
  };

  const formatDate = (dateStr?: string) => {
    if (!dateStr) return "Aug 31, 2026";
    try {
      return new Date(dateStr).toLocaleDateString("en-US", {
        month: "short",
        day: "numeric",
        year: "numeric",
      });
    } catch {
      return dateStr;
    }
  };

  const drawerPersonActivities = drawerPerson
    ? memberActivitiesMap[drawerPerson.user_id || drawerPerson.id] || []
    : [];
  const drawerPersonProjects = drawerPerson
    ? memberProjectsMap[drawerPerson.user_id || drawerPerson.id] || []
    : [];

  return (
    <div className="mx-auto max-w-[1380px] space-y-6 pb-24 text-[#18221E] select-none">
      {/* 1. COMPACT PAGE HEADER */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between pt-1">
        <div>
          <h1 className="text-2xl sm:text-[28px] font-bold tracking-tight text-[#18221E]">
            People
          </h1>
          <p className="text-xs sm:text-sm text-[#65706A] mt-0.5">
            Manage your team, hiring pipeline, and workforce.
          </p>
        </div>

        {canManage && (
          <button
            type="button"
            onClick={() => setInviteModalOpen(true)}
            className="inline-flex h-9 items-center gap-2 rounded-[10px] bg-[#10251F] px-3.5 text-xs font-semibold text-[#F4F3EE] shadow-xs hover:bg-[#18342C] transition-colors cursor-pointer shrink-0"
          >
            <UserPlus className="h-3.5 w-3.5 text-[#C7F34A]" />
            <span>Invite people</span>
          </button>
        )}
      </div>

      {/* 2. POLISHED TOP SEGMENTED NAVIGATION */}
      <div className="flex items-center gap-1.5 rounded-[12px] border border-[#D8DDD4] bg-white p-1.5 shadow-2xs overflow-x-auto">
        {[
          { id: "team", label: "Team", count: people.length, icon: Users },
          { id: "onboarding", label: "Invites & Onboarding", count: pendingInvsCount, icon: Clock },
          { id: "candidates", label: "Candidates", count: candidates.length, icon: UserCheck },
          { id: "jobs", label: "Job openings", count: jobOpenings.length, icon: Briefcase },
          { id: "interviews", label: "Interviews", count: interviews.length, icon: CalendarDays },
        ].map((tab) => {
          const Icon = tab.icon;
          const isActive = activeSection === tab.id;
          return (
            <button
              key={tab.id}
              type="button"
              onClick={() => setActiveSection(tab.id as any)}
              className={cn(
                "flex items-center gap-2 rounded-[8px] px-3.5 py-1.5 text-xs font-semibold transition-all cursor-pointer whitespace-nowrap",
                isActive
                  ? "bg-[#10251F] text-[#F4F3EE] shadow-2xs font-bold"
                  : "text-[#65706A] hover:bg-[#FAF9F5] hover:text-[#18221E]"
              )}
            >
              <Icon className={cn("h-3.5 w-3.5", isActive ? "text-[#C7F34A]" : "text-[#65706A]")} />
              <span>{tab.label}</span>
              <span
                className={cn(
                  "rounded-full px-2 py-0.5 text-[10px] font-bold transition-colors",
                  isActive
                    ? "bg-white/20 text-[#F4F3EE]"
                    : "bg-[#FAF9F5] border border-[#D8DDD4] text-[#65706A]"
                )}
              >
                {tab.count}
              </span>
            </button>
          );
        })}
      </div>

      {/* 3. SECTION CONTENT */}
      {activeSection === "team" && (
        <div className="space-y-4">
          {/* COMPACT TOOLBAR */}
          <div className="flex flex-wrap items-center justify-between gap-3">
            {/* Search */}
            <div className="relative flex-1 min-w-[240px] max-w-md">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-[#65706A]" />
              <input
                type="text"
                placeholder="Search people by name, email, or role..."
                value={searchQuery}
                onChange={(e) => {
                  setSearchQuery(e.target.value);
                  setCurrentPage(1);
                }}
                className="w-full h-9 rounded-[10px] border border-[#D8DDD4] bg-white pl-9 pr-8 text-xs text-[#18221E] shadow-2xs placeholder:text-[#8A958F] focus:border-[#10251F] focus:outline-none transition-colors"
              />
              {searchQuery && (
                <button
                  type="button"
                  onClick={() => setSearchQuery("")}
                  className="absolute right-2.5 top-1/2 -translate-y-1/2 rounded p-0.5 text-[#65706A] hover:text-[#18221E]"
                >
                  <X className="h-3 w-3" />
                </button>
              )}
            </div>

            {/* Custom Filter Dropdowns */}
            <div className="flex flex-wrap items-center gap-2">
              {/* Department Filter */}
              <RopimoSelect
                value={selectedDeptId}
                onChange={(val) => {
                  setSelectedDeptId(val);
                  setCurrentPage(1);
                }}
                options={[
                  { value: "all", label: "All Departments" },
                  ...departments.map((d) => ({ value: d.id, label: d.name })),
                ]}
              />

              {/* Status Filter */}
              <RopimoSelect
                value={selectedStatusFilter}
                onChange={(val) => {
                  setSelectedStatusFilter(val);
                  setCurrentPage(1);
                }}
                options={[
                  { value: "all", label: "All Status" },
                  { value: "Active", label: "Active" },
                  { value: "Pending", label: "Pending" },
                  { value: "On leave", label: "On leave" },
                  { value: "Inactive", label: "Inactive" },
                ]}
              />

              {/* Sort By */}
              <RopimoSelect
                value={sortBy}
                onChange={(val) => setSortBy(val)}
                prefix="Sort"
                options={[
                  { value: "recent", label: "Recently Added" },
                  { value: "name-asc", label: "Name (A-Z)" },
                  { value: "name-desc", label: "Name (Z-A)" },
                  { value: "role", label: "Role / Title" },
                ]}
              />

              {/* Clear filters button */}
              {(selectedDeptId !== "all" || selectedStatusFilter !== "all" || searchQuery) && (
                <button
                  type="button"
                  onClick={() => {
                    setSelectedDeptId("all");
                    setSelectedStatusFilter("all");
                    setSearchQuery("");
                  }}
                  className="h-9 inline-flex items-center gap-1 rounded-[10px] border border-[#D8DDD4] bg-white px-2.5 text-xs font-medium text-[#65706A] hover:text-[#D9383A] hover:bg-[#FAF9F5] transition-colors cursor-pointer"
                >
                  <X className="h-3 w-3" />
                  <span>Clear</span>
                </button>
              )}
            </div>
          </div>

          {/* REFINED ENTERPRISE EMPLOYEE DIRECTORY TABLE */}
          <div className="overflow-hidden rounded-[14px] border border-[#D8DDD4] bg-white shadow-2xs">
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs border-collapse">
                <thead>
                  <tr className="border-b border-[#E7EADF] bg-[#FAF9F5] text-[10px] font-bold uppercase tracking-wider text-[#8A958F]">
                    <th className="py-3 px-4 font-bold">PERSON</th>
                    <th className="py-3 px-4 font-bold">ROLE</th>
                    <th className="py-3 px-4 font-bold">DEPARTMENT</th>
                    <th className="py-3 px-4 font-bold text-center">STATUS</th>
                    <th className="py-3 px-4 font-bold">JOINED</th>
                    <th className="py-3 px-4 font-bold text-right">ACTIONS</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#E7EADF]">
                  {paginatedPeople.length === 0 ? (
                    <tr>
                      <td colSpan={6} className="py-12 text-center text-xs text-[#65706A]">
                        No team members match the current filters.
                      </td>
                    </tr>
                  ) : (
                    paginatedPeople.map((person, index) => {
                      const empId = `EMP-${String(index + 1).padStart(3, "0")}`;
                      const primaryDept = person.departments[0];
                      const jobRole = person.job_title || person.role || "Team Member";

                      return (
                        <tr
                          key={person.id}
                          onClick={() => setDrawerPerson(person)}
                          className="group hover:bg-[#FAF9F5] transition-colors cursor-pointer"
                        >
                          {/* Person: Avatar + Name + Email + EMP ID */}
                          <td className="py-3 px-4">
                            <div className="flex items-center gap-3">
                              <RopimoUserAvatar
                                name={person.full_name || person.email}
                                imageUrl={person.avatar_url}
                                size="sm"
                              />
                              <div className="min-w-0">
                                <div className="flex items-center gap-2">
                                  <p className="font-bold text-[#18221E] group-hover:text-[#246244] transition-colors truncate">
                                    {person.full_name || person.email.split("@")[0]}
                                  </p>
                                  <span className="rounded bg-[#FAF9F5] border border-[#D8DDD4] px-1.5 py-0.2 text-[9px] font-mono text-[#8A958F]">
                                    {empId}
                                  </span>
                                </div>
                                <p className="text-[11px] text-[#65706A] truncate">
                                  {person.email}
                                </p>
                              </div>
                            </div>
                          </td>

                          {/* Role */}
                          <td className="py-3 px-4">
                            <p className="font-semibold text-[#18221E] truncate max-w-[180px]">
                              {jobRole}
                            </p>
                            <span className="text-[10px] text-[#8A958F] capitalize">
                              {person.role || "member"}
                            </span>
                          </td>

                          {/* Department (Clickable link) */}
                          <td className="py-3 px-4" onClick={(e) => e.stopPropagation()}>
                            {primaryDept ? (
                              <Link
                                href={`/app/departments/${primaryDept.id}`}
                                className="inline-flex items-center gap-1.5 rounded-full border border-[#D8DDD4] bg-[#FAF9F5] px-2.5 py-0.5 text-[11px] font-semibold text-[#18221E] hover:border-[#10251F] hover:bg-white transition-all no-underline"
                              >
                                <span className="h-1.5 w-1.5 rounded-full bg-[#246244]" />
                                <span className="truncate max-w-[130px]">{primaryDept.name}</span>
                              </Link>
                            ) : (
                              <span className="text-[#8A958F] italic">Unassigned</span>
                            )}
                          </td>

                          {/* Status */}
                          <td className="py-3 px-4 text-center">
                            {getStatusBadge(person.employment_status)}
                          </td>

                          {/* Joined Date */}
                          <td className="py-3 px-4 text-[#65706A] font-medium text-[11px] whitespace-nowrap">
                            {formatDate(person.created_at)}
                          </td>

                          {/* Actions */}
                          <td
                            className="py-3 px-4 text-right"
                            onClick={(e) => e.stopPropagation()}
                          >
                            <div className="flex items-center justify-end gap-2" data-row-menu>
                              <Link
                                href={`/app/people/${person.user_id || person.id}`}
                                className="inline-flex items-center gap-1 text-[11px] font-bold text-[#246244] hover:underline whitespace-nowrap"
                              >
                                <span>View profile</span>
                                <ChevronRight className="h-3 w-3" />
                              </Link>

                              {canManage && (
                                <div className="relative">
                                  <button
                                    type="button"
                                    onClick={() =>
                                      setRowMenuPersonId(
                                        rowMenuPersonId === person.id ? null : person.id
                                      )
                                    }
                                    className="rounded-[6px] p-1 text-[#65706A] hover:bg-white hover:text-[#18221E] transition-colors"
                                  >
                                    <MoreHorizontal className="h-4 w-4" />
                                  </button>

                                  {rowMenuPersonId === person.id && (
                                    <div className="absolute right-0 top-full mt-1 z-30 min-w-[175px] rounded-[10px] border border-[#D8DDD4] bg-white p-1 shadow-elevated text-left">
                                      <Link
                                        href={`/app/people/onboarding/${person.user_id || person.id}`}
                                        className="flex w-full items-center gap-2 rounded-[6px] px-2.5 py-1.5 text-xs font-semibold text-[#246244] hover:bg-[#EAF4E2] transition-colors no-underline"
                                      >
                                        <Clock className="h-3.5 w-3.5 text-[#246244]" />
                                        <span>Onboarding Checklist</span>
                                      </Link>

                                      <button
                                        type="button"
                                        onClick={() => {
                                          setRowMenuPersonId(null);
                                          setEditingPerson(person);
                                        }}
                                        className="flex w-full items-center gap-2 rounded-[6px] px-2.5 py-1.5 text-xs text-[#18221E] hover:bg-[#FAF9F5] transition-colors"
                                      >
                                        <Edit className="h-3.5 w-3.5 text-[#65706A]" />
                                        <span>Edit Details</span>
                                      </button>

                                      <button
                                        type="button"
                                        onClick={() => {
                                          setRowMenuPersonId(null);
                                          handleToggleStatus(person);
                                        }}
                                        className="flex w-full items-center gap-2 rounded-[6px] px-2.5 py-1.5 text-xs text-[#18221E] hover:bg-[#FAF9F5] transition-colors"
                                      >
                                        <UserX className="h-3.5 w-3.5 text-[#65706A]" />
                                        <span>
                                          {person.employment_status === "Inactive"
                                            ? "Activate Member"
                                            : "Deactivate Member"}
                                        </span>
                                      </button>
                                    </div>
                                  )}
                                </div>
                              )}
                            </div>
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>

            {/* Pagination Footer */}
            {totalPages > 1 && (
              <div className="flex items-center justify-between px-4 py-3 border-t border-[#E7EADF] bg-[#FAF9F5] text-xs">
