        </div>
      )}

      {/* 4. ONBOARDING & PENDING INVITATIONS TAB */}
      {activeSection === "onboarding" && (
        <OnboardingInvitationsView
          workspaceId={workspaceId}
          userRole={userRole}
          invitations={invitations}
          people={people}
          departments={departments}
