      {/* 7. SLIDE-OVER EMPLOYEE PROFILE DRAWER */}
      {drawerPerson && (
        <div className="fixed inset-0 z-50 flex justify-end">
          <div
            className="fixed inset-0 bg-black/30 backdrop-blur-xs transition-opacity"
