                          <p className="font-bold text-[#18221E]">{p.name}</p>
                          <span className="text-[10px] font-semibold text-[#65706A]">{p.status}</span>
                        </div>
                        <p className="text-[11px] text-[#65706A] mt-1">{p.role || "Contributor"}</p>
