                                    const isCompleted = t.status === "completed";
                                    const assignee =
                                      t.assignees?.[0] || people.find((p) => p.user_id === t.created_by);

                                    const priorityConfig: Record<
                                      TaskPriority,
                                      { flagColor: string; bg: string; text: string; label: string }
