"use client";

import * as React from "react";
import {
  ChevronDown,
  ChevronRight,
  Plus,
  Check,
  Building2,
  Calendar,
  User,
  MoreHorizontal,
  ArrowRight,
  X,
  ListTodo,
  Sparkles,
} from "lucide-react";
import { Task, TaskStatus, TaskPriority } from "@/types/task";
import { Project } from "@/types/project";
import { WorkspacePerson } from "@/types/people";
import { Department } from "@/types/department";
import { toggleTaskCompletionAction, createTaskAction, updateTaskAction } from "@/lib/task/actions";
import {
  STRUCTURED_PROJECT_PHASES,
  getTaskPhase,
  getTaskCollaborativeDepartments,
} from "@/lib/project/phases";
import { cn } from "@/lib/utils";

export interface ProjectGroupedListViewProps {
  project: Project;
  tasks: Task[];
  people: WorkspacePerson[];
  departments: Department[];
  activePhaseId?: string;
  onPhaseChange?: (phaseId: string) => void;
  onSelectTask?: (task: Task) => void;
  onOpenCreateModal?: (defaultPhaseId?: string) => void;
}

const PRIORITY_BADGES: Record<string, { label: string; class: string }> = {
  urgent: { label: "Urgent", class: "bg-red-50 text-red-700 border-red-200" },
  high: { label: "High", class: "bg-orange-50 text-orange-700 border-orange-200" },
  medium: { label: "Medium", class: "bg-amber-50 text-amber-700 border-amber-200" },
  low: { label: "Low", class: "bg-green-50 text-green-700 border-green-200" },
};

const STATUS_BADGES: Record<string, { label: string; class: string }> = {
  todo: { label: "To Do", class: "bg-[#F4F3EE] text-[#65706A] border-[#D8DDD4]" },
  in_progress: { label: "In Progress", class: "bg-blue-50 text-blue-700 border-blue-200" },
  in_review: { label: "In Review", class: "bg-purple-50 text-purple-700 border-purple-200" },
  completed: { label: "Completed", class: "bg-[#EAF4E2] text-[#246244] border-[#D8DDD4]" },
};

function formatTaskDueDate(dateStr?: string | null): string {
  if (!dateStr) return "No due date";
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return dateStr;
    return d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
  } catch {
    return dateStr;
  }
}

export function ProjectGroupedListView({
  project,
  tasks: initialTasks,
  people,
  departments = [],
  activePhaseId = "01",
  onPhaseChange,
  onSelectTask,
  onOpenCreateModal,
}: ProjectGroupedListViewProps) {
  const [tasks, setTasks] = React.useState<Task[]>(initialTasks);
  const [collapsedSections, setCollapsedSections] = React.useState<Record<string, boolean>>({});
  const [inlineTaskTitle, setInlineTaskTitle] = React.useState("");
  const [inlineAddingPhaseId, setInlineAddingPhaseId] = React.useState<string | null>(null);

  // Department picker popover state for a specific task
  const [activeDeptMenuTaskId, setActiveDeptMenuTaskId] = React.useState<string | null>(null);
  const deptMenuRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    setTasks(initialTasks);
  }, [initialTasks]);

  React.useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (deptMenuRef.current && !deptMenuRef.current.contains(e.target as Node)) {
        setActiveDeptMenuTaskId(null);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const toggleSection = (sectionKey: string) => {
    setCollapsedSections((prev) => ({
      ...prev,
      [sectionKey]: !prev[sectionKey],
    }));
  };

  // Toggle Task Completion
  const handleToggleTask = async (task: Task) => {
    const isCompleted = task.status === "completed";
    const newStatus: TaskStatus = isCompleted ? "todo" : "completed";

    setTasks((prev) =>
      prev.map((t) => (t.id === task.id ? { ...t, status: newStatus } : t))
    );

    try {
      await toggleTaskCompletionAction(
        task.id,
        task.workspace_id || project.workspace_id,
        !isCompleted
      );
    } catch (err) {
      console.error("[ProjectView] Failed to toggle task:", err);
      setTasks((prev) =>
        prev.map((t) => (t.id === task.id ? { ...t, status: task.status } : t))
      );
    }
  };

  // Inline Add Task to current phase
  const handleInlineAddTask = async (phaseId: string) => {
    if (!inlineTaskTitle.trim()) {
      setInlineAddingPhaseId(null);
      return;
    }

    const title = inlineTaskTitle.trim();
    const tempId = `task-temp-${Date.now()}`;
    const targetPhase = STRUCTURED_PROJECT_PHASES.find((p) => p.id === phaseId) || STRUCTURED_PROJECT_PHASES[0];

    const newTask: Task = {
      id: tempId,
      workspace_id: project.workspace_id,
      project_id: project.id,
      department_id: departments[0]?.id || null,
      deliverable_type: targetPhase.name,
      section: targetPhase.id,
      department: departments[0]
        ? { id: departments[0].id, name: departments[0].name, color: departments[0].color || "#10251F", icon: departments[0].icon || "Building2" }
        : null,
      project: { id: project.id, name: project.name, color: project.color || "#10251F", icon: project.icon || "Folder" },
      title,
      status: "todo",
      priority: "medium",
      due_date: null,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      assignees: [],
    };

    setTasks((prev) => [...prev, newTask]);
    setInlineTaskTitle("");
    setInlineAddingPhaseId(null);

    try {
      const res = await createTaskAction({
        workspaceId: project.workspace_id,
        projectId: project.id,
        departmentId: departments[0]?.id || undefined,
        deliverableType: targetPhase.name,
        title,
        priority: "medium",
        status: "todo",
      });

      if (res.success && res.taskId) {
        setTasks((prev) =>
          prev.map((t) => (t.id === tempId ? { ...t, id: res.taskId! } : t))
        );
      }
    } catch (err) {
      console.error("[ProjectView] Failed to create inline task:", err);
      setTasks((prev) => prev.filter((t) => t.id !== tempId));
    }
  };

  // Toggle department for a task (collaborative working across departments)
  const handleToggleDepartmentOnTask = async (task: Task, dept: Department) => {
    const currentDepts = getTaskCollaborativeDepartments(task, departments);
    const hasDept = currentDepts.some((d) => d.id === dept.id);
    let updatedDepts: Department[];

    if (hasDept) {
      // Keep at least one department
      if (currentDepts.length > 1) {
        updatedDepts = currentDepts.filter((d) => d.id !== dept.id);
      } else {
        return;
      }
    } else {
      updatedDepts = [...currentDepts, dept];
    }

    const deptNames = updatedDepts.map((d) => d.name).join(", ");
    setTasks((prev) =>
      prev.map((t) =>
        t.id === task.id
          ? {
              ...t,
              expected_outcome: deptNames,
              department_id: updatedDepts[0]?.id || t.department_id,
            }
          : t
      )
    );

    try {
      await updateTaskAction({
        taskId: task.id,
        workspaceId: task.workspace_id,
        departmentId: updatedDepts[0]?.id,
        expectedOutcome: deptNames,
      });
    } catch (err) {
      console.error("[ProjectView] Failed to update collaborative departments:", err);
    }
  };

  // Get current active phase object
  const currentPhaseIndex = STRUCTURED_PROJECT_PHASES.findIndex((p) => p.id === activePhaseId);
  const currentPhase = STRUCTURED_PROJECT_PHASES[currentPhaseIndex] || STRUCTURED_PROJECT_PHASES[0];
  const nextPhase =
    currentPhaseIndex >= 0 && currentPhaseIndex < STRUCTURED_PROJECT_PHASES.length - 1
      ? STRUCTURED_PROJECT_PHASES[currentPhaseIndex + 1]
      : null;

  // Filter tasks for the active phase (or if activePhaseId is "all", show all)
  const isAllPhases = activePhaseId === "all";
  const displayedPhases = isAllPhases
    ? STRUCTURED_PROJECT_PHASES
    : [currentPhase];

  return (
    <div className="w-full bg-white rounded-[18px] border border-[#E5E8E1] overflow-hidden shadow-xs select-none">
      {/* ── PHASE WORKSTREAM HEADER BANNER ─────────────────────────────── */}
      {!isAllPhases && (
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 px-5 py-3.5 bg-[#FAF9F5] border-b border-[#E5E8E1]">
          <div className="flex items-center gap-2.5">
            <div className="flex h-7 w-7 items-center justify-center rounded-[8px] bg-[#10251F] text-white">
              <ListTodo size={15} />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <span className="text-xs font-bold text-[#18221E]">{currentPhase.name}</span>
                <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-white border border-[#D8DDD4] text-[#65706A]">
                  Active Workstream
                </span>
              </div>
              <p className="text-[11px] text-[#8A958F] mt-0.2">
                Tasks & collaborative deliverables for this phase
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => onOpenCreateModal?.(currentPhase.id)}
              className="inline-flex items-center gap-1.5 rounded-[8px] bg-[#10251F] px-3 py-1.5 text-xs font-semibold text-white shadow-2xs hover:bg-[#18342C] transition-colors cursor-pointer"
            >
              <Plus size={13} />
              <span>Add Task to {currentPhase.title}</span>
            </button>

            {nextPhase && (
              <button
                type="button"
                onClick={() => onPhaseChange?.(nextPhase.id)}
                className="inline-flex items-center gap-1 rounded-[8px] border border-[#D8DDD4] bg-white px-2.5 py-1.5 text-xs font-semibold text-[#65706A] hover:text-[#18221E] hover:bg-[#FAF9F5] transition-colors cursor-pointer"
                title={`Advance to ${nextPhase.name}`}
              >
                <span>Next: {nextPhase.title}</span>
                <ArrowRight size={12} />
              </button>
            )}
          </div>
        </div>
      )}

      {/* ── LIST TABLE ─────────────────────────────────────────────────── */}
      <div className="w-full overflow-x-auto">
        <table className="w-full text-left text-xs border-collapse min-w-[900px]">
          {/* Table Header */}
          <thead>
            <tr className="border-b border-[#E5E8E1] bg-[#FAFAF8] text-[#65706A] font-semibold text-[11px]">
              <th className="py-2.5 px-4 font-semibold w-[320px]">Task name</th>
              <th className="py-2.5 px-3 font-semibold w-[220px]">Assigned Departments (Collaborative)</th>
              <th className="py-2.5 px-3 font-semibold w-[150px]">Assignee</th>
              <th className="py-2.5 px-3 font-semibold w-[100px]">Priority</th>
              <th className="py-2.5 px-3 font-semibold w-[120px]">Due date</th>
              <th className="py-2.5 px-3 font-semibold w-[110px]">Status</th>
              <th className="py-2.5 px-2 font-semibold w-[35px] text-center"></th>
            </tr>
          </thead>

          {/* Table Body Groups: ONE SECTION PER PHASE */}
          <tbody className="divide-y divide-[#E5E8E1]/60">
            {displayedPhases.map((phase) => {
              const phaseTasks = tasks.filter((t) => {
                const p = getTaskPhase(t);
                return p === phase.id;
              });
              const completedCount = phaseTasks.filter((t) => t.status === "completed").length;
              const isCollapsed = collapsedSections[phase.id];

              return (
                <React.Fragment key={phase.id}>
                  {/* Phase Section Header Row (Shown when viewing all phases) */}
                  {isAllPhases && (
                    <tr className="bg-[#FFFFFF] hover:bg-[#F9FAF7] transition-colors border-t border-[#E5E8E1]">
                      <td colSpan={7} className="py-2.5 px-3">
                        <div className="flex items-center justify-between">
                          <button
                            type="button"
                            onClick={() => toggleSection(phase.id)}
                            className="flex items-center gap-2 text-xs font-bold text-[#18221E] hover:text-[#246244] transition-colors cursor-pointer"
                          >
                            {isCollapsed ? (
                              <ChevronRight size={14} className="text-[#8A958F]" />
                            ) : (
                              <ChevronDown size={14} className="text-[#8A958F]" />
                            )}

                            <span className="font-bold text-[#18221E]">{phase.name}</span>
                            <span className="text-[10px] font-semibold text-[#8A958F]">
                              ({phaseTasks.length} {phaseTasks.length === 1 ? "task" : "tasks"}
                              {phaseTasks.length > 0 && ` · ${completedCount} completed`})
                            </span>
                          </button>

                          <button
                            type="button"
                            onClick={() => {
                              setCollapsedSections((prev) => ({ ...prev, [phase.id]: false }));
                              setInlineAddingPhaseId(phase.id);
                              setInlineTaskTitle("");
                            }}
                            className="inline-flex items-center gap-1 text-[11px] font-semibold text-[#65706A] hover:text-[#18221E] px-2 py-0.5 rounded hover:bg-[#FAF9F5] transition-colors cursor-pointer"
                          >
                            <Plus size={12} />
                            <span>Add task</span>
                          </button>
                        </div>
                      </td>
                    </tr>
                  )}

                  {/* Phase Tasks Rows */}
                  {!isCollapsed && (
                    <>
                      {phaseTasks.length > 0 ? (
                        phaseTasks.map((task) => {
                          const isDone = task.status === "completed";
                          const assignee = task.assignees?.[0];
                          const assigneeName = assignee?.full_name || "Unassigned";
                          const priorityCfg =
                            PRIORITY_BADGES[task.priority] || PRIORITY_BADGES.medium;
                          const statusCfg =
                            STATUS_BADGES[task.status] || STATUS_BADGES.todo;
                          const isOverdue =
                            !isDone &&
                            task.due_date &&
                            new Date(task.due_date).getTime() < new Date().setHours(0, 0, 0, 0);

                          // Collaborative multiple departments
                          const taskDepts = getTaskCollaborativeDepartments(task, departments);
                          const isDeptMenuOpen = activeDeptMenuTaskId === task.id;

                          return (
                            <tr
                              key={task.id}
                              className="group hover:bg-[#F9FAF7] transition-colors text-xs border-b border-[#E5E8E1]/40"
                            >
                              {/* Task Name & Completion Checkbox */}
                              <td className="py-2.5 px-4 pl-6">
                                <div className="flex items-center gap-2.5">
                                  <button
                                    type="button"
                                    onClick={() => handleToggleTask(task)}
                                    className="shrink-0 transition-transform active:scale-90 cursor-pointer"
                                    title={isDone ? "Mark incomplete" : "Mark complete"}
                                  >
                                    {isDone ? (
                                      <div className="flex h-4 w-4 items-center justify-center rounded-full bg-[#246244] text-white">
                                        <Check size={10} strokeWidth={3} />
                                      </div>
                                    ) : (
                                      <div className="h-4 w-4 rounded-full border border-[#8A958F] hover:border-[#246244] transition-colors" />
                                    )}
                                  </button>

                                  <span
                                    onClick={() => onSelectTask?.(task)}
                                    className={cn(
                                      "font-medium text-[#18221E] hover:text-[#246244] cursor-pointer truncate transition-colors",
                                      isDone && "line-through text-[#8A958F]"
                                    )}
                                  >
                                    {task.title}
                                  </span>
                                </div>
                              </td>

                              {/* Assigned Departments (Collaborative Multi-Department Badges) */}
                              <td className="py-2 px-3 relative">
                                <div className="flex items-center gap-1.5 flex-wrap">
                                  {taskDepts.map((d) => (
                                    <span
                                      key={d.id}
                                      className="inline-flex items-center gap-1 px-2 py-0.5 rounded-[5px] text-[10.5px] font-semibold border shadow-2xs"
                                      style={{
                                        backgroundColor: `${d.color || "#10251F"}12`,
                                        color: d.color || "#10251F",
                                        borderColor: `${d.color || "#10251F"}25`,
                                      }}
                                    >
                                      <span
                                        className="h-1.5 w-1.5 rounded-full shrink-0"
                                        style={{ backgroundColor: d.color || "#10251F" }}
                                      />
                                      <span>{d.name}</span>
                                    </span>
                                  ))}

                                  {/* Button to toggle / add collaborative departments */}
                                  <button
                                    type="button"
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      setActiveDeptMenuTaskId(isDeptMenuOpen ? null : task.id);
                                    }}
                                    className="h-5 w-5 rounded-full border border-dashed border-[#D8DDD4] hover:border-[#10251F] text-[#8A958F] hover:text-[#18221E] flex items-center justify-center transition-colors cursor-pointer"
                                    title="Assign/collaborate with department"
                                  >
                                    <Plus size={11} />
                                  </button>
                                </div>

                                {/* Collaborative Department Selector Popover */}
                                {isDeptMenuOpen && (
                                  <div
                                    ref={deptMenuRef}
                                    className="absolute left-3 top-full mt-1 z-50 w-56 rounded-[12px] border border-[#D8DDD4] bg-white p-1.5 shadow-xl select-none"
                                  >
                                    <div className="px-2 py-1 border-b border-[#E7EADF] mb-1">
                                      <p className="text-[10px] font-bold uppercase tracking-wider text-[#8A958F]">
                                        Collaborative Departments
                                      </p>
                                    </div>
                                    <div className="space-y-0.5">
                                      {departments.map((dept) => {
                                        const isAssigned = taskDepts.some((d) => d.id === dept.id);
                                        return (
                                          <button
                                            key={dept.id}
                                            type="button"
                                            onClick={() => handleToggleDepartmentOnTask(task, dept)}
                                            className={cn(
                                              "flex w-full items-center justify-between px-2 py-1.5 rounded-[6px] text-xs font-medium transition-colors cursor-pointer text-left",
                                              isAssigned
                                                ? "bg-[#FAF9F5] text-[#10251F] font-bold"
                                                : "text-[#18221E] hover:bg-[#FAF9F5]"
                                            )}
                                          >
                                            <div className="flex items-center gap-1.5 truncate">
                                              <span
                                                className="h-2 w-2 rounded-full shrink-0"
                                                style={{ backgroundColor: dept.color || "#10251F" }}
                                              />
                                              <span className="truncate">{dept.name}</span>
                                            </div>
                                            {isAssigned && (
                                              <Check size={13} className="text-[#10251F] shrink-0" />
                                            )}
                                          </button>
                                        );
                                      })}
                                    </div>
                                  </div>
                                )}
                              </td>

                              {/* Assignee */}
                              <td className="py-2 px-3">
                                <div className="inline-flex items-center gap-1.5 rounded-full bg-[#FAF9F5] border border-[#E5E8E1] px-2 py-0.5 max-w-[145px]">
                                  {assignee?.avatar_url ? (
                                    <img
                                      src={assignee.avatar_url}
                                      alt=""
                                      className="h-4 w-4 rounded-full object-cover"
                                    />
                                  ) : (
                                    <div className="flex h-4 w-4 items-center justify-center rounded-full bg-[#10251F] text-white text-[8px] font-bold shrink-0">
                                      {assigneeName[0].toUpperCase()}
                                    </div>
                                  )}
                                  <span className="truncate text-[11px] text-[#18221E] font-medium">
                                    {assigneeName}
                                  </span>
                                </div>
                              </td>

                              {/* Priority */}
                              <td className="py-2 px-3">
                                <span
                                  className={cn(
                                    "inline-block rounded-[6px] border px-2 py-0.5 text-[10.5px] font-semibold",
                                    priorityCfg.class
                                  )}
                                >
                                  {priorityCfg.label}
                                </span>
                              </td>

                              {/* Due date */}
                              <td className="py-2 px-3">
                                <span
                                  className={cn(
                                    "text-[11px] font-medium",
                                    isOverdue
                                      ? "text-red-600 font-bold"
                                      : task.due_date
                                      ? "text-[#18221E]"
                                      : "text-[#8A958F]"
                                  )}
                                >
                                  {formatTaskDueDate(task.due_date)}
                                </span>
                              </td>

                              {/* Status */}
                              <td className="py-2 px-3">
                                <span
                                  className={cn(
                                    "inline-block rounded-[6px] border px-2 py-0.5 text-[10.5px] font-semibold",
                                    statusCfg.class
                                  )}
                                >
                                  {statusCfg.label}
                                </span>
                              </td>

                              {/* Actions */}
                              <td className="py-2 px-2 text-center">
                                <button
                                  type="button"
                                  onClick={() => onSelectTask?.(task)}
                                  className="text-[#8A958F] hover:text-[#18221E] p-1 rounded hover:bg-[#FAF9F5] transition-colors cursor-pointer"
                                  title="View task details"
                                >
                                  <MoreHorizontal size={14} />
                                </button>
                              </td>
                            </tr>
                          );
                        })
                      ) : (
                        <tr className="border-b border-[#E5E8E1]/40">
                          <td colSpan={7} className="py-6 text-center text-xs text-[#8A958F]">
                            No tasks in this phase yet.
                            <button
                              type="button"
                              onClick={() => {
                                setInlineAddingPhaseId(phase.id);
                                setInlineTaskTitle("");
                              }}
                              className="ml-2 font-bold text-[#10251F] hover:underline cursor-pointer"
                            >
                              Add first task
                            </button>
                          </td>
                        </tr>
                      )}

                      {/* Inline Add Task Row */}
                      {inlineAddingPhaseId === phase.id ? (
                        <tr className="bg-[#FAF9F5]/70 border-b border-[#E5E8E1]">
                          <td colSpan={7} className="py-2 px-6">
                            <form
                              onSubmit={(e) => {
                                e.preventDefault();
                                handleInlineAddTask(phase.id);
                              }}
                              className="flex items-center gap-2"
                            >
                              <input
                                autoFocus
                                type="text"
                                value={inlineTaskTitle}
                                onChange={(e) => setInlineTaskTitle(e.target.value)}
                                placeholder="Enter task title and press Enter..."
                                className="flex-1 bg-white border border-[#D8DDD4] rounded-[8px] px-3 py-1.5 text-xs text-[#18221E] placeholder:text-[#8A958F] focus:border-[#10251F] focus:outline-none shadow-2xs"
                              />
                              <button
                                type="submit"
                                disabled={!inlineTaskTitle.trim()}
                                className="rounded-[8px] bg-[#10251F] px-3 py-1.5 text-xs font-semibold text-white disabled:opacity-40 cursor-pointer"
                              >
                                Add
                              </button>
                              <button
                                type="button"
                                onClick={() => setInlineAddingPhaseId(null)}
                                className="p-1 text-[#8A958F] hover:text-[#18221E] cursor-pointer"
                              >
                                <X size={14} />
                              </button>
                            </form>
                          </td>
                        </tr>
                      ) : (
                        <tr>
                          <td colSpan={7} className="py-2 px-6 bg-[#FAFAF8]/50">
                            <button
                              type="button"
                              onClick={() => {
                                setInlineAddingPhaseId(phase.id);
                                setInlineTaskTitle("");
                              }}
                              className="inline-flex items-center gap-1.5 text-[11px] font-semibold text-[#65706A] hover:text-[#10251F] cursor-pointer"
                            >
                              <Plus size={12} />
                              <span>Add task to {phase.title}</span>
                            </button>
                          </td>
                        </tr>
                      )}
                    </>
                  )}
                </React.Fragment>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { motion, AnimatePresence } from "motion/react";
import { useRouter } from "next/navigation";
import { JobOpening } from "@/types/recruitment";
import { submitCandidateApplicationAction } from "@/lib/recruitment/actions";
import { PrimaryButton } from "@/components/ui/primary-button";

export interface ApplyJobModalProps {
  isOpen: boolean;
  onClose: () => void;
  workspaceId: string;
  jobOpening: JobOpening;
  onSuccess?: () => void;
}

export function ApplyJobModal({
  isOpen,
  onClose,
  workspaceId,
  jobOpening,
  onSuccess,
}: ApplyJobModalProps) {
  const router = useRouter();

  const [fullName, setFullName] = React.useState("");
  const [email, setEmail] = React.useState("");
  const [phone, setPhone] = React.useState("");
  const [portfolioUrl, setPortfolioUrl] = React.useState("");
  const [linkedinUrl, setLinkedinUrl] = React.useState("");
  const [yearsOfExperience, setYearsOfExperience] = React.useState<number | "">("");
  const [skillsStr, setSkillsStr] = React.useState("");
  const [coverLetter, setCoverLetter] = React.useState("");

  // File Upload to R2
  const [file, setFile] = React.useState<File | null>(null);
  const [uploadingCv, setUploadingCv] = React.useState(false);
  const [cvStorageKey, setCvStorageKey] = React.useState("");
  const [cvFileName, setCvFileName] = React.useState("");
  const [cvFileSize, setCvFileSize] = React.useState<number>(0);
  const [cvFileType, setCvFileType] = React.useState("application/pdf");

  const [loading, setLoading] = React.useState(false);
  const [errorMsg, setErrorMsg] = React.useState<string | null>(null);
  const [successMsg, setSuccessMsg] = React.useState<string | null>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selected = e.target.files?.[0];
    if (!selected) return;

    if (selected.size > 15 * 1024 * 1024) {
      setErrorMsg("CV file size exceeds 15MB limit.");
      return;
    }

    setFile(selected);
    setErrorMsg(null);
    setUploadingCv(true);

    try {
      const formData = new FormData();
      formData.append("file", selected);
      formData.append("folder", "resumes");
      formData.append("workspaceId", workspaceId);

      const res = await fetch("/api/upload", {
        method: "POST",
        body: formData,
      });

      const data = await res.json();
      if (data.success && data.key) {
        setCvStorageKey(data.key);
        setCvFileName(selected.name);
        setCvFileSize(selected.size);
        setCvFileType(selected.type || "application/pdf");
      } else {
        setErrorMsg(data.error || "Failed to upload CV.");
      }
    } catch {
      setErrorMsg("Failed to upload CV to storage.");
    } finally {
      setUploadingCv(false);
    }
  };

  const isValid = fullName.trim().length > 1 && email.includes("@") && Boolean(cvStorageKey);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!isValid || loading) return;

    setLoading(true);
    setErrorMsg(null);
    setSuccessMsg(null);

    const skills = skillsStr
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);

    try {
      const res = await submitCandidateApplicationAction({
        workspaceId,
        jobOpeningId: jobOpening.id,
        fullName: fullName.trim(),
        email: email.trim().toLowerCase(),
        phone: phone.trim() || undefined,
        portfolioUrl: portfolioUrl.trim() || undefined,
        linkedinUrl: linkedinUrl.trim() || undefined,
        yearsOfExperience: typeof yearsOfExperience === "number" ? yearsOfExperience : undefined,
        skills,
        coverLetter: coverLetter.trim() || undefined,
        cvStorageKey,
        cvFileName,
        cvFileSize,
        cvFileType,
      });

      if (!res.success) {
        setErrorMsg(res.error || "Failed to submit application.");
        setLoading(false);
        return;
      }

      setSuccessMsg("Application submitted successfully!");
      setLoading(false);
      setTimeout(() => {
        onClose();
        router.refresh();
        if (onSuccess) onSuccess();
      }, 1000);
    } catch {
      setErrorMsg("An unexpected error occurred.");
      setLoading(false);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/40 backdrop-blur-xs"
          />

          <motion.div
            initial={{ opacity: 0, scale: 0.96, y: 10 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.96, y: 10 }}
            className="relative w-full max-w-lg max-h-[90vh] overflow-y-auto rounded-[16px] border border-[#D8DDD4] bg-white p-6 shadow-xl text-[#18221E] space-y-4"
          >
            <div className="flex items-center justify-between border-b border-[#D8DDD4]/60 pb-3">
              <div>
                <h2 className="text-base font-bold text-[#18221E]">Apply for Position</h2>
                <p className="text-xs text-[#65706A]">{jobOpening.title}</p>
              </div>
              <button
                type="button"
                onClick={onClose}
                className="p-1 rounded text-[#65706A] hover:text-[#18221E]"
              >
                ✕
              </button>
            </div>

            {errorMsg && (
              <div className="rounded-[8px] bg-red-50 p-2.5 text-xs text-red-600 border border-red-200">
                {errorMsg}
              </div>
            )}

            {successMsg && (
              <div className="rounded-[8px] bg-[#EAF4E2] p-2.5 text-xs text-[#246244] border border-[#246244]/20 font-medium">
                {successMsg}
              </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-3.5 text-xs">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block font-semibold text-[#18221E] mb-1">Full Name *</label>
                  <input
                    type="text"
                    required
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                    placeholder="Jane Doe"
                    className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs text-[#18221E] focus:border-[#10251F] focus:outline-none"
                  />
                </div>

                <div>
                  <label className="block font-semibold text-[#18221E] mb-1">Email *</label>
                  <input
                    type="email"
                    required
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="jane@example.com"
                    className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs text-[#18221E] focus:border-[#10251F] focus:outline-none"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block font-semibold text-[#18221E] mb-1">Phone Number</label>
                  <input
                    type="tel"
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                    placeholder="+1 (555) 000-0000"
                    className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs text-[#18221E] focus:border-[#10251F] focus:outline-none"
                  />
                </div>

                <div>
                  <label className="block font-semibold text-[#18221E] mb-1">Years of Experience</label>
                  <input
                    type="number"
                    min={0}
                    step={0.5}
                    value={yearsOfExperience}
                    onChange={(e) =>
                      setYearsOfExperience(e.target.value ? Number(e.target.value) : "")
                    }
                    placeholder="e.g. 5"
                    className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs text-[#18221E] focus:border-[#10251F] focus:outline-none"
                  />
                </div>
              </div>

              {/* CV / Resume Upload */}
              <div>
                <label className="block font-semibold text-[#18221E] mb-1">
                  Upload CV / Resume (PDF, DOCX) <span className="text-red-500">*</span>
                </label>
                <div className="rounded-[10px] border border-dashed border-[#D8DDD4] bg-[#FAF9F5] p-3 text-center">
                  <input
                    type="file"
                    accept=".pdf,.doc,.docx"
                    onChange={handleFileChange}
                    className="hidden"
                    id="cv-upload-input"
                  />
                  <label
                    htmlFor="cv-upload-input"
                    className="cursor-pointer text-xs font-semibold text-[#10251F] hover:underline"
                  >
                    {uploadingCv
                      ? "Uploading CV to storage..."
                      : cvFileName
                      ? `Selected: ${cvFileName} (${Math.round(cvFileSize / 1024)} KB) — Click to replace`
                      : "Choose CV File (PDF / DOCX)"}
                  </label>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block font-semibold text-[#18221E] mb-1">LinkedIn Profile</label>
                  <input
                    type="url"
                    value={linkedinUrl}
                    onChange={(e) => setLinkedinUrl(e.target.value)}
                    placeholder="https://linkedin.com/in/..."
                    className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs text-[#18221E] focus:border-[#10251F] focus:outline-none"
                  />
                </div>

                <div>
                  <label className="block font-semibold text-[#18221E] mb-1">Portfolio / GitHub</label>
                  <input
                    type="url"
                    value={portfolioUrl}
                    onChange={(e) => setPortfolioUrl(e.target.value)}
                    placeholder="https://github.com/..."
                    className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs text-[#18221E] focus:border-[#10251F] focus:outline-none"
                  />
                </div>
              </div>

              <div>
                <label className="block font-semibold text-[#18221E] mb-1">Key Skills</label>
                <input
                  type="text"
                  value={skillsStr}
                  onChange={(e) => setSkillsStr(e.target.value)}
                  placeholder="React, TypeScript, Node.js, Next.js"
                  className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs text-[#18221E] focus:border-[#10251F] focus:outline-none"
                />
              </div>

              <div>
                <label className="block font-semibold text-[#18221E] mb-1">Cover Letter / Note</label>
                <textarea
                  rows={2}
                  value={coverLetter}
                  onChange={(e) => setCoverLetter(e.target.value)}
                  placeholder="Why you are interested in this position..."
                  className="w-full rounded-[8px] border border-[#D8DDD4] bg-white p-2 text-xs text-[#18221E] focus:border-[#10251F] focus:outline-none"
                />
              </div>

              <div className="flex items-center justify-end gap-2.5 pt-2 border-t border-[#D8DDD4]/60">
                <button
                  type="button"
                  onClick={onClose}
                  className="rounded-[8px] border border-[#D8DDD4] bg-white px-3.5 py-1.5 text-xs font-semibold text-[#18221E] hover:bg-[#FAF9F5]"
                >
                  Cancel
                </button>
                <PrimaryButton type="submit" disabled={!isValid || loading || uploadingCv} size="sm">
                  {loading ? "Submitting..." : "Submit Application"}
                </PrimaryButton>
              </div>
            </form>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
}

"use client";

import * as React from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  Candidate,
  CandidateApplication,
  CandidateActivity,
  Interview,
  JobOffer,
  CandidateStage,
} from "@/types/recruitment";
import { Department } from "@/types/department";
import { WorkspacePerson } from "@/types/people";
import {
  updateApplicationStageAction,
  assignCandidateRecruiterAction,
  updateCandidateTagsAction,
  addCandidateNoteAction,
  deleteCandidateNoteAction,
  archiveCandidateAction,
  completeInterviewAction,
  sendOfferAction,
  withdrawOfferAction,
} from "@/lib/recruitment/actions";
import { ScheduleInterviewModal } from "./schedule-interview-modal";
import { SubmitFeedbackModal } from "./submit-feedback-modal";
import { RejectCandidateModal } from "./reject-candidate-modal";
import { ConvertToEmployeeModal } from "./convert-to-employee-modal";
import { AppIcon } from "@/components/ui/app-icon";
import { CreateOfferModal } from "./create-offer-modal";
import { CompleteHiringModal } from "./complete-hiring-modal";

export interface CandidateDetailViewProps {
  workspaceId: string;
  workspaceName?: string;
  userRole: string;
  candidate: Candidate;
  applications: CandidateApplication[];
  interviews?: Interview[];
  offers?: JobOffer[];
  activities: CandidateActivity[];
  departments: Department[];
  teamMembers: WorkspacePerson[];
}

type TabKey = "overview" | "applications" | "offers" | "notes" | "resume" | "interviews" | "activity";

const STAGES: CandidateStage[] = [
  "Applied",
  "Screening",
  "Shortlisted",
  "Interview",
  "Feedback",
  "Offer",
  "Hired",
  "Rejected",
  "Archived",
];

const PRESET_TAGS = ["Senior", "Strong Candidate", "Remote", "Urgent", "Needs Review", "High Salary", "Culture Fit"];

export function CandidateDetailView({
  workspaceId,
  workspaceName = "Workspace",
  userRole,
  candidate,
  applications,
  interviews = [],
  offers = [],
  activities = [],
  departments,
  teamMembers,
}: CandidateDetailViewProps) {
  const router = useRouter();
  const [activeTab, setActiveTab] = React.useState<TabKey>("overview");
  const [currentStage, setCurrentStage] = React.useState<CandidateStage>(
    candidate.latest_stage || "Applied"
  );
  const [updatingStage, setUpdatingStage] = React.useState(false);
  const [copiedEmail, setCopiedEmail] = React.useState(false);
  const [copiedOfferLink, setCopiedOfferLink] = React.useState<string | null>(null);

  // Notes state
  const [newNoteContent, setNewNoteContent] = React.useState("");
  const [submittingNote, setSubmittingNote] = React.useState(false);

  // Tags state
  const [customTagInput, setCustomTagInput] = React.useState("");
  const [tags, setTags] = React.useState<string[]>(candidate.tags || []);

  // Modals state
  const [scheduleModalOpen, setScheduleModalOpen] = React.useState(false);
  const [rejectModalOpen, setRejectModalOpen] = React.useState(false);
  const [createOfferOpen, setCreateOfferOpen] = React.useState(false);
  const [completeHiringOpen, setCompleteHiringOpen] = React.useState(false);
  const [feedbackInterview, setFeedbackInterview] = React.useState<Interview | null>(null);
  const [selectedOfferForHire, setSelectedOfferForHire] = React.useState<JobOffer | undefined>(undefined);

  const canManage = ["owner", "admin", "manager"].includes(userRole);
  const latestApp = applications[0] || {
    id: candidate.latest_application_id || candidate.id,
    workspace_id: workspaceId,
    candidate_id: candidate.id,
    job_opening_id: candidate.latest_job_id || "",
    stage: currentStage,
    created_at: candidate.created_at,
    updated_at: candidate.created_at,
  };

  const isHired = candidate.latest_stage === "Hired" || Boolean(candidate.converted_user_id);
  const acceptedOffer = offers.find((o) => o.status === "Accepted");

  const initials = candidate.full_name
    .split(" ")
    .map((n) => n[0])
    .join("")
    .substring(0, 2)
    .toUpperCase();

  const handleStageChange = async (newStage: CandidateStage) => {
    setCurrentStage(newStage);
    setUpdatingStage(true);
    try {
      await updateApplicationStageAction({
        workspaceId,
        applicationId: latestApp.id,
        candidateId: candidate.id,
        toStage: newStage,
      });
      router.refresh();
    } catch (err) {
      console.error("Failed to update stage:", err);
    } finally {
      setUpdatingStage(false);
    }
  };

  const handleAssignRecruiter = async (userId: string) => {
    const selected = teamMembers.find((m) => m.user_id === userId);
    await assignCandidateRecruiterAction({
      workspaceId,
      candidateId: candidate.id,
      applicationId: latestApp.id,
      recruiterId: selected ? selected.user_id : null,
      recruiterName: selected ? (selected.full_name || null) : null,
    });
    router.refresh();
  };

  const handleAddTag = async (tagToAdd: string) => {
    const trimmed = tagToAdd.trim();
    if (!trimmed || tags.includes(trimmed)) return;
    const updated = [...tags, trimmed];
    setTags(updated);
    setCustomTagInput("");
    await updateCandidateTagsAction({
      workspaceId,
      candidateId: candidate.id,
      tags: updated,
    });
    router.refresh();
  };

  const handleRemoveTag = async (tagToRemove: string) => {
    const updated = tags.filter((t) => t !== tagToRemove);
    setTags(updated);
    await updateCandidateTagsAction({
      workspaceId,
      candidateId: candidate.id,
      tags: updated,
    });
    router.refresh();
  };

  const handleAddNote = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newNoteContent.trim() || submittingNote) return;
    setSubmittingNote(true);
    try {
      await addCandidateNoteAction({
        workspaceId,
        candidateId: candidate.id,
        content: newNoteContent.trim(),
      });
      setNewNoteContent("");
      router.refresh();
    } catch (err) {
      console.error("Failed to add note:", err);
    } finally {
      setSubmittingNote(false);
    }
  };

  const handleDeleteNote = async (noteId: string) => {
    if (!confirm("Are you sure you want to delete this internal note?")) return;
    await deleteCandidateNoteAction({
      workspaceId,
      candidateId: candidate.id,
      noteId,
    });
    router.refresh();
  };

  const handleArchiveToggle = async () => {
    const targetState = !candidate.is_archived;
    await archiveCandidateAction({
      workspaceId,
      candidateId: candidate.id,
      isArchived: targetState,
    });
    router.refresh();
  };

  const handleSendOffer = async (offerId: string) => {
    await sendOfferAction({
      workspaceId,
      offerId,
    });
    router.refresh();
  };

  const handleWithdrawOffer = async (offerId: string) => {
    if (!confirm("Are you sure you want to withdraw this job offer?")) return;
    await withdrawOfferAction({
      workspaceId,
      offerId,
      reason: "Withdrawn by hiring team",
    });
    router.refresh();
  };

  const handleCopyOfferLink = (offer: JobOffer) => {
    if (typeof window !== "undefined") {
      const url = `${window.location.origin}/jobs/offers/${offer.token || offer.id}`;
      navigator.clipboard.writeText(url);
      setCopiedOfferLink(offer.id);
      setTimeout(() => setCopiedOfferLink(null), 2000);
    }
  };

  const handleCompleteInterview = async (interviewId: string) => {
    await completeInterviewAction({
      workspaceId,
      interviewId,
    });
    router.refresh();
  };

  const handleCopyEmail = () => {
    if (typeof window !== "undefined" && candidate.email) {
      navigator.clipboard.writeText(candidate.email);
      setCopiedEmail(true);
      setTimeout(() => setCopiedEmail(false), 2000);
    }
  };

  const cvKey = candidate.cv_storage_key || latestApp.cv_storage_key;
  const cvUrl = cvKey ? `/api/storage/${cvKey}` : null;
  const cvFileName = candidate.cv_file_name || latestApp.cv_file_name || "Resume.pdf";
  const cvFileSize = candidate.cv_file_size || latestApp.cv_file_size;

  const getStageBadgeColor = (stage?: CandidateStage) => {
    switch (stage) {
      case "Applied":
        return "bg-sky-50 text-sky-700 border-sky-200";
      case "Screening":
        return "bg-indigo-50 text-indigo-700 border-indigo-200";
      case "Shortlisted":
        return "bg-purple-50 text-purple-700 border-purple-200";
      case "Interview":
        return "bg-amber-50 text-amber-700 border-amber-200";
      case "Feedback":
        return "bg-teal-50 text-teal-700 border-teal-200";
      case "Offer":
        return "bg-emerald-50 text-emerald-700 border-emerald-200";
      case "Hired":
        return "bg-[#EAF4E2] text-[#246244] border-[#246244]/20 font-bold";
      case "Rejected":
      case "Archived":
      case "Withdrawn":
      case "Expired":
        return "bg-stone-100 text-stone-600 border-stone-200";
      default:
        return "bg-stone-100 text-stone-700";
    }
  };

  const getOfferBadgeColor = (status: string) => {
    switch (status) {
      case "Draft":
        return "bg-stone-100 text-stone-700 border-stone-200";
      case "Sent":
        return "bg-sky-50 text-sky-700 border-sky-200";
      case "Viewed":
        return "bg-purple-50 text-purple-700 border-purple-200";
      case "Accepted":
        return "bg-[#EAF4E2] text-[#246244] border-[#246244]/20 font-bold";
      case "Declined":
      case "Withdrawn":
      case "Expired":
        return "bg-red-50 text-red-700 border-red-200";
      default:
        return "bg-stone-100 text-stone-700 border-stone-200";
    }
  };

  return (
    <div className="mx-auto max-w-[1200px] space-y-6 pb-24 text-[#18221E]">
      {/* 1. BREADCRUMB */}
      <div className="flex items-center gap-2 text-xs text-[#65706A]">
        <Link href="/app" className="hover:text-[#18221E] transition-colors">
          {workspaceName}
        </Link>
        <span>/</span>
        <Link href="/app/people" className="hover:text-[#18221E] transition-colors">
          People & Candidates
        </Link>
        <span>/</span>
        <span className="font-semibold text-[#18221E]">{candidate.full_name}</span>
      </div>

      {/* HIRING NOTIFICATION BANNER (IF ACCEPTED BUT NOT HIRED) */}
      {acceptedOffer && !isHired && canManage && (
        <div className="rounded-[14px] bg-[#EAF4E2] border border-[#246244]/30 p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-3 shadow-2xs">
          <div className="flex items-center gap-3">
            <span className="text-2xl">🎉</span>
            <div>
              <p className="font-bold text-xs text-[#246244]">Offer Accepted by Candidate!</p>
              <p className="text-[11px] text-[#246244]/80">
                {candidate.full_name} accepted the offer for {acceptedOffer.job_title}. Confirm to activate as employee in Team Directory.
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={() => {
              setSelectedOfferForHire(acceptedOffer);
              setCompleteHiringOpen(true);
            }}
            className="rounded-[8px] bg-[#10251F] text-white px-4 py-2 text-xs font-bold hover:bg-[#18342C] transition-colors shadow-2xs whitespace-nowrap"
          >
            Complete Hiring →
          </button>
        </div>
      )}

      {/* 2. CANDIDATE PROFILE HEADER CARD */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 rounded-[16px] border border-[#D8DDD4] bg-white p-6 shadow-2xs">
        <div className="flex items-center gap-4 min-w-0">
          <div className="flex h-14 w-14 shrink-0 items-center justify-center rounded-full bg-[#10251F] text-lg font-bold text-white shadow-2xs">
            {initials}
          </div>
          <div className="min-w-0">
            <div className="flex items-center gap-2.5 flex-wrap">
              <h1 className="text-xl font-bold tracking-tight text-[#18221E] truncate">
                {candidate.full_name}
              </h1>
              <span
                className={`rounded-full border px-2.5 py-0.5 text-xs font-semibold ${getStageBadgeColor(
                  currentStage
                )}`}
              >
                {currentStage}
              </span>
              {isHired && (
                <span className="rounded-full bg-[#EAF4E2] border border-[#246244]/30 px-2.5 py-0.5 text-xs font-bold text-[#246244]">
                  ✓ Active Employee
                </span>
              )}
              {candidate.is_archived && (
                <span className="rounded-full bg-stone-100 border border-stone-200 px-2 py-0.5 text-[10px] font-bold text-stone-600">
                  Archived
                </span>
              )}
            </div>
            <p className="mt-1 text-xs text-[#65706A] truncate">
              {candidate.latest_job_title || latestApp.job_opening?.title || "Candidate"} • {candidate.email}{" "}
              {candidate.phone && `• ${candidate.phone}`}
            </p>
          </div>
        </div>

        {/* Header Actions */}
        <div className="flex items-center gap-2 flex-wrap shrink-0">
          {/* If already hired, view employee profile & onboarding */}
          {candidate.converted_user_id ? (
            <div className="flex items-center gap-2">
              <Link
                href={`/app/people/${candidate.converted_user_id}`}
                className="rounded-[8px] bg-[#EAF4E2] text-[#246244] border border-[#246244]/30 px-3.5 py-1.5 text-xs font-bold hover:bg-[#d8edd0] transition-colors"
              >
                View Employee Profile →
              </Link>
              <Link
                href={`/app/people/onboarding/${candidate.converted_user_id}`}
                className="rounded-[8px] border border-[#D8DDD4] bg-[#FAF9F5] px-3.5 py-1.5 text-xs font-bold text-[#18221E] hover:bg-white transition-colors"
              >
                Onboarding →
              </Link>
            </div>
          ) : (
            <>
              {/* If stage is Hired, prominent Hire Candidate button */}
              {currentStage === "Hired" && canManage && (
                <button
                  type="button"
                  onClick={() => setCompleteHiringOpen(true)}
                  className="rounded-[8px] bg-[#246244] text-white px-3.5 py-1.5 text-xs font-bold hover:bg-[#1b4a33] transition-colors shadow-2xs"
                >
                  ✓ Hire Candidate
                </button>
              )}

              {/* Recruiter Selector */}
              {canManage && (
                <div className="flex items-center gap-1.5 bg-[#FAF9F5] border border-[#D8DDD4] rounded-[8px] px-2.5 py-1">
                  <span className="text-[10px] font-bold uppercase text-[#65706A]">Assigned:</span>
                  <select
                    value={candidate.assigned_recruiter_id || ""}
                    onChange={(e) => handleAssignRecruiter(e.target.value)}
                    className="bg-transparent text-xs font-semibold text-[#18221E] focus:outline-none cursor-pointer"
                  >
                    <option value="">Unassigned</option>
                    {teamMembers.map((m) => (
                      <option key={m.user_id} value={m.user_id}>
                        {m.full_name}
                      </option>
                    ))}
                  </select>
                </div>
              )}

              {/* Move Stage Selector */}
              {canManage && (
                <div className="flex items-center gap-1.5 bg-[#FAF9F5] border border-[#D8DDD4] rounded-[8px] px-2.5 py-1">
                  <span className="text-[10px] font-bold uppercase text-[#65706A]">Stage:</span>
                  <select
                    value={currentStage}
                    disabled={updatingStage}
                    onChange={(e) => handleStageChange(e.target.value as CandidateStage)}
                    className="bg-transparent text-xs font-semibold text-[#18221E] focus:outline-none cursor-pointer"
                  >
                    {STAGES.map((stg) => (
                      <option key={stg} value={stg}>
                        {stg}
                      </option>
                    ))}
                  </select>
                </div>
              )}

              {/* Create Offer Button */}
              {canManage && (
                <button
                  type="button"
                  onClick={() => setCreateOfferOpen(true)}
                  className="rounded-[8px] bg-[#10251F] text-white px-3 py-1.5 text-xs font-bold hover:bg-[#18342C] transition-colors shadow-2xs"
                >
                  💼 Create Offer
                </button>
              )}

              {/* Schedule Interview */}
              {canManage && (
                <button
                  type="button"
                  onClick={() => setScheduleModalOpen(true)}
                  className="rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs font-bold text-[#18221E] hover:bg-[#FAF9F5] transition-colors shadow-2xs"
                >
                  📅 Interview
                </button>
              )}

              {/* Reject */}
              {canManage && currentStage !== "Rejected" && (
                <button
                  type="button"
                  onClick={() => setRejectModalOpen(true)}
                  className="rounded-[8px] border border-red-200 bg-white px-3 py-1.5 text-xs font-semibold text-red-600 hover:bg-red-50 transition-colors shadow-2xs"
                >
                  Reject
                </button>
              )}
            </>
          )}

          {/* Archive / Unarchive */}
          {canManage && (
            <button
              type="button"
              onClick={handleArchiveToggle}
              className="rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs font-semibold text-[#65706A] hover:text-[#18221E] hover:bg-[#FAF9F5] transition-colors"
            >
              {candidate.is_archived ? "Unarchive" : "Archive"}
            </button>
          )}
        </div>
      </div>

      {/* 3. PROFILE TABS */}
      <div className="flex items-center gap-6 border-b border-[#D8DDD4] text-xs font-medium text-[#65706A] overflow-x-auto">
        {[
          { key: "overview", label: "Overview" },
          { key: "offers", label: `Job Offers (${offers.length})` },
          { key: "applications", label: `Applications (${applications.length})` },
          { key: "notes", label: `Private Notes (${candidate.notes_list?.length || 0})` },
          { key: "resume", label: "Resume / CV" },
          { key: "interviews", label: `Interviews (${interviews.length})` },
          { key: "activity", label: `Activity Log (${activities.length})` },
        ].map((tab) => (
          <button
            key={tab.key}
            type="button"
            onClick={() => setActiveTab(tab.key as TabKey)}
            className={`pb-3 whitespace-nowrap transition-colors ${
              activeTab === tab.key
                ? "border-b-2 border-[#10251F] font-semibold text-[#18221E] -mb-px"
                : "hover:text-[#18221E]"
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* 4. TAB CONTENTS */}

      {/* TAB 1: OVERVIEW */}
      {activeTab === "overview" && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
          {/* Left: Contact Info, Summary, & Tags */}
          <div className="lg:col-span-7 space-y-6">
            {/* Contact Details */}
            <div className="rounded-[14px] border border-[#D8DDD4] bg-white p-6 shadow-2xs space-y-4">
              <h3 className="text-sm font-bold text-[#18221E]">Contact & Background</h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 text-xs">
                <div>
                  <span className="text-[10px] font-bold uppercase tracking-wider text-[#65706A] block">
                    Full Name
                  </span>
                  <p className="font-semibold text-[#18221E] mt-0.5">{candidate.full_name}</p>
                </div>

                <div>
                  <span className="text-[10px] font-bold uppercase tracking-wider text-[#65706A] block">
                    Email Address
                  </span>
                  <div className="flex items-center gap-1.5 mt-0.5">
                    <a href={`mailto:${candidate.email}`} className="font-semibold text-[#18221E] hover:underline truncate">
                      {candidate.email}
                    </a>
                    <button
                      type="button"
                      onClick={handleCopyEmail}
                      className="text-[10px] text-[#65706A] hover:text-[#18221E] border border-[#D8DDD4] rounded px-1 py-0.5"
                    >
                      {copiedEmail ? "✓" : "Copy"}
                    </button>
                  </div>
                </div>

                <div>
                  <span className="text-[10px] font-bold uppercase tracking-wider text-[#65706A] block">
                    Phone Number
                  </span>
                  <p className="font-semibold text-[#18221E] mt-0.5">
                    {candidate.phone ? (
                      <a href={`tel:${candidate.phone}`} className="hover:underline">
                        {candidate.phone}
                      </a>
                    ) : (
                      "Not provided"
                    )}
                  </p>
                </div>

                <div>
                  <span className="text-[10px] font-bold uppercase tracking-wider text-[#65706A] block">
                    Location
                  </span>
                  <p className="font-semibold text-[#18221E] mt-0.5">
                    {candidate.location || latestApp.job_opening?.location || "Not provided"}
                  </p>
                </div>

                <div>
                  <span className="text-[10px] font-bold uppercase tracking-wider text-[#65706A] block">
                    Years of Experience
                  </span>
                  <p className="font-semibold text-[#18221E] mt-0.5">
                    {candidate.years_of_experience ? `${candidate.years_of_experience} years` : "Not provided"}
                  </p>
                </div>

                <div>
                  <span className="text-[10px] font-bold uppercase tracking-wider text-[#65706A] block">
                    Application Date
                  </span>
                  <p className="font-semibold text-[#18221E] mt-0.5">
                    {new Date(candidate.created_at).toLocaleDateString("en-US", {
                      month: "short",
                      day: "numeric",
                      year: "numeric",
                    })}
                  </p>
                </div>
              </div>
            </div>

            {/* Tags Section */}
            <div className="rounded-[14px] border border-[#D8DDD4] bg-white p-6 shadow-2xs space-y-3">
              <h3 className="text-sm font-bold text-[#18221E]">Recruitment Tags</h3>
              <div className="flex flex-wrap gap-1.5 items-center">
                {tags.map((tag) => (
                  <span
                    key={tag}
                    className="inline-flex items-center gap-1.5 rounded-full border border-[#D8DDD4] bg-[#FAF9F5] px-3 py-1 text-xs font-semibold text-[#18221E]"
                  >
                    <span>{tag}</span>
                    {canManage && (
                      <button
                        type="button"
                        onClick={() => handleRemoveTag(tag)}
                        className="text-[#65706A] hover:text-red-600 text-xs font-bold"
                      >
                        ✕
                      </button>
                    )}
                  </span>
                ))}
              </div>

              {canManage && (
                <div className="pt-2 space-y-2 border-t border-[#D8DDD4]/60">
                  <div className="flex items-center gap-2">
                    <input
                      type="text"
                      value={customTagInput}
                      onChange={(e) => setCustomTagInput(e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          e.preventDefault();
                          handleAddTag(customTagInput);
                        }
                      }}
                      placeholder="Add tag (e.g. Senior, Urgent)..."
                      className="rounded-[8px] border border-[#D8DDD4] bg-[#FAF9F5] px-3 py-1 text-xs focus:border-[#10251F] focus:outline-none"
                    />
