"use client";

import * as React from "react";
import Link from "next/link";
import { Candidate, CandidateStage } from "@/types/recruitment";
import { Department } from "@/types/department";
import { WorkspacePerson } from "@/types/people";
import {
  updateApplicationStageAction,
  assignCandidateRecruiterAction,
  updateCandidateTagsAction,
  addCandidateNoteAction,
  deleteCandidateNoteAction,
  archiveCandidateAction,
} from "@/lib/recruitment/actions";
import { RejectCandidateModal } from "./reject-candidate-modal";
import { AppIcon } from "@/components/ui/app-icon";

export interface CandidateProfileDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  candidate: Candidate | null;
  workspaceId: string;
  userRole: string;
  departments: Department[];
  teamMembers: WorkspacePerson[];
  onScheduleInterview: (candidate: Candidate) => void;
  onCreateOffer: (candidate: Candidate) => void;
  onConvertToEmployee: (candidate: Candidate) => void;
  onStageUpdated?: () => void;
}

const STAGES: CandidateStage[] = [
  "Applied",
  "Screening",
  "Shortlisted",
  "Interview",
  "Feedback",
  "Offer",
  "Hired",
  "Rejected",
  "Archived",
];

const PRESET_TAGS = ["Senior", "Strong Candidate", "Remote", "Urgent", "Needs Review"];

export function CandidateProfileDrawer({
  isOpen,
  onClose,
  candidate,
  workspaceId,
  userRole,
  departments,
  teamMembers,
  onScheduleInterview,
  onCreateOffer,
  onConvertToEmployee,
  onStageUpdated,
}: CandidateProfileDrawerProps) {
  const [currentStage, setCurrentStage] = React.useState<CandidateStage>(
    candidate?.latest_stage || "Applied"
  );
  const [updatingStage, setUpdatingStage] = React.useState(false);
  const [copiedEmail, setCopiedEmail] = React.useState(false);
  const [activeTab, setActiveTab] = React.useState<"overview" | "notes" | "history">("overview");

  // Notes state
  const [newNoteContent, setNewNoteContent] = React.useState("");
  const [submittingNote, setSubmittingNote] = React.useState(false);

  // Reject modal
  const [rejectModalOpen, setRejectModalOpen] = React.useState(false);

  // Tags state
  const [tags, setTags] = React.useState<string[]>(candidate?.tags || []);
  const [customTagInput, setCustomTagInput] = React.useState("");

  React.useEffect(() => {
    if (candidate?.latest_stage) {
      setCurrentStage(candidate.latest_stage);
    }
    if (candidate?.tags) {
      setTags(candidate.tags);
    }
  }, [candidate]);

  // Handle escape key
  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isOpen) {
        onClose();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose]);

  if (!isOpen || !candidate) return null;

  const canManage = ["owner", "admin", "manager"].includes(userRole);

  const initials = candidate.full_name
    .split(" ")
    .map((n) => n[0])
    .join("")
    .substring(0, 2)
    .toUpperCase();

  const handleStageSelect = async (newStage: CandidateStage) => {
    setCurrentStage(newStage);
    setUpdatingStage(true);
    try {
      await updateApplicationStageAction({
        workspaceId,
        applicationId: candidate.latest_application_id || candidate.id,
        candidateId: candidate.id,
        toStage: newStage,
      });
      if (onStageUpdated) onStageUpdated();
    } catch (err) {
      console.error("Failed to update stage:", err);
    } finally {
      setUpdatingStage(false);
    }
  };

  const handleAssignRecruiter = async (userId: string) => {
    const selected = teamMembers.find((m) => m.user_id === userId);
    await assignCandidateRecruiterAction({
      workspaceId,
      candidateId: candidate.id,
      applicationId: candidate.latest_application_id,
      recruiterId: selected ? selected.user_id : null,
      recruiterName: selected ? selected.full_name : null,
    });
    if (onStageUpdated) onStageUpdated();
  };

  const handleAddTag = async (tagToAdd: string) => {
    const trimmed = tagToAdd.trim();
    if (!trimmed || tags.includes(trimmed)) return;
    const updated = [...tags, trimmed];
    setTags(updated);
    setCustomTagInput("");
    await updateCandidateTagsAction({
      workspaceId,
      candidateId: candidate.id,
      tags: updated,
    });
    if (onStageUpdated) onStageUpdated();
  };

  const handleRemoveTag = async (tagToRemove: string) => {
    const updated = tags.filter((t) => t !== tagToRemove);
    setTags(updated);
    await updateCandidateTagsAction({
      workspaceId,
      candidateId: candidate.id,
      tags: updated,
    });
    if (onStageUpdated) onStageUpdated();
  };

  const handleAddNote = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newNoteContent.trim() || submittingNote) return;
    setSubmittingNote(true);
    try {
      await addCandidateNoteAction({
        workspaceId,
        candidateId: candidate.id,
        content: newNoteContent.trim(),
      });
      setNewNoteContent("");
      if (onStageUpdated) onStageUpdated();
    } catch (err) {
      console.error("Failed to add note:", err);
    } finally {
      setSubmittingNote(false);
    }
  };

  const handleDeleteNote = async (noteId: string) => {
    await deleteCandidateNoteAction({
      workspaceId,
      candidateId: candidate.id,
      noteId,
    });
    if (onStageUpdated) onStageUpdated();
  };

  const handleArchiveToggle = async () => {
    await archiveCandidateAction({
      workspaceId,
      candidateId: candidate.id,
      isArchived: !candidate.is_archived,
    });
    if (onStageUpdated) onStageUpdated();
  };

  const handleCopyEmail = () => {
    if (typeof window !== "undefined" && candidate.email) {
      navigator.clipboard.writeText(candidate.email);
      setCopiedEmail(true);
      setTimeout(() => setCopiedEmail(false), 2000);
    }
  };

  const getStageBadgeColor = (stage?: CandidateStage) => {
    switch (stage) {
      case "Applied":
        return "bg-sky-50 text-sky-700 border-sky-200";
      case "Screening":
        return "bg-indigo-50 text-indigo-700 border-indigo-200";
      case "Shortlisted":
        return "bg-purple-50 text-purple-700 border-purple-200";
      case "Interview":
        return "bg-amber-50 text-amber-700 border-amber-200";
      case "Feedback":
        return "bg-teal-50 text-teal-700 border-teal-200";
      case "Offer":
        return "bg-emerald-50 text-emerald-700 border-emerald-200";
      case "Hired":
        return "bg-[#EAF4E2] text-[#246244] border-[#246244]/20 font-bold";
      case "Rejected":
      case "Archived":
      case "Withdrawn":
      case "Expired":
        return "bg-stone-100 text-stone-600 border-stone-200";
      default:
        return "bg-stone-100 text-stone-700";
    }
  };

  const cvUrl = candidate.cv_storage_key
    ? `/api/storage/${candidate.cv_storage_key}`
    : null;

  return (
    <>
      {/* Backdrop */}
      <div
        onClick={onClose}
        className="fixed inset-0 z-40 bg-black/30 backdrop-blur-2xs transition-opacity duration-300"
      />

      {/* Slide-over Drawer Panel */}
      <aside
        className="fixed inset-y-0 right-0 z-50 flex w-full max-w-[540px] flex-col border-l border-[#D8DDD4] bg-white shadow-2xl transition-transform duration-300 ease-out"
        role="dialog"
        aria-modal="true"
      >
        {/* Header */}
        <div className="flex items-center justify-between border-b border-[#D8DDD4] px-6 py-4 bg-[#FAF9F5]/80">
          <div className="flex items-center gap-2">
            <span className="text-xs font-bold uppercase tracking-wider text-[#65706A]">
              Candidate Profile
            </span>
            <span
              className={`rounded-full border px-2 py-0.5 text-[10px] font-semibold ${getStageBadgeColor(
                currentStage
              )}`}
            >
              {currentStage}
            </span>
          </div>

          <div className="flex items-center gap-2">
            <Link
              href={`/app/people/candidates/${candidate.id}`}
              className="text-xs font-bold text-[#10251F] hover:underline"
            >
              Full Profile ↗
            </Link>
            <button
              type="button"
              onClick={onClose}
              className="flex h-7 w-7 items-center justify-center rounded-full hover:bg-[#E2E8D8] text-[#65706A] hover:text-[#18221E] transition-colors"
            >
              ✕
            </button>
          </div>
        </div>

        {/* Candidate Summary Box */}
        <div className="border-b border-[#D8DDD4] p-6 bg-white space-y-4">
          <div className="flex items-start gap-4">
            <div className="flex h-14 w-14 shrink-0 items-center justify-center rounded-full bg-[#10251F] text-lg font-bold text-white shadow-2xs">
              {initials}
            </div>

            <div className="min-w-0 flex-1">
              <h2 className="text-lg font-bold text-[#18221E] truncate">
                {candidate.full_name}
              </h2>
              <p className="text-xs text-[#65706A] truncate">
                {candidate.latest_job_title || "General Application"}
              </p>
              <div className="flex items-center gap-2 mt-1">
                <span className="text-xs text-[#18221E] font-medium truncate">
                  {candidate.email}
                </span>
                <button
                  type="button"
                  onClick={handleCopyEmail}
                  className="rounded border border-[#D8DDD4] bg-[#FAF9F5] px-1.5 py-0.5 text-[10px] text-[#65706A] hover:text-[#18221E]"
                >
                  {copiedEmail ? "✓ Copied" : "Copy"}
                </button>
              </div>
            </div>
          </div>

          {/* Quick Info & Recruiter Selector */}
          <div className="grid grid-cols-2 gap-3 pt-2 text-xs border-t border-[#D8DDD4]/60">
            <div>
              <span className="text-[10px] font-bold uppercase text-[#65706A] block">
                Assigned Recruiter
              </span>
              {canManage ? (
                <select
                  value={candidate.assigned_recruiter_id || ""}
                  onChange={(e) => handleAssignRecruiter(e.target.value)}
                  className="mt-0.5 w-full rounded border border-[#D8DDD4] bg-[#FAF9F5] p-1 text-xs font-semibold text-[#18221E] focus:outline-none"
                >
                  <option value="">Unassigned</option>
                  {teamMembers.map((m) => (
                    <option key={m.user_id} value={m.user_id}>
                      {m.full_name}
                    </option>
                  ))}
                </select>
              ) : (
                <p className="font-semibold text-[#18221E]">
                  {candidate.assigned_recruiter_name || "Unassigned"}
                </p>
              )}
            </div>

            <div>
              <span className="text-[10px] font-bold uppercase text-[#65706A] block">
                Current Stage
              </span>
              {canManage ? (
                <select
                  value={currentStage}
                  disabled={updatingStage}
                  onChange={(e) => handleStageSelect(e.target.value as CandidateStage)}
                  className="mt-0.5 w-full rounded border border-[#D8DDD4] bg-[#FAF9F5] p-1 text-xs font-semibold text-[#18221E] focus:outline-none"
                >
                  {STAGES.map((s) => (
                    <option key={s} value={s}>
                      {s}
                    </option>
                  ))}
                </select>
              ) : (
                <p className="font-semibold text-[#18221E]">{currentStage}</p>
              )}
            </div>
          </div>

          {/* Tags Chips */}
          <div className="pt-2 border-t border-[#D8DDD4]/60 space-y-1.5">
            <span className="text-[10px] font-bold uppercase text-[#65706A] block">
              Internal Tags
            </span>
            <div className="flex flex-wrap gap-1 items-center">
              {tags.map((tag) => (
                <span
                  key={tag}
                  className="inline-flex items-center gap-1 rounded-full border border-[#D8DDD4] bg-[#FAF9F5] px-2 py-0.5 text-[11px] font-semibold text-[#18221E]"
                >
                  <span>{tag}</span>
                  {canManage && (
                    <button
                      type="button"
                      onClick={() => handleRemoveTag(tag)}
                      className="text-[#65706A] hover:text-red-600 font-bold"
                    >
                      ✕
                    </button>
                  )}
                </span>
              ))}

              {canManage && (
                <div className="flex items-center gap-1">
                  <input
                    type="text"
                    value={customTagInput}
                    onChange={(e) => setCustomTagInput(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") {
                        e.preventDefault();
                        handleAddTag(customTagInput);
                      }
                    }}
                    placeholder="+ Tag..."
                    className="w-16 rounded border border-[#D8DDD4] bg-[#FAF9F5] px-1.5 py-0.5 text-[10px] focus:outline-none focus:w-28 transition-all"
                  />
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Navigation Tabs */}
        <div className="flex items-center border-b border-[#D8DDD4] px-6 text-xs font-semibold text-[#65706A]">
          {[
            { key: "overview", label: "Overview" },
            { key: "notes", label: `Notes (${candidate.notes_list?.length || 0})` },
            { key: "history", label: "History" },
          ].map((tab) => (
            <button
              key={tab.key}
              type="button"
              onClick={() => setActiveTab(tab.key as any)}
              className={`py-3 px-3 transition-colors ${
                activeTab === tab.key
                  ? "border-b-2 border-[#10251F] text-[#18221E] -mb-px font-bold"
                  : "hover:text-[#18221E]"
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* Tab Body */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6 text-xs">
          {activeTab === "overview" && (
            <div className="space-y-5">
              {/* CV Section */}
              <div className="rounded-[10px] border border-[#D8DDD4] bg-[#FAF9F5] p-3.5 space-y-2">
                <span className="font-bold text-[#18221E] block text-xs">Resume / CV</span>
                {cvUrl ? (
                  <div className="flex items-center justify-between">
                    <span className="text-[#65706A] truncate flex items-center gap-1.5">
                      <AppIcon name="document" size={13} />
                      <span>{candidate.cv_file_name || "Resume.pdf"}</span>
                    </span>
                    <a
                      href={cvUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="rounded bg-[#10251F] text-white px-3 py-1 text-xs font-bold hover:bg-[#18342C]"
                    >
                      Download CV ↗
                    </a>
                  </div>
                ) : (
                  <p className="text-[#8C9489]">No resume uploaded.</p>
                )}
              </div>

              {/* Summary / Bio */}
              <div className="space-y-1">
                <span className="font-bold text-[#18221E] block">Professional Summary</span>
                <p className="text-[#65706A] leading-relaxed rounded-[8px] bg-[#FAF9F5] p-3 border border-[#D8DDD4]">
                  {candidate.bio || candidate.cover_letter || "Not provided"}
                </p>
              </div>

              {/* Skills */}
              <div className="space-y-1.5">
                <span className="font-bold text-[#18221E] block">Skills</span>
                {candidate.skills && candidate.skills.length > 0 ? (
                  <div className="flex flex-wrap gap-1">
                    {candidate.skills.map((s) => (
                      <span
                        key={s}
                        className="rounded border border-[#D8DDD4] bg-[#FAF9F5] px-2 py-0.5 text-[11px] font-semibold text-[#18221E]"
                      >
                        {s}
                      </span>
                    ))}
                  </div>
                ) : (
                  <p className="text-[#8C9489]">Not provided</p>
                )}
              </div>

              {/* Online Links */}
              <div className="space-y-2">
                <span className="font-bold text-[#18221E] block">Online Links</span>
                {candidate.linkedin_url && (
                  <a
                    href={candidate.linkedin_url}
                    target="_blank"
                    rel="noreferrer"
                    className="block text-[#246244] font-semibold hover:underline truncate"
                  >
                    🔗 LinkedIn: {candidate.linkedin_url}
                  </a>
                )}
                {candidate.portfolio_url && (
                  <a
                    href={candidate.portfolio_url}
                    target="_blank"
                    rel="noreferrer"
                    className="block text-[#246244] font-semibold hover:underline truncate"
                  >
                    🌐 Portfolio: {candidate.portfolio_url}
                  </a>
                )}
                {candidate.github_url && (
                  <a
                    href={candidate.github_url}
                    target="_blank"
                    rel="noreferrer"
                    className="block text-[#246244] font-semibold hover:underline truncate"
                  >
                    🐙 GitHub: {candidate.github_url}
                  </a>
                )}
              </div>
            </div>
          )}

          {activeTab === "notes" && (
            <div className="space-y-4">
              {/* Add note */}
              {canManage && (
                <form onSubmit={handleAddNote} className="space-y-2 p-3 rounded-[8px] border border-[#D8DDD4] bg-[#FAF9F5]">
                  <textarea
                    rows={2}
                    value={newNoteContent}
                    onChange={(e) => setNewNoteContent(e.target.value)}
                    placeholder="Write a private recruitment note..."
                    className="w-full rounded border border-[#D8DDD4] bg-white p-2 text-xs focus:outline-none"
                  />
                  <div className="flex justify-end">
                    <button
                      type="submit"
                      disabled={submittingNote || !newNoteContent.trim()}
                      className="rounded bg-[#10251F] text-white px-3 py-1 text-xs font-bold hover:bg-[#18342C] disabled:opacity-50"
                    >
                      {submittingNote ? "Saving..." : "Add Note"}
                    </button>
                  </div>
                </form>
              )}

              {/* Notes list */}
              {candidate.notes_list && candidate.notes_list.length > 0 ? (
                <div className="space-y-2.5">
                  {candidate.notes_list.map((n) => (
                    <div
                      key={n.id}
                      className="rounded-[8px] border border-[#D8DDD4] bg-white p-3 space-y-1 shadow-2xs"
                    >
                      <div className="flex items-center justify-between">
                        <span className="font-bold text-[#18221E]">{n.author_name}</span>
                        <div className="flex items-center gap-2">
                          <span className="text-[10px] text-[#65706A]">
                            {new Date(n.created_at).toLocaleDateString("en-US", {
                              month: "short",
                              day: "numeric",
                            })}
                          </span>
                          {canManage && (
                            <button
                              type="button"
                              onClick={() => handleDeleteNote(n.id)}
                              className="text-[10px] text-red-600 hover:underline"
                            >
                              Delete
                            </button>
                          )}
                        </div>
                      </div>
                      <p className="text-xs text-[#18221E] whitespace-pre-wrap">{n.content}</p>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-center text-[#8C9489] py-6">No private notes yet.</p>
              )}
            </div>
          )}

          {activeTab === "history" && (
            <div className="space-y-3">
              <div className="rounded-[8px] border border-[#D8DDD4] bg-[#FAF9F5] p-3 space-y-1">
                <div className="flex items-center justify-between">
                  <span className="font-bold text-[#18221E]">
                    {candidate.latest_job_title || "Position Application"}
                  </span>
                  <span className="rounded-full bg-white border border-[#D8DDD4] px-2 py-0.5 text-[10px] font-bold">
                    {currentStage}
                  </span>
                </div>
                <p className="text-[11px] text-[#65706A]">
                  Applied on {new Date(candidate.created_at).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
                </p>
              </div>
            </div>
          )}
        </div>

        {/* Footer Actions */}
        {canManage && (
          <div className="border-t border-[#D8DDD4] p-4 bg-[#FAF9F5]/80 flex flex-wrap items-center justify-between gap-2">
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={() => onCreateOffer(candidate)}
                className="rounded-[8px] bg-[#10251F] text-white px-3 py-1.5 text-xs font-bold hover:bg-[#18342C] transition-colors shadow-2xs"
              >
                💼 Offer
              </button>

              <button
                type="button"
                onClick={() => onScheduleInterview(candidate)}
                className="rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs font-bold text-[#18221E] hover:bg-[#FAF9F5] transition-colors"
              >
                📅 Interview
              </button>

              {(currentStage === "Offer" || currentStage === "Hired") && !candidate.converted_user_id && (
                <button
                  type="button"
                  onClick={() => onConvertToEmployee(candidate)}
                  className="rounded-[8px] bg-[#246244] text-white px-3 py-1.5 text-xs font-bold hover:bg-[#1c4e36] transition-colors shadow-2xs"
                >
                  ✓ Convert to Employee
                </button>
              )}

              {candidate.converted_user_id && (
                <div className="flex items-center gap-1.5">
                  <span className="rounded-[8px] bg-[#FAF9F5] border border-[#D8DDD4] px-2.5 py-1 text-[11px] font-semibold text-[#65706A]">
                    Already converted to an employee
                  </span>
                  <Link
                    href={`/app/people/${candidate.converted_user_id}`}
                    className="rounded-[8px] bg-[#10251F] text-white px-2.5 py-1 text-[11px] font-bold hover:bg-[#18342C] transition-colors shadow-2xs"
                  >
                    Profile →
                  </Link>
                  <Link
                    href={`/app/people/onboarding/${candidate.converted_user_id}`}
                    className="rounded-[8px] bg-[#EAF4E2] text-[#246244] border border-[#246244]/20 px-2.5 py-1 text-[11px] font-bold hover:bg-[#d8edd0] transition-colors"
                  >
                    Onboarding →
                  </Link>
                </div>
              )}
            </div>

            <div className="flex items-center gap-2">
              {currentStage !== "Rejected" && (
                <button
                  type="button"
                  onClick={() => setRejectModalOpen(true)}
                  className="rounded-[8px] border border-red-200 bg-white px-3 py-1.5 text-xs font-semibold text-red-600 hover:bg-red-50"
                >
                  Reject
                </button>
              )}

              <button
                type="button"
                onClick={handleArchiveToggle}
                className="rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs font-semibold text-[#65706A] hover:text-[#18221E]"
              >
                {candidate.is_archived ? "Unarchive" : "Archive"}
              </button>
            </div>
          </div>
        )}
      </aside>

      {/* Reject Modal */}
      {rejectModalOpen && (
        <RejectCandidateModal
          isOpen={rejectModalOpen}
          onClose={() => setRejectModalOpen(false)}
          workspaceId={workspaceId}
          candidate={candidate}
          onSuccess={() => {
            if (onStageUpdated) onStageUpdated();
          }}
        />
      )}
    </>
  );
}

"use client";

import * as React from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  UserCheck,
  Search,
  ChevronRight,
  ChevronDown,
  Calendar,
  Briefcase,
  FileText,
  Clock,
  CheckCircle2,
  XCircle,
  MoreHorizontal,
  ArrowRight,
  X,
  ExternalLink,
  Plus,
  Building2,
  Check,
} from "lucide-react";
import { Candidate, CandidateStage, JobOpening } from "@/types/recruitment";
import { Department } from "@/types/department";
import { WorkspacePerson } from "@/types/people";
import { updateApplicationStageAction } from "@/lib/recruitment/actions";
import { RopimoUserAvatar } from "@/components/ropimo/ropimo-user-avatar";
import { RopimoSelect } from "@/components/ropimo/ropimo-select";
import { ScheduleInterviewModal } from "./schedule-interview-modal";
import { CreateOfferModal } from "./create-offer-modal";
import { ConvertToEmployeeModal } from "./convert-to-employee-modal";
import { CandidateProfileDrawer } from "./candidate-profile-drawer";
import { ApplyJobModal } from "./apply-job-modal";
import { cn } from "@/lib/utils";

export interface CandidatesViewProps {
  workspaceId: string;
  userRole: string;
  candidates: Candidate[];
  jobOpenings?: JobOpening[];
  departments: Department[];
  teamMembers: WorkspacePerson[];
  onNavigateToJobs?: () => void;
}

const STAGES: { stage: CandidateStage; label: string; dotColor: string; badgeColor: string }[] = [
  { stage: "Applied", label: "Applied", dotColor: "bg-sky-500", badgeColor: "bg-sky-50 text-sky-700 border-sky-200" },
  { stage: "Screening", label: "Screening", dotColor: "bg-indigo-500", badgeColor: "bg-indigo-50 text-indigo-700 border-indigo-200" },
  { stage: "Shortlisted", label: "Shortlisted", dotColor: "bg-purple-500", badgeColor: "bg-purple-50 text-purple-700 border-purple-200" },
  { stage: "Interview", label: "Interview", dotColor: "bg-amber-500", badgeColor: "bg-amber-50 text-amber-700 border-amber-200" },
  { stage: "Feedback", label: "Feedback", dotColor: "bg-teal-500", badgeColor: "bg-teal-50 text-teal-700 border-teal-200" },
  { stage: "Offer", label: "Offer", dotColor: "bg-emerald-500", badgeColor: "bg-emerald-50 text-emerald-700 border-emerald-200" },
  { stage: "Hired", label: "Hired", dotColor: "bg-[#246244]", badgeColor: "bg-[#EAF4E2] text-[#246244] border-[#D8DDD4]" },
  { stage: "Rejected", label: "Rejected", dotColor: "bg-stone-400", badgeColor: "bg-stone-100 text-stone-600 border-stone-200" },
];

export function CandidatesView({
  workspaceId,
  userRole,
  candidates = [],
  jobOpenings = [],
  departments = [],
  teamMembers = [],
  onNavigateToJobs,
}: CandidatesViewProps) {
  const router = useRouter();

  const [searchQuery, setSearchQuery] = React.useState("");
  const [selectedStage, setSelectedStage] = React.useState<string>("all");
  const [selectedJobId, setSelectedJobId] = React.useState<string>("all");
  const [sortBy, setSortBy] = React.useState<string>("recent");
  const [viewMode, setViewMode] = React.useState<"table" | "pipeline">("table");

  // Selected candidate for slide-over drawer
  const [drawerCandidate, setDrawerCandidate] = React.useState<Candidate | null>(null);

  // Modals state
  const [scheduleModalCandidate, setScheduleModalCandidate] = React.useState<Candidate | null>(null);
  const [offerModalCandidate, setOfferModalCandidate] = React.useState<Candidate | null>(null);
  const [convertModalCandidate, setConvertModalCandidate] = React.useState<Candidate | null>(null);
  const [addCandidateOpen, setAddCandidateOpen] = React.useState(false);
  const [actionMenuCandidateId, setActionMenuCandidateId] = React.useState<string | null>(null);

  const canManage = ["owner", "admin", "manager"].includes(userRole);

  // Close action menus on outside click
  React.useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (!(e.target as HTMLElement).closest("[data-candidate-menu]")) {
        setActionMenuCandidateId(null);
      }
    };
    window.addEventListener("click", handleClickOutside);
    return () => window.removeEventListener("click", handleClickOutside);
  }, []);

  const filteredCandidates = React.useMemo(() => {
    let result = candidates.filter((c) => {
      const q = searchQuery.toLowerCase().trim();
      const matchesSearch =
        !q ||
        c.full_name.toLowerCase().includes(q) ||
        c.email.toLowerCase().includes(q) ||
        (c.latest_job_title && c.latest_job_title.toLowerCase().includes(q)) ||
        c.skills.some((s) => s.toLowerCase().includes(q));

      const matchesStage = selectedStage === "all" || c.latest_stage === selectedStage;
      const matchesJob = selectedJobId === "all" || c.latest_job_id === selectedJobId;

      return matchesSearch && matchesStage && matchesJob;
    });

    if (sortBy === "name-asc") {
      result = [...result].sort((a, b) => a.full_name.localeCompare(b.full_name));
    } else if (sortBy === "exp-desc") {
      result = [...result].sort(
        (a, b) => (b.years_of_experience || 0) - (a.years_of_experience || 0)
      );
    } else if (sortBy === "recent") {
      result = [...result].sort(
        (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
      );
    }

    return result;
  }, [candidates, searchQuery, selectedStage, selectedJobId, sortBy]);

  const handleAdvanceStage = async (cand: Candidate, nextStage: CandidateStage) => {
    await updateApplicationStageAction({
      workspaceId,
      applicationId: cand.latest_application_id || cand.id,
      candidateId: cand.id,
      toStage: nextStage,
    });
    router.refresh();
  };

  const getStageConfig = (stage?: CandidateStage) => {
    const found = STAGES.find((s) => s.stage === stage);
    return (
      found || {
        stage: "Applied" as CandidateStage,
        label: "Applied",
        dotColor: "bg-sky-500",
        badgeColor: "bg-sky-50 text-sky-700 border-sky-200",
      }
    );
  };

  const formatDate = (dateStr?: string) => {
    if (!dateStr) return "Recently";
    try {
      return new Date(dateStr).toLocaleDateString("en-US", {
        month: "short",
        day: "numeric",
        year: "numeric",
      });
    } catch {
      return dateStr;
    }
  };

  return (
    <div className="space-y-4 select-none">
      {/* 1. COMPACT TOOLBAR */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        {/* Search */}
        <div className="relative flex-1 min-w-[240px] max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-[#65706A]" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search candidates by name, email, or skills..."
            className="w-full h-9 rounded-[10px] border border-[#D8DDD4] bg-white pl-9 pr-8 text-xs text-[#18221E] shadow-2xs placeholder:text-[#8A958F] focus:border-[#10251F] focus:outline-none transition-colors"
          />
          {searchQuery && (
            <button
              type="button"
              onClick={() => setSearchQuery("")}
              className="absolute right-2.5 top-1/2 -translate-y-1/2 rounded p-0.5 text-[#65706A] hover:text-[#18221E]"
            >
              <X className="h-3 w-3" />
            </button>
          )}
        </div>

        {/* Filters & View Switcher */}
        <div className="flex items-center gap-2 flex-wrap">
          {/* Job Filter */}
          {jobOpenings.length > 0 && (
            <RopimoSelect
              value={selectedJobId}
              onChange={(val) => setSelectedJobId(val)}
              options={[
                { value: "all", label: "All Job Openings" },
                ...jobOpenings.map((j) => ({ value: j.id, label: j.title })),
              ]}
            />
          )}

          {/* Stage Filter */}
          <RopimoSelect
            value={selectedStage}
            onChange={(val) => setSelectedStage(val)}
            options={[
              { value: "all", label: "All Stages" },
              ...STAGES.map((s) => ({ value: s.stage, label: s.label })),
            ]}
          />

          {/* Sort Selector */}
          <RopimoSelect
            value={sortBy}
            onChange={(val) => setSortBy(val)}
            prefix="Sort"
            options={[
              { value: "recent", label: "Recently Applied" },
              { value: "name-asc", label: "Name (A-Z)" },
              { value: "exp-desc", label: "Experience (Highest)" },
            ]}
          />

          {/* View Mode Toggle */}
          <div className="flex items-center rounded-[10px] border border-[#D8DDD4] bg-white p-0.5 shadow-2xs h-9">
            <button
              type="button"
              onClick={() => setViewMode("table")}
              className={cn(
                "rounded-[8px] px-3 py-1 text-xs font-semibold transition-colors cursor-pointer",
                viewMode === "table"
                  ? "bg-[#10251F] text-[#F4F3EE] shadow-2xs font-bold"
                  : "text-[#65706A] hover:text-[#18221E]"
              )}
            >
              List View
            </button>
            <button
              type="button"
              onClick={() => setViewMode("pipeline")}
              className={cn(
                "rounded-[8px] px-3 py-1 text-xs font-semibold transition-colors cursor-pointer",
                viewMode === "pipeline"
                  ? "bg-[#10251F] text-[#F4F3EE] shadow-2xs font-bold"
                  : "text-[#65706A] hover:text-[#18221E]"
              )}
            >
              Pipeline
            </button>
          </div>

          {/* Add Candidate Button */}
          {canManage && jobOpenings.length > 0 && (
            <button
              type="button"
              onClick={() => setAddCandidateOpen(true)}
              className="inline-flex h-9 items-center gap-1.5 rounded-[10px] bg-[#10251F] text-[#F4F3EE] px-3 text-xs font-semibold hover:bg-[#18342C] transition-colors shadow-xs cursor-pointer"
            >
              <Plus className="h-3.5 w-3.5 text-[#C7F34A]" />
              <span>Add Candidate</span>
            </button>
          )}
        </div>
      </div>

      {/* 2. VIEW MODE 1: LIST / TABLE (DEFAULT) */}
      {viewMode === "table" ? (
        <div className="overflow-hidden rounded-[14px] border border-[#D8DDD4] bg-white shadow-2xs">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs border-collapse">
              <thead>
                <tr className="border-b border-[#E7EADF] bg-[#FAF9F5] text-[10px] font-bold uppercase tracking-wider text-[#8A958F]">
                  <th className="py-3 px-4 font-bold">CANDIDATE</th>
                  <th className="py-3 px-4 font-bold">APPLIED POSITION</th>
                  <th className="py-3 px-4 font-bold">STAGE</th>
                  <th className="py-3 px-4 font-bold">EXPERIENCE</th>
                  <th className="py-3 px-4 font-bold">APPLIED DATE</th>
                  <th className="py-3 px-4 font-bold text-right">ACTIONS</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[#E7EADF]">
                {filteredCandidates.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="py-12 text-center text-xs text-[#65706A]">
                      No candidates match your current filters.
                    </td>
                  </tr>
                ) : (
                  filteredCandidates.map((cand) => {
                    const stageConfig = getStageConfig(cand.latest_stage);
                    const isHired = cand.latest_stage === "Hired";

                    return (
                      <tr
                        key={cand.id}
                        onClick={() => setDrawerCandidate(cand)}
                        className="group hover:bg-[#FAF9F5] transition-colors cursor-pointer"
                      >
                        {/* Candidate Name & Email */}
                        <td className="py-3 px-4">
                          <div className="flex items-center gap-3">
                            <RopimoUserAvatar name={cand.full_name} size="sm" />
                            <div className="min-w-0">
                              <p className="font-bold text-[#18221E] group-hover:text-[#246244] transition-colors truncate">
                                {cand.full_name}
                              </p>
                              <p className="text-[11px] text-[#65706A] truncate">
                                {cand.email}
                              </p>
                            </div>
                          </div>
                        </td>

                        {/* Applied Position */}
                        <td className="py-3 px-4">
                          <p className="font-semibold text-[#18221E] truncate max-w-[180px]">
                            {cand.latest_job_title || "General Application"}
                          </p>
                          {cand.skills && cand.skills.length > 0 && (
                            <div className="flex items-center gap-1 mt-0.5">
                              {cand.skills.slice(0, 2).map((s) => (
                                <span
                                  key={s}
                                  className="rounded bg-[#FAF9F5] border border-[#D8DDD4] px-1.5 py-0.2 text-[9px] font-medium text-[#65706A]"
                                >
                                  {s}
                                </span>
                              ))}
                            </div>
                          )}
                        </td>

                        {/* Stage */}
                        <td className="py-3 px-4">
                          <span
                            className={cn(
                              "inline-flex items-center gap-1.5 rounded-full border px-2.5 py-0.5 text-[11px] font-semibold",
                              stageConfig.badgeColor
                            )}
                          >
                            <span className={cn("h-1.5 w-1.5 rounded-full", stageConfig.dotColor)} />
                            {stageConfig.label}
                          </span>
                        </td>

                        {/* Experience */}
                        <td className="py-3 px-4 text-[#65706A] font-medium text-[11px]">
                          {cand.years_of_experience ? `${cand.years_of_experience} yrs exp` : "Not set"}
                        </td>

                        {/* Applied Date */}
                        <td className="py-3 px-4 text-[#65706A] font-medium text-[11px] whitespace-nowrap">
                          {formatDate(cand.created_at)}
                        </td>

                        {/* Actions */}
                        <td className="py-3 px-4 text-right" onClick={(e) => e.stopPropagation()}>
                          <div className="flex items-center justify-end gap-2" data-candidate-menu>
                            <button
                              type="button"
                              onClick={() => setDrawerCandidate(cand)}
                              className="inline-flex items-center gap-1 text-[11px] font-bold text-[#246244] hover:underline"
                            >
                              <span>Profile</span>
                              <ChevronRight className="h-3 w-3" />
                            </button>

                            {canManage && !isHired && (
                              <button
                                type="button"
                                onClick={() => {
                                  const currentIdx = STAGES.findIndex((s) => s.stage === cand.latest_stage);
                                  if (currentIdx >= 0 && currentIdx < STAGES.length - 2) {
                                    handleAdvanceStage(cand, STAGES[currentIdx + 1].stage);
                                  }
                                }}
                                className="inline-flex items-center gap-1 rounded-[6px] border border-[#D8DDD4] bg-white px-2 py-1 text-[10px] font-bold text-[#18221E] shadow-2xs hover:bg-[#FAF9F5] transition-colors cursor-pointer"
                              >
                                <span>Advance</span>
                                <ArrowRight className="h-2.5 w-2.5 text-[#246244]" />
                              </button>
                            )}

                            {isHired && (
                              <span className="rounded-full bg-[#EAF4E2] text-[#246244] border border-[#D8DDD4] px-2 py-0.5 text-[10px] font-bold">
                                Hired
                              </span>
                            )}
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
        /* 3. VIEW MODE 2: REFINED PIPELINE BOARD */
        <div className="flex gap-4 overflow-x-auto pb-4 pt-1">
          {STAGES.filter((s) => !["Rejected"].includes(s.stage)).map(({ stage: stageName, label, dotColor }) => {
            const stageCandidates = filteredCandidates.filter(
              (c) => (c.latest_stage || "Applied") === stageName
            );

            return (
              <div
                key={stageName}
                className="w-72 min-w-[288px] shrink-0 rounded-[14px] border border-[#D8DDD4] bg-[#FAF9F5] flex flex-col shadow-2xs overflow-hidden"
              >
                {/* Column Header */}
                <div className="flex items-center justify-between border-b border-[#D8DDD4] bg-white px-3.5 py-2.5">
                  <div className="flex items-center gap-2">
                    <span className={cn("h-2 w-2 rounded-full", dotColor)} />
                    <span className="font-bold text-xs text-[#18221E]">{label}</span>
                  </div>
                  <span className="rounded-full bg-[#FAF9F5] border border-[#D8DDD4] px-2 py-0.5 text-[10px] font-bold text-[#65706A]">
                    {stageCandidates.length}
                  </span>
                </div>

                {/* Column Body */}
                <div className="p-2.5 space-y-2.5 flex-1 min-h-[300px]">
                  {stageCandidates.length === 0 ? (
                    <div className="py-12 text-center text-[11px] text-[#8A958F]">
                      No candidates
                    </div>
                  ) : (
                    stageCandidates.map((cand) => (
                      <div
                        key={cand.id}
                        onClick={() => setDrawerCandidate(cand)}
                        className="rounded-[10px] border border-[#D8DDD4] bg-white p-3 shadow-2xs hover:border-[#10251F] hover:shadow-xs transition-all cursor-pointer group space-y-2"
                      >
                        <div className="flex items-start justify-between gap-2">
                          <div className="min-w-0">
                            <p className="font-bold text-xs text-[#18221E] group-hover:text-[#246244] transition-colors truncate">
                              {cand.full_name}
                            </p>
                            <p className="text-[11px] text-[#65706A] truncate">
                              {cand.latest_job_title || "General Application"}
                            </p>
                          </div>

                          <RopimoUserAvatar name={cand.full_name} size="sm" />
                        </div>

                        <div className="flex items-center justify-between pt-1 border-t border-[#E7EADF] text-[10px] text-[#8A958F]">
                          <span>{cand.years_of_experience ? `${cand.years_of_experience} yrs exp` : "Entry"}</span>
                          <span className="font-semibold text-[#246244] group-hover:underline">
                            View details →
                          </span>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* 4. MODALS & DRAWERS */}
      {drawerCandidate && (
        <CandidateProfileDrawer
          isOpen={true}
          candidate={drawerCandidate}
          workspaceId={workspaceId}
          userRole={userRole}
          departments={departments}
          teamMembers={teamMembers}
          onClose={() => setDrawerCandidate(null)}
          onScheduleInterview={() => {
            setScheduleModalCandidate(drawerCandidate);
          }}
          onCreateOffer={() => {
            setOfferModalCandidate(drawerCandidate);
          }}
          onConvertToEmployee={() => {
            setConvertModalCandidate(drawerCandidate);
          }}
        />
      )}

      {scheduleModalCandidate && (
        <ScheduleInterviewModal
          isOpen={true}
          onClose={() => setScheduleModalCandidate(null)}
          workspaceId={workspaceId}
          candidate={scheduleModalCandidate}
          application={{
            id: scheduleModalCandidate.latest_application_id || scheduleModalCandidate.id,
            candidate_id: scheduleModalCandidate.id,
            job_opening_id: scheduleModalCandidate.latest_job_id || "",
            stage: scheduleModalCandidate.latest_stage || "Applied",
            workspace_id: workspaceId,
            source: "Direct",
            created_at: scheduleModalCandidate.created_at,
            updated_at: scheduleModalCandidate.created_at,
          }}
          teamMembers={teamMembers}
        />
      )}

      {offerModalCandidate && (
        <CreateOfferModal
          isOpen={true}
          onClose={() => setOfferModalCandidate(null)}
          workspaceId={workspaceId}
          candidate={offerModalCandidate}
          application={{
            id: offerModalCandidate.latest_application_id || offerModalCandidate.id,
            candidate_id: offerModalCandidate.id,
            job_opening_id: offerModalCandidate.latest_job_id || "",
            stage: offerModalCandidate.latest_stage || "Offer",
            workspace_id: workspaceId,
            source: "Direct",
            created_at: offerModalCandidate.created_at,
            updated_at: offerModalCandidate.created_at,
          }}
          departments={departments}
        />
      )}

      {convertModalCandidate && (
        <ConvertToEmployeeModal
          isOpen={true}
          onClose={() => setConvertModalCandidate(null)}
          workspaceId={workspaceId}
          candidate={convertModalCandidate}
          departments={departments}
        />
      )}

      {addCandidateOpen && jobOpenings.length > 0 && (
        <ApplyJobModal
          isOpen={true}
          onClose={() => setAddCandidateOpen(false)}
          workspaceId={workspaceId}
          jobOpening={jobOpenings[0]}
        />
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { motion, AnimatePresence } from "motion/react";
import { useRouter } from "next/navigation";
import { Candidate, EmploymentType, JobOffer } from "@/types/recruitment";
import { Department } from "@/types/department";
import { WorkspacePerson } from "@/types/people";
import { hireCandidateAction } from "@/lib/recruitment/actions";
import { PrimaryButton } from "@/components/ui/primary-button";

export interface CompleteHiringModalProps {
  isOpen: boolean;
  onClose: () => void;
  workspaceId: string;
  candidate: Candidate;
  departments: Department[];
  teamMembers?: WorkspacePerson[];
  offer?: JobOffer;
  onSuccess?: () => void;
}

export function CompleteHiringModal({
  isOpen,
  onClose,
  workspaceId,
  candidate,
  departments,
  teamMembers = [],
  offer,
  onSuccess,
}: CompleteHiringModalProps) {
  const router = useRouter();

  // Required Fields
  const [fullName, setFullName] = React.useState(candidate.full_name || "");
  const [workEmail, setWorkEmail] = React.useState(candidate.email || "");
  const [jobTitle, setJobTitle] = React.useState(
    offer?.job_title || candidate.latest_job_title || "Team Member"
  );
  const [departmentId, setDepartmentId] = React.useState(
    offer?.department_id || departments[0]?.id || ""
  );
  const [employmentType, setEmploymentType] = React.useState<EmploymentType>(
    offer?.employment_type || "Full-time"
  );
  const [startDate, setStartDate] = React.useState(
    offer?.start_date || new Date().toISOString().split("T")[0]
  );

  // Optional Fields
  const [personalEmail, setPersonalEmail] = React.useState("");
  const [phone, setPhone] = React.useState(candidate.phone || "");
  const [salary, setSalary] = React.useState(offer?.salary || "");
  const [location, setLocation] = React.useState(candidate.location || "");
  const [managerId, setManagerId] = React.useState("");
  const [employeeId, setEmployeeId] = React.useState(
    candidate.employee_id || ""
  );
  const [role, setRole] = React.useState<"member" | "manager" | "admin">("member");

  const [loading, setLoading] = React.useState(false);
  const [errorMsg, setErrorMsg] = React.useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setErrorMsg(null);

    try {
      const res = await hireCandidateAction({
        workspaceId,
        candidateId: candidate.id,
        applicationId: candidate.latest_application_id,
        offerId: offer?.id,
        fullName: fullName.trim(),
        workEmail: workEmail.trim(),
        jobTitle: jobTitle.trim(),
        departmentId: departmentId || undefined,
        employmentType,
        startDate,
        salary: salary.trim() || undefined,
        location: location.trim() || undefined,
        phone: phone.trim() || undefined,
        managerId: managerId || undefined,
        employeeId: employeeId.trim() || undefined,
        role,
      });

      if (!res.success) {
        setErrorMsg(res.error || "Failed to complete hiring.");
        setLoading(false);
        return;
      }

      setLoading(false);
      onClose();
      router.refresh();
      if (res.data?.userId) {
        router.push(`/app/people/onboarding/${res.data.userId}`);
      }
      if (onSuccess) onSuccess();
    } catch {
      setErrorMsg("An unexpected error occurred.");
      setLoading(false);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/40 backdrop-blur-xs"
          />

          <motion.div
            initial={{ opacity: 0, scale: 0.96, y: 10 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.96, y: 10 }}
            className="relative w-full max-w-lg rounded-[16px] border border-[#D8DDD4] bg-white p-6 shadow-xl text-[#18221E] space-y-4 max-h-[90vh] overflow-y-auto"
          >
            <div className="flex items-center justify-between border-b border-[#D8DDD4]/60 pb-3">
              <div>
                <h2 className="text-base font-bold text-[#18221E]">Hire Candidate</h2>
                <p className="text-xs text-[#65706A]">
                  Confirm details to create official employee record and initiate onboarding.
                </p>
              </div>
              <button
                type="button"
                onClick={onClose}
                className="p-1 rounded text-[#65706A] hover:text-[#18221E]"
              >
                ✕
              </button>
            </div>

            {errorMsg && (
              <div className="rounded-[8px] bg-red-50 p-2.5 text-xs text-red-600 border border-red-200">
                {errorMsg}
              </div>
            )}

            {/* Candidate & Position Context Badge */}
            <div className="rounded-[10px] border border-[#D8DDD4] bg-[#FAF9F5] p-3.5 space-y-1.5 text-xs">
              <div className="flex items-center justify-between">
                <span className="font-bold text-xs text-[#18221E]">{candidate.full_name}</span>
                <span className="rounded-full bg-[#EAF4E2] text-[#246244] border border-[#246244]/20 px-2 py-0.5 text-[10px] font-bold">
                  Current Stage: Hired
                </span>
              </div>
              <p className="text-[11px] text-[#65706A]">
                Applied Position: <span className="font-semibold text-[#18221E]">{candidate.latest_job_title || "Team Member"}</span>
              </p>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4 text-xs">
              <div className="border-b border-[#D8DDD4]/40 pb-3">
                <h4 className="text-[11px] font-bold uppercase tracking-wider text-[#65706A] mb-3">
                  Required Employee Details
                </h4>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="block font-semibold text-[#18221E] mb-1">Employee Name *</label>
                    <input
                      type="text"
                      required
                      value={fullName}
                      onChange={(e) => setFullName(e.target.value)}
                      className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs focus:border-[#10251F] focus:outline-none"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold text-[#18221E] mb-1">Work Email *</label>
                    <input
                      type="email"
                      required
                      value={workEmail}
                      onChange={(e) => setWorkEmail(e.target.value)}
                      className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs focus:border-[#10251F] focus:outline-none"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold text-[#18221E] mb-1">Job Title *</label>
                    <input
                      type="text"
                      required
                      value={jobTitle}
                      onChange={(e) => setJobTitle(e.target.value)}
                      className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs focus:border-[#10251F] focus:outline-none"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold text-[#18221E] mb-1">Department *</label>
                    <select
                      value={departmentId}
                      required
                      onChange={(e) => setDepartmentId(e.target.value)}
                      className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs focus:border-[#10251F] focus:outline-none"
                    >
                      {departments.map((d) => (
                        <option key={d.id} value={d.id}>
                          {d.name}
                        </option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <label className="block font-semibold text-[#18221E] mb-1">Employment Type *</label>
                    <select
                      value={employmentType}
                      onChange={(e) => setEmploymentType(e.target.value as EmploymentType)}
                      className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs focus:border-[#10251F] focus:outline-none"
                    >
                      <option value="Full-time">Full-time</option>
                      <option value="Part-time">Part-time</option>
                      <option value="Contractor">Contractor</option>
                      <option value="Intern">Intern</option>
                    </select>
                  </div>

                  <div>
                    <label className="block font-semibold text-[#18221E] mb-1">Official Start Date *</label>
                    <input
                      type="date"
                      required
                      value={startDate}
                      onChange={(e) => setStartDate(e.target.value)}
                      className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs focus:border-[#10251F] focus:outline-none"
                    />
                  </div>
                </div>
              </div>

              <div>
                <h4 className="text-[11px] font-bold uppercase tracking-wider text-[#65706A] mb-3">
                  Additional Details (Optional)
                </h4>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="block font-semibold text-[#18221E] mb-1">Employee ID</label>
                    <input
                      type="text"
                      placeholder="Auto-generated (e.g. EMP-001)"
                      value={employeeId}
                      onChange={(e) => setEmployeeId(e.target.value)}
                      className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs focus:border-[#10251F] focus:outline-none"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold text-[#18221E] mb-1">Reporting Lead / Manager</label>
                    <select
                      value={managerId}
                      onChange={(e) => setManagerId(e.target.value)}
                      className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs focus:border-[#10251F] focus:outline-none"
                    >
                      <option value="">Unassigned</option>
                      {teamMembers.map((m) => (
                        <option key={m.user_id} value={m.user_id}>
                          {m.full_name}
                        </option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <label className="block font-semibold text-[#18221E] mb-1">Phone</label>
                    <input
                      type="tel"
                      value={phone}
                      onChange={(e) => setPhone(e.target.value)}
                      placeholder="+1 (555) 000-0000"
                      className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs focus:border-[#10251F] focus:outline-none"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold text-[#18221E] mb-1">Salary / Compensation</label>
                    <input
                      type="text"
                      value={salary}
                      onChange={(e) => setSalary(e.target.value)}
                      placeholder="e.g. $95,000 / year"
                      className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs focus:border-[#10251F] focus:outline-none"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold text-[#18221E] mb-1">Location</label>
                    <input
                      type="text"
                      value={location}
                      onChange={(e) => setLocation(e.target.value)}
                      placeholder="e.g. San Francisco, CA / Remote"
                      className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs focus:border-[#10251F] focus:outline-none"
                    />
                  </div>

                  <div>
                    <label className="block font-semibold text-[#18221E] mb-1">Workspace Role</label>
                    <select
                      value={role}
                      onChange={(e) => setRole(e.target.value as any)}
                      className="w-full rounded-[8px] border border-[#D8DDD4] bg-white px-3 py-1.5 text-xs focus:border-[#10251F] focus:outline-none"
                    >
                      <option value="member">Member</option>
                      <option value="manager">Manager</option>
                      <option value="admin">Admin</option>
                    </select>
                  </div>
                </div>
              </div>

              <div className="flex items-center justify-end gap-2.5 pt-3 border-t border-[#D8DDD4]/60">
                <button
                  type="button"
                  onClick={onClose}
                  className="rounded-[8px] border border-[#D8DDD4] px-4 py-2 text-xs font-semibold text-[#65706A] hover:bg-[#FAF9F5] transition-colors"
                >
                  Cancel
                </button>
                <PrimaryButton size="sm" type="submit" disabled={loading}>
                  {loading ? "Hiring Candidate..." : "Confirm & Hire Employee"}
                </PrimaryButton>
              </div>
            </form>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
}

