/**
 * Submit Leave Request Action
 */
export async function submitLeaveRequestAction(params: {
  workspaceId: string;
  leaveType: LeaveType;
  startDate: string;
  endDate: string;
  durationDays?: number;
  reason: string;
  attachmentUrl?: string;
}): Promise<ActionResult<LeaveRequest>> {
  try {
    const { user, adminClient } = await verifyUserAndRole(params.workspaceId);
    if (!user) {
      return { success: false, error: "Unauthorized." };
    }

    if (!params.startDate || !params.endDate) {
      return { success: false, error: "Start and end dates are required." };
    }

    if (params.startDate > params.endDate) {
      return { success: false, error: "Start date cannot be after end date." };
    }

    if (!params.reason?.trim()) {
      return { success: false, error: "A reason for leave is required." };
    }

    const calculatedDuration =
      params.durationDays ||
      Math.max(
        1,
        Math.round(
          (new Date(params.endDate).getTime() - new Date(params.startDate).getTime()) / 86400000
        ) + 1
      );

    // Check existing pending/approved requests overlapping
    const { data: overlapping } = await adminClient
      .from("leave_requests")
      .select("id")
      .eq("workspace_id", params.workspaceId)
      .eq("user_id", user.id)
      .in("status", ["Pending", "Approved"])
      .lte("start_date", params.endDate)
      .gte("end_date", params.startDate);

    if (overlapping && overlapping.length > 0) {
      return {
        success: false,
        error: "You already have a pending or approved leave request for overlapping dates.",
      };
    }

    // Insert leave request
    const { data: newRequest, error: insertErr } = await adminClient
      .from("leave_requests")
      .insert({
        workspace_id: params.workspaceId,
        user_id: user.id,
        leave_type: params.leaveType,
        start_date: params.startDate,
        end_date: params.endDate,
        duration_days: calculatedDuration,
        reason: params.reason.trim(),
        attachment_url: params.attachmentUrl || null,
        status: "Pending",
      })
      .select()
      .single();

    if (insertErr || !newRequest) {
      return { success: false, error: insertErr?.message || "Failed to submit leave request." };
    }

    // Update pending balance
    const currentYear = new Date().getFullYear();
    const { data: balanceData } = await adminClient
      .from("leave_balances")
      .select("*")
      .eq("workspace_id", params.workspaceId)
      .eq("user_id", user.id)
      .eq("leave_type", params.leaveType)
      .eq("year", currentYear)
      .maybeSingle();

    if (balanceData) {
      await adminClient
        .from("leave_balances")
        .update({
          pending_days: (balanceData.pending_days || 0) + calculatedDuration,
        })
        .eq("id", balanceData.id);
    }

    try {
      await dispatchLeaveRequestedEvent({
        workspaceId: params.workspaceId,
        requestId: newRequest.id,
        employeeUserId: user.id,
        leaveType: params.leaveType,
        startDate: params.startDate,
        endDate: params.endDate,
        durationDays: calculatedDuration,
        reason: params.reason.trim(),
      });
    } catch {
      // Notification dispatch is non-blocking
    }

    try {
      revalidatePath("/app/attendance");
      revalidatePath("/app/leave");
    } catch {
      // Background context
    }

    return { success: true, data: newRequest as unknown as LeaveRequest };
  } catch (error: unknown) {
    const errMessage = error instanceof Error ? error.message : undefined;
    console.error("Submit leave request error:", error);
    return { success: false, error: errMessage || "Failed to submit leave request." };
  }
}

/**
 * Review / Approve / Reject Leave Request Action
 */
export async function reviewLeaveRequestAction(params: {
  workspaceId: string;
  requestId: string;
  action?: "approve" | "reject";
  decision?: "Approved" | "Rejected";
  rejectionReason?: string;
}): Promise<ActionResult<LeaveRequest>> {
  try {
    const { user, adminClient } = await verifyUserAndRole(params.workspaceId, [
      "owner",
      "admin",
      "manager",
    ]);
    if (!user) {
      return { success: false, error: "Insufficient permissions to review leave requests." };
    }

    const isApproved =
      params.action === "approve" ||
      params.decision === "Approved" ||
      (!params.action && params.decision !== "Rejected");
    const finalDecision: "Approved" | "Rejected" = isApproved ? "Approved" : "Rejected";

    const { data: request, error: fetchErr } = await adminClient
      .from("leave_requests")
      .select("*")
      .eq("id", params.requestId)
      .eq("workspace_id", params.workspaceId)
      .single();

    if (fetchErr || !request) {
      return { success: false, error: "Leave request not found." };
    }

    if (request.status !== "Pending") {
      return { success: false, error: `This leave request is already ${request.status}.` };
    }

    const now = new Date();
    const { data: updatedRequest, error: updateErr } = await adminClient
      .from("leave_requests")
      .update({
        status: finalDecision,
        rejection_reason:
          finalDecision === "Rejected"
            ? params.rejectionReason?.trim() || "Rejected by manager"
            : null,
        reviewed_by: user.id,
        reviewed_at: now.toISOString(),
        updated_at: now.toISOString(),
      })
      .eq("id", params.requestId)
      .select()
      .single();

    if (updateErr || !updatedRequest) {
      return { success: false, error: updateErr?.message || "Failed to update leave request." };
    }

    // Update balances
    const currentYear = new Date().getFullYear();
    const { data: balanceData } = await adminClient
      .from("leave_balances")
      .select("*")
      .eq("workspace_id", params.workspaceId)
      .eq("user_id", request.user_id)
      .eq("leave_type", request.leave_type)
      .eq("year", currentYear)
      .maybeSingle();

    if (balanceData) {
      const newPending = Math.max(0, (balanceData.pending_days || 0) - request.duration_days);
      const newUsed =
        finalDecision === "Approved"
          ? (balanceData.used_days || 0) + request.duration_days
          : balanceData.used_days || 0;

      await adminClient
        .from("leave_balances")
        .update({
          pending_days: newPending,
          used_days: newUsed,
        })
        .eq("id", balanceData.id);
    }

    try {
      await dispatchLeaveReviewedEvent({
        workspaceId: params.workspaceId,
        requestId: request.id,
        employeeUserId: request.user_id,
        reviewerUserId: user.id,
        action: isApproved ? "approve" : "reject",
        leaveType: request.leave_type,
        startDate: request.start_date,
        endDate: request.end_date,
        durationDays: request.duration_days,
        rejectionReason: params.rejectionReason,
      });
    } catch {
      // Non-blocking
    }

    try {
      revalidatePath("/app/attendance");
      revalidatePath("/app/leave");
    } catch {
      // Background context
    }

    return { success: true, data: updatedRequest as unknown as LeaveRequest };
  } catch (error: unknown) {
    const errMessage = error instanceof Error ? error.message : undefined;
    console.error("Review leave request error:", error);
    return { success: false, error: errMessage || "Failed to review leave request." };
  }
}

/**
 * Cancel Own Leave Request Action
 */
export async function cancelLeaveRequestAction(params: {
  workspaceId: string;
  requestId: string;
}): Promise<ActionResult<LeaveRequest>> {
  try {
    const { user, adminClient } = await verifyUserAndRole(params.workspaceId);
    if (!user) {
      return { success: false, error: "Unauthorized." };
    }

    const { data: request, error: fetchErr } = await adminClient
      .from("leave_requests")
      .select("*")
      .eq("id", params.requestId)
      .eq("workspace_id", params.workspaceId)
      .single();

    if (fetchErr || !request) {
      return { success: false, error: "Leave request not found." };
    }

    if (request.user_id !== user.id) {
      return { success: false, error: "You can only cancel your own leave requests." };
    }

    if (request.status === "Cancelled" || request.status === "Rejected") {
      return { success: false, error: "This request cannot be cancelled." };
    }

    const { data: updatedRequest, error: updateErr } = await adminClient
      .from("leave_requests")
      .update({
        status: "Cancelled",
        updated_at: new Date().toISOString(),
      })
      .eq("id", params.requestId)
      .select()
      .single();

    if (updateErr || !updatedRequest) {
      return { success: false, error: updateErr?.message || "Failed to cancel request." };
    }

    // Restore balance
    const currentYear = new Date().getFullYear();
    const { data: balanceData } = await adminClient
      .from("leave_balances")
      .select("*")
      .eq("workspace_id", params.workspaceId)
      .eq("user_id", user.id)
      .eq("leave_type", request.leave_type)
      .eq("year", currentYear)
      .maybeSingle();

    if (balanceData) {
      if (request.status === "Approved") {
        await adminClient
          .from("leave_balances")
          .update({
            used_days: Math.max(0, (balanceData.used_days || 0) - request.duration_days),
          })
          .eq("id", balanceData.id);
      } else if (request.status === "Pending") {
        await adminClient
          .from("leave_balances")
          .update({
            pending_days: Math.max(0, (balanceData.pending_days || 0) - request.duration_days),
          })
          .eq("id", balanceData.id);
      }
    }

    revalidatePath("/app/attendance");
    revalidatePath("/app/leave");

    return { success: true, data: updatedRequest as unknown as LeaveRequest };
  } catch (error: unknown) {
    const errMessage = error instanceof Error ? error.message : undefined;
    return { success: false, error: error.message };
  }
}

/**
 * Update Attendance Policy / Work Schedule Settings
 */
export async function updateAttendanceSettingsAction(params: {
  workspaceId: string;
  workStartTime?: string;
  workEndTime?: string;
  gracePeriodMinutes?: number;
  halfDayThresholdMinutes?: number;
  workDays?: number[];
}): Promise<ActionResult<AttendanceSettings>> {
  try {
    const { user, adminClient } = await verifyUserAndRole(params.workspaceId, [
      "owner",
      "admin",
    ]);
    if (!user) {
      return { success: false, error: "Only workspace owners and admins can edit policy settings." };
    }

    const { data: savedSettings, error } = await adminClient
      .from("attendance_settings")
      .upsert(
        {
          workspace_id: params.workspaceId,
          work_start_time: params.workStartTime || "09:00",
          work_end_time: params.workEndTime || "17:00",
          grace_period_minutes: params.gracePeriodMinutes ?? 15,
          half_day_threshold_minutes: params.halfDayThresholdMinutes ?? 240,
          work_days: params.workDays ?? [1, 2, 3, 4, 5],
          updated_at: new Date().toISOString(),
        },
        { onConflict: "workspace_id" }
      )
      .select()
      .single();

    if (error) {
      return { success: false, error: error.message };
    }

    revalidatePath("/app/attendance");
    return { success: true, data: savedSettings as unknown as AttendanceSettings };
  } catch (error: unknown) {
    const errMessage = error instanceof Error ? error.message : undefined;
    return { success: false, error: error.message };
  }
}

"use server";

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { revalidatePath } from "next/cache";

export interface SaveOnboardingInput {
  companyName: string;
  teamSize: string;
  industry: string;
  role: string;
  emails?: string[];
}

export async function saveOnboardingAction(input: SaveOnboardingInput) {
  // 1. Verify user session securely on server
  const serverClient = await createClient();
  const {
    data: { user },
    error: authError,
  } = await serverClient.auth.getUser();

  if (authError || !user) {
    return { success: false, error: "Authentication session expired. Please log in again." };
  }

  const name = input.companyName.trim();
  if (!name || name.length < 2) {
    return { success: false, error: "Workspace name must be at least 2 characters." };
  }

  const adminClient = createAdminClient();

  // Generate safe unique slug
  const baseSlug =
    name
      .toLowerCase()
      .trim()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "") || "workspace";
  const slug = `${baseSlug}-${Math.random().toString(36).substring(2, 6)}`;

  // Map role
  let dbRole: "owner" | "admin" | "hr" | "manager" | "member" = "owner";
  if (input.role === "HR") dbRole = "hr";
  else if (input.role === "Manager") dbRole = "manager";
  else if (input.role === "Team member") dbRole = "member";

  // Try insert with team_size & industry
  let workspaceId: string | null = null;
  const fullPayload: Record<string, any> = {
    name,
    slug,
    team_size: input.teamSize,
    industry: input.industry,
    owner_id: user.id,
    created_by: user.id,
  };

  const { data: wsData, error: wsError } = await adminClient
    .from("workspaces")
    .insert(fullPayload)
    .select("id")
    .single();

  if (!wsError && wsData) {
    workspaceId = wsData.id;
  } else if (
    wsError &&
    (wsError.message.includes("industry") ||
      wsError.message.includes("team_size") ||
      wsError.message.includes("owner_id"))
  ) {
    // Fallback if older table schema without industry/team_size columns
    const fallbackPayload: Record<string, any> = {
      name,
      slug,
      created_by: user.id,
    };
    const { data: fbData, error: fbError } = await adminClient
      .from("workspaces")
      .insert(fallbackPayload)
      .select("id")
      .single();

    if (fbError || !fbData) {
      return { success: false, error: fbError?.message || "Failed to create workspace." };
    }
    workspaceId = fbData.id;
  } else {
    return { success: false, error: wsError?.message || "Failed to create workspace." };
  }

  // 2. Insert into workspace_members
  const { error: memberError } = await adminClient.from("workspace_members").insert({
    workspace_id: workspaceId,
    user_id: user.id,
    role: dbRole,
  });

  if (memberError) {
    // If check constraint on role rejected 'hr' or 'manager', fallback to 'owner'
    await adminClient.from("workspace_members").insert({
      workspace_id: workspaceId,
      user_id: user.id,
      role: "owner",
    });
  }

  // 3. Insert invitations if provided
  const validEmails = (input.emails || [])
    .map((e) => e.trim().toLowerCase())
    .filter((e) => e.length > 0 && e.includes("@"));

  if (validEmails.length > 0) {
    try {
      const invitationRows = validEmails.map((email) => ({
        workspace_id: workspaceId,
        email,
        role: "member",
        invited_by: user.id,
        status: "pending",
      }));
      await adminClient.from("invitations").insert(invitationRows);
    } catch {
      // Non-blocking if invitations table isn't created yet
    }
  }

  revalidatePath("/dashboard");
  revalidatePath("/onboarding");

  return { success: true, workspaceId };
}

/**
 * Ropimo Centralized Permission Engine
 *
 * Single source of truth for ALL authorization decisions.
 * - Never checks permissions scattered across components.
 * - All server actions and data queries must use this.
 * - Server-only: never import in client components.
 */
import { cache } from "react";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import {
  UserContext,
  WorkspaceCapability,
  DeptMembership,
  DepartmentRole,
  WorkspaceRole,
} from "@/types/permissions";
import { Project } from "@/types/project";
import { Task } from "@/types/task";
import { FileItem } from "@/types/files";

// ─────────────────────────────────────────────────────────────────────────────
// 1. CONTEXT RESOLUTION
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Resolve the full UserContext for the currently authenticated user in a given workspace.
 * Cached per React render tree — safe to call multiple times without extra DB hits.
 */
export const getUserContext = cache(
  async (workspaceId: string): Promise<UserContext | null> => {
    if (!workspaceId) return null;

    const authClient = await createClient();
    const {
      data: { user },
      error: authError,
    } = await authClient.auth.getUser();

    if (authError || !user) return null;

    const adminClient = createAdminClient();

    // Fetch workspace role + department memberships in parallel
    const [{ data: wsMember }, { data: deptRows }] = await Promise.all([
      adminClient
        .from("workspace_members")
        .select("role")
        .eq("workspace_id", workspaceId)
        .eq("user_id", user.id)
        .maybeSingle(),
      adminClient
        .from("department_members")
        .select("department_id, role")
        .eq("workspace_id", workspaceId)
        .eq("user_id", user.id),
    ]);

    // User is not a workspace member — no access
    if (!wsMember) return null;

    const workspaceRole = wsMember.role as WorkspaceRole;
    const isOwnerOrAdmin = ["owner", "admin", "manager"].includes(workspaceRole);

    const deptMemberships: DeptMembership[] = (deptRows || []).map((row: any) => ({
      deptId: row.department_id,
      role: (row.role || "member") as DepartmentRole,
    }));

    const deptIds = deptMemberships.map((d) => d.deptId);
    const ledDeptIds = deptMemberships
      .filter((d) => d.role === "lead")
      .map((d) => d.deptId);
    const isDeptLead = ledDeptIds.length > 0;

    return {
      userId: user.id,
      workspaceId,
      workspaceRole,
      isOwnerOrAdmin,
      deptMemberships,
      deptIds,
      isDeptLead,
      ledDeptIds,
    };
  }
);

/**
 * Get UserContext or throw if unauthenticated.
 * Use in server actions that require authentication.
 */
export async function requireUserContext(workspaceId: string): Promise<UserContext> {
  const ctx = await getUserContext(workspaceId);
  if (!ctx) {
    throw new Error("Unauthorized: You must be a workspace member to perform this action.");
  }
  return ctx;
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. WORKSPACE CAPABILITIES
// ─────────────────────────────────────────────────────────────────────────────

const OWNER_ADMIN_CAPS: WorkspaceCapability[] = [
  "manage_workspace",
  "invite_people",
  "remove_people",
  "change_roles",
  "view_all_people",
  "create_department",
  "delete_department",
  "manage_any_department",
  "create_project",
  "delete_any_project",
  "manage_any_project",
  "view_all_projects",
  "create_any_task",
  "delete_any_task",
  "manage_any_task",
  "view_all_tasks",
  "view_recruitment",
  "manage_recruitment",
  "approve_leave",
  "view_all_attendance",
  "view_all_leave",
  "manage_workspace_files",
  "view_workspace_activities",
];

const DEPT_LEAD_CAPS: WorkspaceCapability[] = [
  "view_all_people",
  "create_project", // own dept only — enforced at resource level
  "create_any_task", // own dept only
  "view_all_projects", // filtered to accessible
  "view_all_tasks", // filtered to accessible
  "approve_leave", // own dept only
  "view_all_attendance", // own dept only
  "view_all_leave",
  "view_workspace_activities",
];

const MEMBER_CAPS: WorkspaceCapability[] = [
  "view_all_people",
  "view_all_projects", // filtered to accessible
  "view_all_tasks", // filtered to assigned
  "view_workspace_activities",
];

/**
 * Check if a user context has a given workspace capability.
 */
export function can(ctx: UserContext, cap: WorkspaceCapability): boolean {
  if (ctx.isOwnerOrAdmin) {
    return OWNER_ADMIN_CAPS.includes(cap);
  }
  if (ctx.isDeptLead) {
    return [...DEPT_LEAD_CAPS, ...MEMBER_CAPS].includes(cap);
  }
  return MEMBER_CAPS.includes(cap);
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. PEOPLE PERMISSIONS
// ─────────────────────────────────────────────────────────────────────────────

export function canViewPeople(ctx: UserContext): boolean {
  return true; // All workspace members can see the people directory
}

export function canInvitePeople(ctx: UserContext): boolean {
  return ctx.isOwnerOrAdmin;
}

export function canRemovePerson(ctx: UserContext, targetUserId: string): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  // Users can remove themselves
  return ctx.userId === targetUserId;
}

export function canChangePersonRole(ctx: UserContext): boolean {
  return ctx.isOwnerOrAdmin;
}

export function canEditPerson(ctx: UserContext, targetUserId: string): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  return ctx.userId === targetUserId;
}

// ─────────────────────────────────────────────────────────────────────────────
// 4. DEPARTMENT PERMISSIONS
// ─────────────────────────────────────────────────────────────────────────────

export function canCreateDepartment(ctx: UserContext): boolean {
  return ctx.isOwnerOrAdmin;
}

export function canDeleteDepartment(ctx: UserContext): boolean {
  return ctx.isOwnerOrAdmin;
}

export function canManageDepartment(ctx: UserContext, deptId: string): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  return ctx.ledDeptIds.includes(deptId);
}

export function canViewDepartment(ctx: UserContext, deptId: string): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  return ctx.deptIds.includes(deptId);
}

export function canManageDeptMembers(ctx: UserContext, deptId: string): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  return ctx.ledDeptIds.includes(deptId);
}

export function canAssignDeptLead(ctx: UserContext): boolean {
  return ctx.isOwnerOrAdmin;
}

// ─────────────────────────────────────────────────────────────────────────────
// 5. PROJECT PERMISSIONS
// ─────────────────────────────────────────────────────────────────────────────

export function canCreateProject(ctx: UserContext, departmentId?: string | null): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  // Dept leads can create projects for their own department
  if (ctx.isDeptLead && departmentId && ctx.ledDeptIds.includes(departmentId)) return true;
  return false;
}

export function canManageProject(
  ctx: UserContext,
  project: { created_by?: string | null; manager_id?: string | null; lead_id?: string | null; department_id?: string | null }
): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  if (project.created_by === ctx.userId) return true;
  if (project.manager_id === ctx.userId) return true;
  if (project.lead_id === ctx.userId) return true;
  if (ctx.isDeptLead && project.department_id && ctx.ledDeptIds.includes(project.department_id)) return true;
  return false;
}

export function canViewProject(
  ctx: UserContext,
  project: {
    created_by?: string | null;
    manager_id?: string | null;
    lead_id?: string | null;
    department_id?: string | null;
    member_ids?: string[];
  }
): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  if (project.created_by === ctx.userId) return true;
  if (project.manager_id === ctx.userId) return true;
  if (project.lead_id === ctx.userId) return true;
  if (project.member_ids?.includes(ctx.userId)) return true;
  // Dept member can see dept projects
  if (project.department_id && ctx.deptIds.includes(project.department_id)) return true;
  return false;
}

export function canDeleteProject(
  ctx: UserContext,
  project: { created_by?: string | null; manager_id?: string | null }
): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  return false;
}

// ─────────────────────────────────────────────────────────────────────────────
// 6. TASK PERMISSIONS
// ─────────────────────────────────────────────────────────────────────────────

export function canCreateTask(
  ctx: UserContext,
  opts?: { departmentId?: string | null; projectId?: string | null }
): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  if (ctx.isDeptLead) {
    if (opts?.departmentId && ctx.ledDeptIds.includes(opts.departmentId)) return true;
  }
  return false;
}

export function canViewTask(
  ctx: UserContext,
  task: {
    created_by?: string | null;
    department_id?: string | null;
    project_id?: string | null;
    assignees?: { user_id?: string | null }[];
  },
  accessibleProjectIds: string[]
): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  // Assigned
  if (task.assignees?.some((a) => a.user_id === ctx.userId)) return true;
  // Created by user
  if (task.created_by === ctx.userId) return true;
  // Dept task in user's led dept
  if (task.department_id && ctx.ledDeptIds.includes(task.department_id)) return true;
  // On accessible project
  if (task.project_id && accessibleProjectIds.includes(task.project_id)) return true;
  // Dept task in user's dept (read-only)
  if (task.department_id && ctx.deptIds.includes(task.department_id)) return true;
  return false;
}

export function canEditTask(
  ctx: UserContext,
  task: {
    created_by?: string | null;
    department_id?: string | null;
    assignees?: { user_id?: string | null }[];
  }
): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  if (task.created_by === ctx.userId) return true;
  if (task.assignees?.some((a) => a.user_id === ctx.userId)) return true;
  if (ctx.isDeptLead && task.department_id && ctx.ledDeptIds.includes(task.department_id)) return true;
  return false;
}

export function canDeleteTask(
  ctx: UserContext,
  task: {
    created_by?: string | null;
    department_id?: string | null;
  }
): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  if (task.created_by === ctx.userId) return true;
  if (ctx.isDeptLead && task.department_id && ctx.ledDeptIds.includes(task.department_id)) return true;
  return false;
}

export function canAssignTask(ctx: UserContext, task: { department_id?: string | null }): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  if (ctx.isDeptLead && task.department_id && ctx.ledDeptIds.includes(task.department_id)) return true;
  return false;
}

// ─────────────────────────────────────────────────────────────────────────────
// 7. FILE PERMISSIONS
// ─────────────────────────────────────────────────────────────────────────────

export function canViewFile(
  ctx: UserContext,
  file: {
    uploaded_by?: string | null;
    department_id?: string | null;
    project_id?: string | null;
    access_level?: string | null;
    shares?: { user_id?: string | null; department_id?: string | null }[];
  },
  accessibleProjectIds: string[]
): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  if (file.uploaded_by === ctx.userId) return true;
  if (file.access_level === "company") return true;
  if (file.shares?.some((s) => s.user_id === ctx.userId)) return true;
  if (file.shares?.some((s) => s.department_id && ctx.deptIds.includes(s.department_id))) return true;
  if (file.department_id && ctx.deptIds.includes(file.department_id)) return true;
  if (file.project_id && accessibleProjectIds.includes(file.project_id)) return true;
  return false;
}

export function canDeleteFile(
  ctx: UserContext,
  file: { uploaded_by?: string | null; department_id?: string | null }
): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  if (file.uploaded_by === ctx.userId) return true;
  if (ctx.isDeptLead && file.department_id && ctx.ledDeptIds.includes(file.department_id)) return true;
  return false;
}

export function canUploadFile(ctx: UserContext): boolean {
  return true; // All workspace members can upload
}

// ─────────────────────────────────────────────────────────────────────────────
// 8. ATTENDANCE PERMISSIONS
// ─────────────────────────────────────────────────────────────────────────────

export function canViewAttendance(ctx: UserContext, targetUserId: string): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  if (ctx.userId === targetUserId) return true;
  return false; // Dept leads see dept attendance through a scoped query
}

export function canViewDeptAttendance(ctx: UserContext, deptId: string): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  return ctx.ledDeptIds.includes(deptId);
}

export function canCheckInForUser(ctx: UserContext, targetUserId: string): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  return ctx.userId === targetUserId; // Employees can only check themselves in
}

// ─────────────────────────────────────────────────────────────────────────────
// 9. LEAVE PERMISSIONS
// ─────────────────────────────────────────────────────────────────────────────

export function canRequestLeave(ctx: UserContext): boolean {
  return true; // All workspace members can request leave
}

export function canApproveLeave(ctx: UserContext, deptId?: string | null): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  if (!deptId) return false;
  return ctx.ledDeptIds.includes(deptId);
}

export function canViewLeaveRequest(ctx: UserContext, leaveUserId: string, deptId?: string | null): boolean {
  if (ctx.isOwnerOrAdmin) return true;
  if (ctx.userId === leaveUserId) return true;
  if (ctx.isDeptLead && deptId && ctx.ledDeptIds.includes(deptId)) return true;
  return false;
}

// ─────────────────────────────────────────────────────────────────────────────
// 10. RECRUITMENT PERMISSIONS
// ─────────────────────────────────────────────────────────────────────────────

export function canViewRecruitment(ctx: UserContext): boolean {
  return ctx.isOwnerOrAdmin;
}

export function canManageRecruitment(ctx: UserContext): boolean {
  return ctx.isOwnerOrAdmin;
}

// ─────────────────────────────────────────────────────────────────────────────
// 11. CALENDAR / DOCUMENTS / MEETINGS
// ─────────────────────────────────────────────────────────────────────────────

export function canViewCalendarEvent(
  ctx: UserContext,
  event: {
    created_by?: string | null;
    department_id?: string | null;
    participants?: { user_id?: string | null }[];
  }
