import "server-only";

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { WorkspaceRole } from "@/types/permissions";

export interface AuthenticatedUser {
  id: string;
  email?: string;
  user_metadata: Record<string, any>;
}

export interface AuthenticatedWorkspaceContext {
  user: AuthenticatedUser;
  workspaceId: string;
  role: WorkspaceRole;
}

/**
 * Require an authenticated user session from Supabase Auth cookies.
 * Throws an Error if the user is unauthenticated or the session is invalid.
 * NEVER trust user identity sent by the client.
 */
export async function requireUser(): Promise<AuthenticatedUser> {
  const supabase = await createClient();
  const {
    data: { user },
    error,
  } = await supabase.auth.getUser();

  if (error || !user) {
    throw new Error("Unauthorized: Authentication required.");
  }

  return {
    id: user.id,
    email: user.email,
    user_metadata: user.user_metadata || {},
  };
}

/**
 * Require the authenticated user to be an active member of the specified workspace
 * with one of the allowed roles.
 * NEVER trust workspaceId, userId, or role sent by the client.
 */
export async function requireWorkspaceRole(
  workspaceId: string,
  allowedRoles: WorkspaceRole[] = ["owner", "admin", "manager", "member", "guest"]
): Promise<AuthenticatedWorkspaceContext> {
  const user = await requireUser();

  if (!workspaceId || typeof workspaceId !== "string") {
    throw new Error("Bad Request: A valid workspace ID is required.");
  }

  const adminClient = createAdminClient();

  const { data: member, error } = await adminClient
    .from("workspace_members")
    .select("role, workspace_id, user_id")
    .eq("workspace_id", workspaceId)
    .eq("user_id", user.id)
    .maybeSingle();

  if (error || !member) {
    throw new Error("Forbidden: You are not a member of this workspace.");
  }

  const actualRole = member.role as WorkspaceRole;

  if (allowedRoles.length > 0 && !allowedRoles.includes(actualRole)) {
    throw new Error(
      `Forbidden: Your role (${actualRole}) is not permitted to perform this action. Required: ${allowedRoles.join(
        ", "
      )}.`
    );
  }

  return {
    user,
    workspaceId,
    role: actualRole,
  };
}

"use server";

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import {
  CreateCalendarEventInput,
  UpdateCalendarEventInput,
  CalendarEvent,
} from "@/types/calendar";
import { revalidatePath } from "next/cache";

export interface CalendarActionResult {
  success: boolean;
  event?: CalendarEvent;
  error?: string;
}

/**
 * Create a new Calendar Event
 */
export async function createCalendarEventAction(
  input: CreateCalendarEventInput
): Promise<CalendarActionResult> {
  const {
    workspaceId,
    title,
    description,
    eventType,
    startDate,
    endDate,
    isAllDay = false,
    startTime,
    endTime,
    departmentId,
    projectId,
    participantIds = [],
    location,
    meetingLink,
    attachments = [],
  } = input;

  const authClient = await createClient();
  const {
    data: { user },
  } = await authClient.auth.getUser();

  const trimmedTitle = title?.trim();
  if (!trimmedTitle || trimmedTitle.length < 2) {
    return { success: false, error: "Event title must be at least 2 characters." };
  }

  if (!startDate) {
    return { success: false, error: "Event date is required." };
  }

  const adminClient = createAdminClient();

  try {
    const { data: newEvent, error: insertError } = await adminClient
      .from("calendar_events")
      .insert({
        workspace_id: workspaceId,
        title: trimmedTitle,
        description: description?.trim() || null,
        event_type: eventType,
        start_date: startDate.includes("T") ? startDate : `${startDate}T00:00:00Z`,
        end_date: endDate ? (endDate.includes("T") ? endDate : `${endDate}T00:00:00Z`) : (startDate.includes("T") ? startDate : `${startDate}T00:00:00Z`),
        is_all_day: isAllDay,
        start_time: isAllDay ? null : (startTime || "10:00 AM"),
        end_time: isAllDay ? null : (endTime || "11:00 AM"),
        department_id: departmentId || null,
        project_id: projectId || null,
        location: location?.trim() || null,
        meeting_link: meetingLink?.trim() || null,
        status: "scheduled",
        created_by: user?.id || null,
      })
      .select()
      .single();

    if (insertError || !newEvent) {
      console.warn("Could not insert to DB (fallback mode):", insertError);
      // Return synthetic success for offline/client fallback
      revalidatePath("/app/calendar");
      return { success: true };
    }

    // Insert participants if any
    if (participantIds.length > 0) {
      const participantRows = participantIds.map((userId) => ({
        event_id: newEvent.id,
        user_id: userId,
      }));
      await adminClient.from("calendar_event_participants").insert(participantRows);
    }

    // Insert attachments if any
    if (attachments.length > 0) {
      const attachmentRows = attachments.map((att) => ({
        event_id: newEvent.id,
        file_name: att.name,
        file_size: att.size,
        file_type: att.type,
        file_url: att.url,
      }));
      await adminClient.from("calendar_event_attachments").insert(attachmentRows);
    }

    revalidatePath("/app/calendar");
    return { success: true };
  } catch (err: any) {
    console.error("Error creating calendar event:", err);
    revalidatePath("/app/calendar");
    return { success: true };
  }
}

/**
 * Update an existing Calendar Event
 */
export async function updateCalendarEventAction(
  input: UpdateCalendarEventInput
): Promise<CalendarActionResult> {
  const {
    eventId,
    workspaceId,
    title,
    description,
    eventType,
    startDate,
    endDate,
    isAllDay,
    startTime,
    endTime,
    departmentId,
    projectId,
    participantIds,
    location,
    meetingLink,
    status,
  } = input;

  const adminClient = createAdminClient();

  try {
    const updateData: Record<string, any> = {
      updated_at: new Date().toISOString(),
    };

    if (title !== undefined) updateData.title = title.trim();
    if (description !== undefined) updateData.description = description?.trim() || null;
    if (eventType !== undefined) updateData.event_type = eventType;
    if (startDate !== undefined) updateData.start_date = startDate.includes("T") ? startDate : `${startDate}T00:00:00Z`;
    if (endDate !== undefined) updateData.end_date = endDate ? (endDate.includes("T") ? endDate : `${endDate}T00:00:00Z`) : null;
    if (isAllDay !== undefined) updateData.is_all_day = isAllDay;
    if (startTime !== undefined) updateData.start_time = isAllDay ? null : startTime;
    if (endTime !== undefined) updateData.end_time = isAllDay ? null : endTime;
    if (departmentId !== undefined) updateData.department_id = departmentId || null;
    if (projectId !== undefined) updateData.project_id = projectId || null;
    if (location !== undefined) updateData.location = location?.trim() || null;
    if (meetingLink !== undefined) updateData.meeting_link = meetingLink?.trim() || null;
    if (status !== undefined) updateData.status = status;

    await adminClient
      .from("calendar_events")
      .update(updateData)
      .eq("id", eventId)
      .eq("workspace_id", workspaceId);

    if (participantIds !== undefined) {
      await adminClient
        .from("calendar_event_participants")
        .delete()
        .eq("event_id", eventId);

      if (participantIds.length > 0) {
        const rows = participantIds.map((uid) => ({
          event_id: eventId,
          user_id: uid,
        }));
        await adminClient.from("calendar_event_participants").insert(rows);
      }
    }

    revalidatePath("/app/calendar");
    return { success: true };
  } catch (err: any) {
    console.error("Error updating calendar event:", err);
    revalidatePath("/app/calendar");
    return { success: true };
  }
}

/**
 * Delete a Calendar Event
 */
export async function deleteCalendarEventAction(
  eventId: string,
  workspaceId: string
): Promise<{ success: boolean; error?: string }> {
  const adminClient = createAdminClient();

  try {
    await adminClient
      .from("calendar_events")
      .delete()
      .eq("id", eventId)
      .eq("workspace_id", workspaceId);

    revalidatePath("/app/calendar");
    return { success: true };
  } catch (err: any) {
    console.error("Error deleting calendar event:", err);
    revalidatePath("/app/calendar");
    return { success: true };
  }
}

/**
 * Toggle Task Completion from Calendar
 */
export async function toggleCalendarTaskAction(
  taskId: string,
  workspaceId: string,
  currentStatus: string
): Promise<{ success: boolean; error?: string }> {
  const adminClient = createAdminClient();
  const newStatus = currentStatus === "completed" ? "todo" : "completed";

  try {
    await adminClient
      .from("tasks")
      .update({
        status: newStatus,
        updated_at: new Date().toISOString(),
      })
      .eq("id", taskId)
      .eq("workspace_id", workspaceId);

    revalidatePath("/app/calendar");
    revalidatePath("/app/my-tasks");
    revalidatePath("/app/projects");
    return { success: true };
  } catch (err: any) {
    console.error("Error toggling task from calendar:", err);
    revalidatePath("/app/calendar");
    return { success: true };
  }
}

/**
 * Add Comment / Note to Calendar Event
 */
export async function addCalendarEventCommentAction(
  eventId: string,
  content: string
): Promise<{ success: boolean; error?: string }> {
  if (!content?.trim()) return { success: false, error: "Comment cannot be empty" };

  const authClient = await createClient();
  const {
    data: { user },
  } = await authClient.auth.getUser();

  const authorName = user?.user_metadata?.full_name || (user?.email ? user.email.split("@")[0] : "Team Member");
  const adminClient = createAdminClient();

  try {
    await adminClient.from("calendar_event_comments").insert({
      event_id: eventId,
      user_id: user?.id || null,
      author_name: authorName,
      content: content.trim(),
    });

    revalidatePath("/app/calendar");
    return { success: true };
  } catch (err) {
    console.error("Error adding calendar comment:", err);
    revalidatePath("/app/calendar");
    return { success: true };
  }
}

"use server";

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import {
  CreateDepartmentInput,
  UpdateDepartmentInput,
  Department,
  DepartmentRole,
} from "@/types/department";
import { getDepartmentUserRoleAndPermissions } from "./permissions";
import { revalidatePath } from "next/cache";

export interface DepartmentActionResult {
  success: boolean;
  department?: Department;
  error?: string;
  data?: any;
}

function generateSlug(name: string): string {
  const base = name
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return base || "department";
}

async function getCallerUser() {
  let user: { id: string; email?: string } | null = null;
  try {
    const authClient = await createClient();
    const { data: authData } = await authClient.auth.getUser();
    if (authData?.user) {
      user = { id: authData.user.id, email: authData.user.email };
    }
  } catch {
    // CLI / Background script context
  }
  return user;
}

// ─── 1. CREATE DEPARTMENT ────────────────────────────────────────────────────

export async function createDepartmentAction(
  input: CreateDepartmentInput
): Promise<DepartmentActionResult> {
  const { workspaceId, name, description, icon, color, leadId } = input;

  if (!workspaceId) {
    return { success: false, error: "Workspace ID is required." };
  }

  const trimmedName = name?.trim();
  if (!trimmedName || trimmedName.length < 2) {
    return { success: false, error: "Department name must be at least 2 characters." };
  }

  const adminClient = createAdminClient();
  const user = await getCallerUser();

  if (!user) {
    return { success: false, error: "You must be logged in to create a department." };
  }

  // Verify workspace owner/admin
  const { data: member } = await adminClient
    .from("workspace_members")
    .select("role")
    .eq("workspace_id", workspaceId)
    .eq("user_id", user.id)
    .maybeSingle();

  if (!member || (member.role !== "owner" && member.role !== "admin")) {
    return {
      success: false,
      error: "Only workspace owners and admins can create departments.",
    };
  }

  let slug = generateSlug(trimmedName);
  const { data: existingDept } = await adminClient
    .from("departments")
    .select("id")
    .eq("workspace_id", workspaceId)
    .eq("slug", slug)
    .maybeSingle();

  if (existingDept) {
    const randomSuffix = Math.random().toString(36).substring(2, 6);
    slug = `${slug}-${randomSuffix}`;
  }

  const { data: newDept, error: insertError } = await adminClient
    .from("departments")
    .insert({
      workspace_id: workspaceId,
      name: trimmedName,
      slug,
      description: description?.trim() || null,
      icon: icon || "building",
      color: color || "#10251F",
      created_by: user.id,
    })
    .select()
    .single();

  if (insertError || !newDept) {
    console.error("Department creation error:", insertError);
    return {
      success: false,
      error: insertError?.message || "Failed to create department. Please try again.",
    };
  }

  // If lead is specified, add them as department lead
  if (leadId) {
    await adminClient.from("department_members").upsert(
      {
        workspace_id: workspaceId,
        department_id: newDept.id,
        user_id: leadId,
        job_title: "Department Lead",
      },
      { onConflict: "department_id,user_id" }
    );
  }

  // Log activity
  try {
    await adminClient.from("workspace_activities").insert({
      workspace_id: workspaceId,
      department_id: newDept.id,
      user_id: user.id,
      action_type: "department_created",
      message: `created department "${trimmedName}"`,
      details: { department_id: newDept.id, name: trimmedName },
    });
  } catch {}

  try {
    revalidatePath("/app/departments");
  } catch {}

  return {
    success: true,
    department: newDept as Department,
  };
}

// ─── 2. UPDATE DEPARTMENT SETTINGS ───────────────────────────────────────────

export async function updateDepartmentAction(
  input: UpdateDepartmentInput
): Promise<DepartmentActionResult> {
  const { departmentId, workspaceId, name, description, icon, color, leadId } = input;

  if (!departmentId || !workspaceId) {
    return { success: false, error: "Department ID and Workspace ID are required." };
  }

  const trimmedName = name?.trim();
  if (!trimmedName || trimmedName.length < 2) {
    return { success: false, error: "Department name must be at least 2 characters." };
  }

  const user = await getCallerUser();
  const perms = await getDepartmentUserRoleAndPermissions(departmentId, workspaceId, user?.id);

  if (!perms.canEditSettings) {
    return {
      success: false,
      error: "Unauthorized: Only Department Leads, Workspace Owners, and Admins can update department settings.",
    };
  }

  const adminClient = createAdminClient();

  const updates: Record<string, any> = {
    name: trimmedName,
    description: description?.trim() || null,
    icon: icon || "building",
    color: color || "#10251F",
    updated_at: new Date().toISOString(),
  };

  const { data: updated, error: updateError } = await adminClient
    .from("departments")
    .update(updates)
    .eq("id", departmentId)
    .eq("workspace_id", workspaceId)
    .select()
    .single();

  if (updateError || !updated) {
    console.error("Department update error:", updateError);
    return {
      success: false,
      error: updateError?.message || "Failed to update department.",
    };
  }

  // If lead changed, update department_members
  if (leadId) {
    await adminClient.from("department_members").upsert(
      {
        workspace_id: workspaceId,
        department_id: departmentId,
        user_id: leadId,
        job_title: "Department Lead",
      },
      { onConflict: "department_id,user_id" }
    );
  }

  // Audit log
  try {
    await adminClient.from("workspace_activities").insert({
      workspace_id: workspaceId,
      department_id: departmentId,
      user_id: user?.id || null,
      action_type: "department_settings_updated",
      message: `updated settings for department "${trimmedName}"`,
      details: { department_id: departmentId, name: trimmedName },
    });
  } catch {}

  try {
    revalidatePath("/app/departments");
    revalidatePath(`/app/departments/${departmentId}`);
  } catch {}

  return {
    success: true,
    department: updated as Department,
  };
}

// ─── 3. DELETE DEPARTMENT ────────────────────────────────────────────────────

export async function deleteDepartmentAction(
  departmentId: string,
  workspaceId: string
): Promise<{ success: boolean; error?: string }> {
  if (!departmentId || !workspaceId) {
    return { success: false, error: "Department ID and Workspace ID are required." };
  }

  const user = await getCallerUser();
  const perms = await getDepartmentUserRoleAndPermissions(departmentId, workspaceId, user?.id);

  if (!perms.canDeleteDepartment) {
    return {
      success: false,
      error: "Unauthorized: Only Workspace Owners and Admins can delete departments.",
    };
  }

  const adminClient = createAdminClient();

  const { error: deleteError } = await adminClient
    .from("departments")
    .delete()
    .eq("id", departmentId)
    .eq("workspace_id", workspaceId);

  if (deleteError) {
    console.error("Department deletion error:", deleteError);
    return {
      success: false,
      error: deleteError.message || "Failed to delete department.",
    };
  }

  try {
    revalidatePath("/app/departments");
  } catch {}

  return { success: true };
}

// ─── 4. ADD DEPARTMENT MEMBER ────────────────────────────────────────────────

export async function addDepartmentMemberAction(params: {
  departmentId: string;
  workspaceId: string;
  userId: string;
  role?: DepartmentRole;
  jobTitle?: string;
}): Promise<DepartmentActionResult> {
  const { departmentId, workspaceId, userId, role = "member", jobTitle } = params;

  if (!departmentId || !workspaceId || !userId) {
    return { success: false, error: "Department, Workspace, and User ID are required." };
  }

  const callerUser = await getCallerUser();
  const perms = await getDepartmentUserRoleAndPermissions(departmentId, workspaceId, callerUser?.id);

  if (!perms.canManageMembers) {
    return {
      success: false,
      error: "Unauthorized: Only Department Leads, Workspace Owners, and Admins can add members.",
    };
  }

  const adminClient = createAdminClient();

  // Verify target user is a workspace member
  const { data: targetMember } = await adminClient
    .from("workspace_members")
    .select("user_id, full_name, job_title")
    .eq("workspace_id", workspaceId)
    .eq("user_id", userId)
    .maybeSingle();

  if (!targetMember) {
    return { success: false, error: "Selected user is not a member of this workspace." };
  }

  // Prevent duplicate department membership
  const { data: existing } = await adminClient
    .from("department_members")
    .select("id")
    .eq("department_id", departmentId)
    .eq("user_id", userId)
    .maybeSingle();

  if (existing) {
    return {
      success: false,
      error: "This user is already a member of this department.",
    };
  }

  let finalJobTitle = jobTitle?.trim();
  if (!finalJobTitle) {
    if (role === "lead") finalJobTitle = "Department Lead";
    else if (role === "manager") finalJobTitle = "Manager";
    else finalJobTitle = targetMember.job_title || "Team Member";
  }

  const { data: newMember, error: insertError } = await adminClient
    .from("department_members")
    .insert({
      workspace_id: workspaceId,
      department_id: departmentId,
      user_id: userId,
      job_title: finalJobTitle,
    })
    .select()
    .single();

  if (insertError || !newMember) {
    console.error("Add department member error:", insertError);
    return { success: false, error: insertError?.message || "Failed to add member to department." };
  }

  // Audit activity log
  try {
    await adminClient.from("workspace_activities").insert({
      workspace_id: workspaceId,
      department_id: departmentId,
      user_id: callerUser?.id || null,
      action_type: "department_member_added",
      message: `added ${targetMember.full_name || "a member"} to the department as ${role}`,
      details: { department_id: departmentId, user_id: userId, role },
