      .delete()
      .eq("id", documentId)
      .eq("workspace_id", workspaceId);

    revalidatePath("/app/documents");
    return { success: true };
  } catch (err) {
    console.error("Error deleting document:", err);
    revalidatePath("/app/documents");
    return { success: true };
  }
}

/**
