"use server";

import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import {
  MeetingItem,
  CreateMeetingInput,
  UpdateMeetingInput,
} from "@/types/meetings";

export async function createMeetingAction(
  input: CreateMeetingInput & { workspace_id: string }
): Promise<{ success: boolean; meeting?: MeetingItem; error?: string }> {
  try {
    const adminClient = createAdminClient();
    let userId = input.organizer_id;

    try {
      const supabase = await createClient();
      const { data: authData } = await supabase.auth.getUser();
      if (authData?.user) {
        userId = authData.user.id;
      }
    } catch {
      // CLI / background context
    }

    const meetingLink = `https://meet.brnnd.com/${input.title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
    const meetingCode = Math.random().toString().slice(2, 5) + "-" + Math.random().toString().slice(2, 5) + "-" + Math.random().toString().slice(2, 5);

    const startIso = input.date ? `${input.date}T10:00:00Z` : new Date().toISOString();
    const endIso = input.date ? `${input.date}T11:00:00Z` : new Date(Date.now() + 3600000).toISOString();

    // 1. Try workspace_meetings table
    const { data: wmRow, error: wmErr } = await adminClient
      .from("workspace_meetings")
      .insert({
        workspace_id: input.workspace_id,
        title: input.title.trim(),
        description: input.description?.trim() || null,
        status: (input.status || "scheduled").toLowerCase(),
        start_time: startIso,
        end_time: endIso,
        duration_minutes: 60,
        location: input.location_value || "Google Meet",
        meeting_url: meetingLink,
        created_by: userId || null,
        attendees: (input.attendees || []).map((a, i) => ({ ...a, id: `att-${Date.now()}-${i}` })),
        attendee_count: (input.attendees || []).length || 1,
        agenda: (input.agenda || []).map((a, i) => ({ ...a, id: `ag-${Date.now()}-${i}` })),
        attachments: (input.attachments || []).map((a, i) => ({ ...a, id: `attach-${Date.now()}-${i}` })),
      })
      .select()
      .single();

    if (!wmErr && wmRow) {
      revalidatePath("/app/meetings");
      return { success: true, meeting: wmRow as unknown as MeetingItem };
    }

    // 2. Fallback to calendar_events table
    const calDateIso = `${input.date}T10:00:00Z`;
    const { data: calRow, error: calErr } = await adminClient
      .from("calendar_events")
      .insert({
        workspace_id: input.workspace_id,
        title: input.title.trim(),
        description: input.description?.trim() || null,
        event_type: "meeting",
        start_date: calDateIso,
        end_date: calDateIso,
        is_all_day: false,
        start_time: input.start_time,
        end_time: input.end_time,
        department_id: input.department_id || null,
        project_id: input.project_id || null,
        location: input.location_value || null,
        meeting_link: meetingLink,
        status: "scheduled",
        created_by: userId || null,
      })
      .select()
      .single();

    if (calErr) {
      return { success: false, error: calErr.message || "Failed to create meeting." };
    }

    const meeting: MeetingItem = {
      id: calRow.id,
      workspace_id: calRow.workspace_id,
      title: calRow.title,
      description: calRow.description || "",
      type: input.type,
      status: "Upcoming",
      date: input.date,
      start_time: input.start_time,
      end_time: input.end_time,
      duration_minutes: 60,
      timezone: input.timezone || "Asia/Dhaka",
      organizer_id: userId || "user-lead",
      organizer_name: "Tashin Khan",
      department_id: input.department_id,
      project_id: input.project_id,
      attendees: (input.attendees || []).map((a, i) => ({ ...a, id: `att-${i}` })),
      attendee_count: (input.attendees || []).length || 1,
      agenda: [],
      attachments: [],
      location_type: input.location_type || "Video",
      location_value: input.location_value,
      meeting_link: meetingLink,
      meeting_id_code: meetingCode,
      is_recurring: input.is_recurring || false,
      recurrence: input.recurrence || "None",
      notify_attendees: input.notify_attendees ?? true,
      created_at: calRow.created_at,
      updated_at: calRow.updated_at,
    };

    revalidatePath("/app/meetings");
    return { success: true, meeting };
  } catch (err: any) {
    return { success: false, error: err.message || "An unexpected error occurred." };
  }
}

export async function updateMeetingAction(
  input: UpdateMeetingInput
): Promise<{ success: boolean; meeting?: MeetingItem; error?: string }> {
  try {
    const adminClient = createAdminClient();

    // 1. Try workspace_meetings
    const { data: wmRow, error: wmErr } = await adminClient
      .from("workspace_meetings")
      .update({
        ...(input.title ? { title: input.title } : {}),
        ...(input.description !== undefined ? { description: input.description } : {}),
        ...(input.type ? { type: input.type } : {}),
        ...(input.date ? { date: input.date } : {}),
        ...(input.start_time ? { start_time: input.start_time } : {}),
        ...(input.end_time ? { end_time: input.end_time } : {}),
        ...(input.status ? { status: input.status } : {}),
        ...(input.notes !== undefined ? { notes: input.notes } : {}),
        ...(input.cancellation_reason ? { cancellation_reason: input.cancellation_reason } : {}),
        ...(input.attendees ? { attendees: input.attendees, attendee_count: input.attendees.length } : {}),
        ...(input.agenda ? { agenda: input.agenda } : {}),
        ...(input.attachments ? { attachments: input.attachments } : {}),
        updated_at: new Date().toISOString(),
      })
      .eq("id", input.id)
      .select()
      .maybeSingle();

    if (!wmErr && wmRow) {
      revalidatePath("/app/meetings");
      return { success: true, meeting: wmRow as unknown as MeetingItem };
    }

    // 2. Fallback to calendar_events
    let calStatus: string | undefined;
    if (input.status === "Completed") calStatus = "completed";
    else if (input.status === "Cancelled") calStatus = "cancelled";
    else if (input.status === "Live") calStatus = "in_progress";
    else if (input.status === "Upcoming") calStatus = "scheduled";

    await adminClient
      .from("calendar_events")
      .update({
        ...(input.title ? { title: input.title } : {}),
        ...(input.description !== undefined ? { description: input.description } : {}),
        ...(calStatus ? { status: calStatus } : {}),
        updated_at: new Date().toISOString(),
      })
      .eq("id", input.id);

    revalidatePath("/app/meetings");
    return { success: true };
  } catch (err: any) {
    return { success: false, error: err.message || "An unexpected error occurred." };
  }
}

/**
 * Convert a meeting action item into a workspace task
 */
export async function convertMeetingActionItemToTaskAction(params: {
  workspaceId: string;
  meetingId: string;
  title: string;
  assigneeId?: string;
  dueDate?: string;
  priority?: "low" | "medium" | "high" | "urgent";
}): Promise<{ success: boolean; taskId?: string; error?: string }> {
  try {
    const { requireWorkspaceRole } = await import("@/lib/auth/require-user");
    await requireWorkspaceRole(params.workspaceId);

    const title = params.title?.trim();
    if (!title) {
      return { success: false, error: "Action item title is required." };
    }

    const adminClient = createAdminClient();

    // 1. Fetch meeting title for task context
    const { data: meeting } = await adminClient
      .from("workspace_meetings")
      .select("title, agenda")
      .eq("id", params.meetingId)
      .maybeSingle();

    const meetingTitle = meeting?.title || "Meeting";

    // 2. Insert new task
    const { data: task, error: taskError } = await adminClient
      .from("tasks")
      .insert({
        workspace_id: params.workspaceId,
        title,
        description: `Action item originated from meeting: "${meetingTitle}"`,
        status: "todo",
        priority: params.priority || "medium",
        due_date: params.dueDate ? new Date(params.dueDate).toISOString() : null,
      })
      .select("id")
      .single();

    if (taskError || !task) {
      return { success: false, error: taskError?.message || "Failed to create task from action item." };
    }

    // 3. Assign task if assignee specified
    if (params.assigneeId) {
      try {
        await adminClient.from("task_assignees").insert({
          task_id: task.id,
          user_id: params.assigneeId,
        });
      } catch (assignErr) {
        console.warn("Assignee insertion note:", assignErr);
      }
    }

    revalidatePath("/app/meetings");
    revalidatePath("/app/tasks");
    revalidatePath("/app/my-tasks");

    return { success: true, taskId: task.id };
  } catch (err: any) {
    return { success: false, error: err.message || "Failed to convert action item to task." };
  }
}

export async function cancelMeetingAction(
  meetingId: string,
  reason?: string
): Promise<{ success: boolean; error?: string }> {
  try {
    const adminClient = createAdminClient();
    const now = new Date().toISOString();

    await adminClient
      .from("workspace_meetings")
      .update({
        status: "cancelled",
        cancelled_at: now,
        cancellation_reason: reason || "Cancelled by host",
        updated_at: now,
      })
      .eq("id", meetingId);

    await adminClient
      .from("calendar_events")
      .update({
        status: "cancelled",
        updated_at: now,
      })
      .eq("id", meetingId);

    revalidatePath("/app/meetings");
    return { success: true };
  } catch (err: any) {
    return { success: false, error: err.message || "Failed to cancel meeting." };
  }
}

export async function deleteMeetingAction(
  meetingId: string
): Promise<{ success: boolean; error?: string }> {
  try {
    const adminClient = createAdminClient();

    await adminClient.from("workspace_meetings").delete().eq("id", meetingId);
    await adminClient.from("calendar_events").delete().eq("id", meetingId);

    revalidatePath("/app/meetings");
    return { success: true };
  } catch (err: any) {
    return { success: false, error: err.message || "Failed to delete meeting." };
  }
}

import { cache } from "react";
import { createAdminClient } from "@/lib/supabase/admin";
import {
  MeetingItem,
  MeetingStats,
  MeetingInsights,
  MeetingType,
  MeetingStatus,
  MeetingAttendee,
} from "@/types/meetings";

export const getWorkspaceMeetings = cache(
  async (
    workspaceId: string,
    options?: {
      status?: string;
      date?: string;
      departmentId?: string;
      projectId?: string;
    }
  ): Promise<MeetingItem[]> => {
    if (!workspaceId) return [];

    const adminClient = createAdminClient();

    // 1. Try querying dedicated workspace_meetings table
    const { data: wmRows, error: wmErr } = await adminClient
      .from("workspace_meetings")
      .select("*")
      .eq("workspace_id", workspaceId)
      .order("start_time", { ascending: false });

    if (!wmErr && wmRows && wmRows.length > 0) {
      let list: MeetingItem[] = wmRows.map((r: any) => {
        const rawDate = r.start_time
          ? new Date(r.start_time).toISOString().split("T")[0]
          : new Date().toISOString().split("T")[0];
        const rawStartTime = r.start_time
          ? new Date(r.start_time).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
          : "10:00 AM";
        const rawEndTime = r.end_time
          ? new Date(r.end_time).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
          : "11:00 AM";
        let status: MeetingStatus = "Upcoming";
        if (r.status === "completed") status = "Completed";
        else if (r.status === "cancelled") status = "Cancelled";
        else if (r.status === "in_progress") status = "Live";

        return {
          id: r.id,
          workspace_id: r.workspace_id,
          title: r.title,
          description: r.description || "",
          type: (r.type || "Internal") as MeetingType,
          status,
          date: rawDate,
          start_time: rawStartTime,
          end_time: rawEndTime,
          duration_minutes: 60,
          timezone: "Asia/Dhaka",
          organizer_id: r.created_by || "user-organizer",
          organizer_name: "Organizer",
          attendees: [],
          attendee_count: 1,
          agenda: [],
          attachments: [],
          location_type:
            r.location?.includes("http") || r.meeting_url ? "Video" : "Physical",
          location_value: r.location || undefined,
          location_details: r.location || r.meeting_url || "Main Office",
          meeting_link: r.meeting_url || undefined,
          meeting_id_code: r.id.substring(0, 8),
          is_recurring: false,
          notify_attendees: true,
          created_at: r.created_at || new Date().toISOString(),
          updated_at: r.updated_at || new Date().toISOString(),
        };
      });

      if (options?.status && options.status !== "All") {
        list = list.filter((m) => m.status === options.status);
      }
      if (options?.date) {
        list = list.filter((m) => m.date === options.date);
      }
      return list;
    }

    // 2. Fallback to calendar_events table where event_type = 'meeting'
    const { data: calRows, error: calErr } = await adminClient
      .from("calendar_events")
      .select(`
        *,
        departments:department_id (id, name, color),
        projects:project_id (id, name, color)
      `)
      .eq("workspace_id", workspaceId)
      .eq("event_type", "meeting")
      .order("start_date", { ascending: false });

    if (!calErr && calRows) {
      const meetings: MeetingItem[] = calRows.map((r) => {
        const rawDate = r.start_date ? new Date(r.start_date).toISOString().split("T")[0] : new Date().toISOString().split("T")[0];
        let status: MeetingStatus = "Upcoming";
        if (r.status === "completed") status = "Completed";
        else if (r.status === "cancelled") status = "Cancelled";
        else if (r.status === "in_progress") status = "Live";

        return {
          id: r.id,
          workspace_id: r.workspace_id,
          title: r.title,
          description: r.description || "",
          type: "Internal" as MeetingType,
          status,
          date: rawDate,
          start_time: r.start_time || "10:00 AM",
          end_time: r.end_time || "11:00 AM",
          duration_minutes: 60,
          timezone: "Asia/Dhaka",
          organizer_id: r.created_by || "user-organizer",
          organizer_name: "Team Lead",
          department_id: r.department_id || undefined,
          department_name: r.departments?.name,
          project_id: r.project_id || undefined,
          project_name: r.projects?.name,
          attendees: [],
          attendee_count: 1,
          agenda: [],
          attachments: [],
          location_type: r.location ? "Physical" : "Video",
          location_value: r.location || undefined,
          meeting_link: r.meeting_link || undefined,
          meeting_id_code: r.id.substring(0, 8),
          is_recurring: false,
          notify_attendees: true,
          created_at: r.created_at || new Date().toISOString(),
          updated_at: r.updated_at || new Date().toISOString(),
        };
      });

      return meetings;
    }

    return [];
  }
);

export const getMeetingStats = cache(
  async (workspaceId: string): Promise<MeetingStats> => {
    const meetings = await getWorkspaceMeetings(workspaceId);

    const now = new Date();
    const todayStr = now.toISOString().split("T")[0];
    const sevenDaysLater = new Date(now.getTime() + 7 * 86400000).toISOString().split("T")[0];
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;

    let upcomingThisWeek = 0;
    let totalAttended = 0;
    let totalMinutes = 0;
    let cancelledThisMonth = 0;

    for (const m of meetings) {
      if ((m.status === "Upcoming" || m.status === "Live") && m.date >= todayStr && m.date <= sevenDaysLater) {
        upcomingThisWeek++;
      }
      if (m.status === "Completed") {
        totalAttended++;
        totalMinutes += m.duration_minutes || 60;
      }
      if (m.status === "Cancelled" && m.date.startsWith(currentMonthPrefix)) {
        cancelledThisMonth++;
      }
    }

    return {
      totalMeetings: meetings.length,
      upcomingThisWeek,
      totalAttended,
      totalHours: Number((totalMinutes / 60).toFixed(1)),
      cancelledThisMonth,
    };
  }
);

export const getMeetingInsights = cache(
  async (workspaceId: string): Promise<MeetingInsights> => {
    const meetings = await getWorkspaceMeetings(workspaceId);
    let meetingsHeld = 0;
    let totalParticipants = 0;
    let totalMinutes = 0;
    let meetingsCancelled = 0;

    for (const m of meetings) {
      if (m.status === "Completed") {
        meetingsHeld++;
        totalParticipants += m.attendee_count || 1;
        totalMinutes += m.duration_minutes || 60;
      } else if (m.status === "Cancelled") {
        meetingsCancelled++;
      }
    }

    return {
      meetingsHeld,
      totalParticipants,
      avgMeetingMinutes: meetingsHeld > 0 ? Math.round(totalMinutes / meetingsHeld) : 0,
      meetingsCancelled,
    };
  }
);

