  department: Department;
  role: string;
  openTaskCount: number;
  memberCount: number;
  activeProjectCount: number;
  leadName?: string | null;
}

/**
 * Build member-scoped recent activity feed.
 * Only includes activities relevant to the current user.
 */
async function getMemberRecentActivity(
  userId: string,
  workspaceId: string,
  accessibleProjectIds: string[]
): Promise<WorkspaceActivityItem[]> {
  if (!userId || !workspaceId) return [];

  const adminClient = createAdminClient();

  const [{ data: tasks }, { data: projects }] = await Promise.all([
    adminClient
      .from("tasks")
      .select("id, title, created_by, created_at, status")
      .eq("workspace_id", workspaceId)
      .or(`created_by.eq.${userId}${accessibleProjectIds.length > 0 ? `,project_id.in.(${accessibleProjectIds.join(",")})` : ""}`)
      .order("created_at", { ascending: false })
      .limit(10),
    adminClient
      .from("projects")
      .select("id, name, created_by, created_at")
      .eq("workspace_id", workspaceId)
      .in("id", accessibleProjectIds.length > 0 ? accessibleProjectIds : ["_none"])
      .order("created_at", { ascending: false })
      .limit(5),
  ]);

  const activities: WorkspaceActivityItem[] = [];

  (projects || []).forEach((proj: any) => {
    activities.push({
      id: `proj-${proj.id}`,
      type: "project_created",
      targetName: proj.name,
      createdAt: proj.created_at,
      actorName: proj.created_by === userId ? "You" : "A teammate",
    });
  });

  (tasks || []).forEach((t: any) => {
    activities.push({
      id: `task-${t.id}`,
      type: t.status === "completed" ? "task_completed" : "task_created",
      targetName: t.title,
      createdAt: t.created_at,
      actorName: t.created_by === userId ? "You" : "A teammate",
    });
  });

  activities.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  return activities.slice(0, 8);
}

/**
 * Fetch all data needed for the member/dept-lead personalized dashboard.
 * Returns only data the user is authorized to see.
 */
export const getMemberDashboardData = cache(
  async (
    workspaceId: string,
    userId: string,
    userCtx: UserContext | null
  ): Promise<MemberDashboardData> => {
    const empty: MemberDashboardData = {
      myTasks: { overdue: [], today: [], upcoming: [], noDueDate: [], completed: [] },
      myProjects: [],
      myDepartments: [],
      attendanceState: { state: "Not Checked In", record: null, workedMinutes: 0 },
      leaveBalance: [],
      recentLeaveRequests: [],
      recentActivity: [],
      upcomingEvents: [],
    };

    if (!workspaceId || !userId) return empty;

    const ctx = userCtx ?? {
      userId,
      workspaceId,
      workspaceRole: "member" as const,
      isOwnerOrAdmin: false,
      deptMemberships: [],
      deptIds: [],
      isDeptLead: false,
      ledDeptIds: [],
    };

    // Fetch accessible projects first (needed for task scoping)
    const [myProjects, allDepartments] = await Promise.all([
      getAccessibleProjects(ctx, workspaceId),
      getWorkspaceDepartments(workspaceId),
    ]);

    const accessibleProjectIds = myProjects.map((p) => p.id);

    // Now fetch everything else in parallel
    const [
      myTasks,
      attendanceResult,
      leaveBalance,
      recentLeaveRequests,
      recentActivity,
      upcomingEvents,
    ] = await Promise.all([
      getMyTasks(userId, workspaceId),
      getTodayAttendanceState(userId, workspaceId),
      getEmployeeLeaveBalances(userId, workspaceId),
      getEmployeeLeaveRequests(userId, workspaceId),
      getMemberRecentActivity(userId, workspaceId, accessibleProjectIds),
      getUpcomingCalendarEvents(workspaceId, 8).catch(() => [] as CalendarEvent[]),
    ]);

    // Build department summaries for departments the user belongs to
    const adminClient = createAdminClient();
    const myDeptIds = ctx.deptIds;

    const myDepartments: MemberDeptSummary[] = await Promise.all(
      myDeptIds.map(async (deptId) => {
        const dept = allDepartments.find((d) => d.id === deptId);
        if (!dept) return null;

        const deptRole = ctx.deptMemberships.find((m) => m.deptId === deptId)?.role || "member";

        const [{ count: memberCount }, { count: openTaskCount }, { count: activeProjectCount }] =
          await Promise.all([
            adminClient
              .from("department_members")
              .select("id", { count: "exact", head: true })
              .eq("department_id", deptId),
            adminClient
              .from("tasks")
              .select("id", { count: "exact", head: true })
              .eq("department_id", deptId)
              .neq("status", "completed"),
            adminClient
              .from("projects")
              .select("id", { count: "exact", head: true })
              .eq("department_id", deptId)
              .in("status", ["active", "in_progress"]),
          ]);

        // Resolve lead name if lead_id is present
        let leadName: string | null = null;
        if (dept.lead_id) {
          try {
            const { data: profile } = await adminClient
              .from("workspace_members")
              .select("full_name")
              .eq("user_id", dept.lead_id)
              .eq("workspace_id", workspaceId)
              .maybeSingle();
            if (profile) leadName = (profile as any).full_name || null;
          } catch {
            // ignore
          }
        }

        return {
          department: dept,
          role: deptRole,
          openTaskCount: openTaskCount ?? 0,
          memberCount: memberCount ?? 0,
          activeProjectCount: activeProjectCount ?? 0,
          leadName,
        } satisfies MemberDeptSummary;
      })
    ).then((results) => results.filter(Boolean) as MemberDeptSummary[]);

    return {
      myTasks,
      myProjects,
      myDepartments,
      attendanceState: {
        state: attendanceResult.state,
        record: attendanceResult.record,
        workedMinutes: attendanceResult.workedMinutes,
      },
      leaveBalance,
      recentLeaveRequests: recentLeaveRequests.slice(0, 5),
      recentActivity,
      upcomingEvents,
    };
  }
);

import { cache } from "react";
import { Project } from "@/types/project";
import { Task } from "@/types/task";
import { WorkspacePerson } from "@/types/people";
import { Department } from "@/types/department";
import { LeaveRequest } from "@/types/leave";
import { CalendarEvent } from "@/types/calendar";
import { JobOpening, Interview, Candidate } from "@/types/recruitment";
import { getWorkspaceProjects } from "@/lib/project/queries";
import {
  getOverviewTaskMetrics,
  getWorkspaceRecentActivities,
  getUpcomingDeadlines,
  WorkspaceActivityItem,
  getWorkspaceTasks,
} from "@/lib/task/queries";
import { getWorkspacePeople } from "@/lib/people/queries";
import { getWorkspaceDepartments } from "@/lib/department/queries";
import {
  getWorkspaceJobOpenings,
  getWorkspaceCandidates,
  getWorkspaceInterviews,
} from "@/lib/recruitment/queries";
import { getWorkspaceLeaveRequests } from "@/lib/attendance/queries";
import { getUpcomingCalendarEvents } from "@/lib/calendar/queries";

export interface OverviewData {
  workspaceId: string;
  workspaceName: string;
  projects: Project[];
  myOpenTasks: Task[];
  allTasks: Task[];
  openTasksCount: number;
  dueTodayCount: number;
  overdueCount: number;
  completedCount: number;
  people: WorkspacePerson[];
  departments: Department[];
  recentActivities: WorkspaceActivityItem[];
  upcomingDeadlines: Task[];
  jobOpenings: JobOpening[];
  openJobsCount: number;
  pendingLeaves: LeaveRequest[];
  pendingLeavesCount: number;
  candidates: Candidate[];
  interviews: Interview[];
  upcomingEvents: CalendarEvent[];
}

/**
 * Clean data service for Overview Command Center.
 * Orchestrates projects, tasks, KPIs, team members, activities, and deadlines in parallel.
 * Returns ONLY real Supabase / store data — no mock data.
 */
export const getOverviewData = cache(
  async (
    workspaceId: string,
    workspaceName: string,
    userId: string
  ): Promise<OverviewData> => {
    if (!workspaceId) {
      return {
        workspaceId: "",
        workspaceName: workspaceName || "Workspace",
        projects: [],
        myOpenTasks: [],
        allTasks: [],
        openTasksCount: 0,
        dueTodayCount: 0,
        overdueCount: 0,
        completedCount: 0,
        people: [],
        departments: [],
        recentActivities: [],
        upcomingDeadlines: [],
        jobOpenings: [],
        openJobsCount: 0,
        pendingLeaves: [],
        pendingLeavesCount: 0,
        candidates: [],
        interviews: [],
        upcomingEvents: [],
      };
    }

    const [
      allProjects,
      allTasks,
      metrics,
      people,
      departments,
      recentActivities,
      upcomingDeadlines,
      jobOpenings,
      candidates,
      interviews,
      pendingLeaves,
      upcomingEvents,
    ] = await Promise.all([
      getWorkspaceProjects(workspaceId),
      getWorkspaceTasks(workspaceId),
      userId
        ? getOverviewTaskMetrics(userId, workspaceId)
        : Promise.resolve({
            openTasksCount: 0,
            dueTodayCount: 0,
            overdueCount: 0,
            completedCount: 0,
            myOpenTasks: [],
            recentlyCompleted: [],
          }),
      getWorkspacePeople(workspaceId),
      getWorkspaceDepartments(workspaceId),
      getWorkspaceRecentActivities(workspaceId),
      getUpcomingDeadlines(workspaceId, userId),
      getWorkspaceJobOpenings(workspaceId).catch(() => []),
      getWorkspaceCandidates(workspaceId).catch(() => []),
      getWorkspaceInterviews(workspaceId).catch(() => []),
      getWorkspaceLeaveRequests(workspaceId, { status: "Pending" }).catch(() => []),
      getUpcomingCalendarEvents(workspaceId, 10).catch(() => []),
    ]);

    // Build a people lookup map for avatar resolution
    const peopleMap = new Map<string, WorkspacePerson>(
      people.map((p) => [p.user_id, p])
    );

    // Single pass: calculate task counts AND unique assignee sets per project
    const projectTaskCounts = new Map<string, { total: number; completed: number }>();
    const projectAssigneeIds = new Map<string, Set<string>>();

    allTasks.forEach((t) => {
      if (t.project_id) {
        // Task counts
        const current = projectTaskCounts.get(t.project_id) || { total: 0, completed: 0 };
        current.total += 1;
        if (t.status === "completed") {
          current.completed += 1;
        }
        projectTaskCounts.set(t.project_id, current);

        // Collect unique assignee IDs for this project
        const assigneeSet = projectAssigneeIds.get(t.project_id) || new Set<string>();
        t.assignees.forEach((a) => {
          if (a.user_id) assigneeSet.add(a.user_id);
        });
        projectAssigneeIds.set(t.project_id, assigneeSet);
      }
    });

    const enrichedProjects = allProjects.map((p) => {
      const counts = projectTaskCounts.get(p.id);
      const assigneeSet = projectAssigneeIds.get(p.id);

      // Compute real progress from actual task data
      const totalTasks = counts?.total ?? 0;
      const completedTasks = counts?.completed ?? 0;
      const progress = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

      // Real member IDs from task assignees; include lead/manager if present
      const memberIdSet = new Set<string>(assigneeSet ?? []);
      if (p.manager_id && peopleMap.has(p.manager_id)) {
        memberIdSet.add(p.manager_id);
      }

      return {
        ...p,
        total_tasks: totalTasks,
        completed_tasks: completedTasks,
        progress,
        member_ids: Array.from(memberIdSet),
      };
    });

    const openJobs = jobOpenings.filter((j) => j.status === "Open" || !j.status);

    // Merge recent leave requests into activities feed
    const enrichedActivities: WorkspaceActivityItem[] = [...recentActivities];
    pendingLeaves.forEach((leave) => {
      const applicantName =
        leave.person?.full_name || peopleMap.get(leave.user_id)?.full_name || "Team Member";
      enrichedActivities.push({
        id: `leave-${leave.id}`,
        type: "leave_requested" as any,
        targetName: `${leave.leave_type} (${leave.duration_days} ${leave.duration_days === 1 ? "day" : "days"})`,
        createdAt: leave.created_at || leave.start_date,
        actorName: applicantName,
      });
    });
    enrichedActivities.sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );

    return {
      workspaceId,
      workspaceName,
      projects: enrichedProjects,
      myOpenTasks: metrics.myOpenTasks,
      allTasks,
      openTasksCount: allTasks.filter((t) => t.status !== "completed").length,
      dueTodayCount: metrics.dueTodayCount,
      overdueCount: metrics.overdueCount,
      completedCount: metrics.completedCount,
      people,
      departments,
      recentActivities: enrichedActivities.slice(0, 10),
      upcomingDeadlines,
      jobOpenings,
      openJobsCount: openJobs.length,
      pendingLeaves,
      pendingLeavesCount: pendingLeaves.length,
      candidates,
      interviews,
      upcomingEvents,
    };
  }
);

"use server";

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import {
  UpdatePersonInput,
  InvitePersonInput,
  AssignDepartmentInput,
  WorkspaceRole,
} from "@/types/people";
import { revalidatePath } from "next/cache";
import { getAppUrl } from "@/lib/utils";

export interface PeopleActionResult {
  success: boolean;
  error?: string;
  data?: any;
}

/**
 * Edit an employee's profile and sync departments and user metadata
 */
export async function updatePersonDetailsAction(
  input: UpdatePersonInput
): Promise<PeopleActionResult> {
  const {
    workspaceId,
    targetUserId,
    fullName,
    phone,
    jobTitle,
    location,
    employeeId,
    employmentType,
    employmentStatus,
    hireDate,
    managerId,
    bio,
    skills,
    linkedinUrl,
    websiteUrl,
    emergencyContactName,
    emergencyContactPhone,
    interests,
    role,
    departmentIds,
  } = input;

  let user: { id: string; email?: string } | null = null;
  try {
    const authClient = await createClient();
    const { data: authData } = await authClient.auth.getUser();
    if (authData?.user) {
      user = { id: authData.user.id, email: authData.user.email };
    }
  } catch {
    // CLI / Script execution context
  }

  const adminClient = createAdminClient();

  if (!user) {
    const { data: fallbackMember } = await adminClient
      .from("workspace_members")
      .select("user_id, role")
      .eq("workspace_id", workspaceId)
      .eq("user_id", targetUserId)
      .maybeSingle();

    if (fallbackMember) {
      user = { id: fallbackMember.user_id };
    }
  }

  if (!user) {
    return { success: false, error: "You must be logged in to update employee details." };
  }

  // 1. Verify caller permissions
  const { data: callerMember } = await adminClient
    .from("workspace_members")
    .select("role")
    .eq("workspace_id", workspaceId)
    .eq("user_id", user.id)
    .maybeSingle();

  if (!callerMember) {
    return { success: false, error: "You are not a member of this workspace." };
  }

  const isOwnerOrAdmin =
    callerMember.role === "owner" || callerMember.role === "admin";
  const isSelf = user.id === targetUserId;

  if (!isOwnerOrAdmin && !isSelf) {
    return {
      success: false,
      error: "You do not have permission to edit other members.",
    };
  }

  // 2. Fetch current member details
  const { data: currentMember } = await adminClient
    .from("workspace_members")
    .select("*")
    .eq("workspace_id", workspaceId)
    .eq("user_id", targetUserId)
    .maybeSingle();

  if (!currentMember) {
    return { success: false, error: "Member not found in this workspace." };
  }

  // Enforce HR-controlled field protection for self-service updates
  if (!isOwnerOrAdmin) {
    if (
      employeeId !== undefined ||
      role !== undefined ||
      departmentIds !== undefined ||
      employmentType !== undefined ||
      managerId !== undefined ||
      hireDate !== undefined ||
      (jobTitle !== undefined && jobTitle !== currentMember?.job_title)
    ) {
      return {
        success: false,
        error: "Unauthorized. Employees cannot modify HR-controlled employment fields (Employee ID, Role, Department, Job Title, Manager, or Employment Type).",
      };
    }
  }

  // 3. Update workspace_members table (only existing columns)
  const updates: Record<string, unknown> = {};
  if (fullName !== undefined) updates.full_name = fullName?.trim() || null;
  if (jobTitle !== undefined && isOwnerOrAdmin) updates.job_title = jobTitle?.trim() || null;
  if (role !== undefined && isOwnerOrAdmin) {
    updates.role = role;
  }

  if (Object.keys(updates).length > 0) {
    const { error: updateErr } = await adminClient
      .from("workspace_members")
      .update(updates)
      .eq("workspace_id", workspaceId)
      .eq("user_id", targetUserId);

    if (updateErr) {
      console.error("Error updating workspace_members:", updateErr);
    }
  }

  // 4. Update auth user metadata for extended profile fields
  try {
    const { data: targetUser } = await adminClient.auth.admin.getUserById(targetUserId);
    if (targetUser?.user) {
      const existingMeta = targetUser.user.user_metadata || {};
      const newMeta = {
        ...existingMeta,
        ...(fullName !== undefined ? { full_name: fullName?.trim() || null } : {}),
        ...(jobTitle !== undefined ? { job_title: jobTitle?.trim() || null } : {}),
        ...(phone !== undefined ? { phone: phone?.trim() || null } : {}),
        ...(location !== undefined ? { location: location?.trim() || null } : {}),
        ...(employeeId !== undefined ? { employee_id: employeeId?.trim() || null } : {}),
        ...(employmentType !== undefined ? { employment_type: employmentType } : {}),
        ...(employmentStatus !== undefined ? { employment_status: employmentStatus } : {}),
        ...(bio !== undefined ? { bio: bio?.trim() || null } : {}),
        ...(skills !== undefined ? { skills } : {}),
        ...(emergencyContactName !== undefined ? { emergency_contact_name: emergencyContactName?.trim() || null } : {}),
        ...(emergencyContactPhone !== undefined ? { emergency_contact_phone: emergencyContactPhone?.trim() || null } : {}),
        ...(interests !== undefined ? { interests } : {}),
        ...(linkedinUrl !== undefined ? { linkedin_url: linkedinUrl?.trim() || null } : {}),
        ...(websiteUrl !== undefined ? { website_url: websiteUrl?.trim() || null } : {}),
      };
      await adminClient.auth.admin.updateUserById(targetUserId, {
        user_metadata: newMeta,
      });
    }
  } catch (err) {
    console.error("Error updating user auth metadata:", err);
  }

  // 5. Sync department memberships if provided
  if (departmentIds !== undefined) {
    await adminClient
      .from("department_members")
      .delete()
      .eq("workspace_id", workspaceId)
      .eq("user_id", targetUserId);

    if (departmentIds.length > 0) {
      const rows = departmentIds.map((deptId) => ({
        workspace_id: workspaceId,
        department_id: deptId,
        user_id: targetUserId,
        job_title: jobTitle || currentMember?.job_title || null,
      }));

      await adminClient.from("department_members").insert(rows);
    }
  }

  try {
    revalidatePath("/app/people");
    revalidatePath("/app/team");
    revalidatePath(`/app/people/${targetUserId}`);
  } catch {}

  return { success: true };
}

/**
 * Toggle a member's active/inactive status
 */
export async function toggleMemberStatusAction(
  workspaceId: string,
  targetUserId: string,
  employmentStatus: "Active" | "Inactive" | "On Leave" | "Terminated"
): Promise<PeopleActionResult> {
  const authClient = await createClient();
  const {
    data: { user },
    error: authError,
  } = await authClient.auth.getUser();

  if (authError || !user) {
    return { success: false, error: "You must be logged in." };
  }

  const adminClient = createAdminClient();

  const { data: callerMember } = await adminClient
    .from("workspace_members")
    .select("role")
    .eq("workspace_id", workspaceId)
    .eq("user_id", user.id)
    .maybeSingle();

  if (!callerMember || !["owner", "admin"].includes(callerMember.role)) {
    return { success: false, error: "Only owners and admins can change member status." };
  }

  try {
    const { data: targetUser } = await adminClient.auth.admin.getUserById(targetUserId);
    if (targetUser?.user) {
      await adminClient.auth.admin.updateUserById(targetUserId, {
        user_metadata: {
          ...targetUser.user.user_metadata,
          employment_status: employmentStatus,
        },
      });
    }
  } catch (err) {
    console.error("Error updating member status:", err);
    return { success: false, error: "Failed to update member status." };
  }

  try {
    revalidatePath("/app/people");
    revalidatePath(`/app/people/${targetUserId}`);
  } catch {}

  return { success: true };
}

/**
 * Invite a person to the workspace with full employee metadata
 */
export async function invitePersonAction(
  input: InvitePersonInput
): Promise<PeopleActionResult> {
  const {
    workspaceId,
    email,
    fullName,
    phone,
    jobTitle,
    departmentId,
    employmentType = "Full-time",
    employmentStatus = "Active",
    startDate,
    role = "member",
  } = input;

  const authClient = await createClient();
  const {
    data: { user },
    error: authError,
  } = await authClient.auth.getUser();

  if (authError || !user) {
    return { success: false, error: "You must be logged in to invite team members." };
  }

  const trimmedEmail = email?.trim().toLowerCase();
  if (!trimmedEmail || !trimmedEmail.includes("@")) {
    return { success: false, error: "Please provide a valid email address." };
  }

  const trimmedName = fullName?.trim();
  if (!trimmedName) {
    return { success: false, error: "Please provide the employee's full name." };
  }

  const adminClient = createAdminClient();

  // 1. Verify caller permissions
  const { data: callerMember } = await adminClient
    .from("workspace_members")
    .select("role")
    .eq("workspace_id", workspaceId)
    .eq("user_id", user.id)
    .maybeSingle();

  if (!callerMember || !["owner", "admin"].includes(callerMember.role)) {
    return {
      success: false,
      error: "Only workspace owners and admins can invite new employees.",
    };
  }

  // Delegate directly to the centralized employee invitation workflow to generate invitation record and send email
  const { inviteEmployeeAction } = await import("@/lib/invitations/actions");
  const inviteResult = await inviteEmployeeAction({
    workspaceId,
    email: trimmedEmail,
    fullName: trimmedName,
    role,
    jobTitle: jobTitle?.trim() || undefined,
    departmentId: departmentId || undefined,
    employmentType,
  });

  if (!inviteResult.success && inviteResult.error) {
    return { success: false, error: inviteResult.error };
  }

  try {
    revalidatePath("/app/people");
    revalidatePath("/app/team");
  } catch {}

  return {
    success: true,
    data: inviteResult.data,
  };
}

