/**
 * Submit employee onboarding application with profile, photo, CV, and password
 */
export async function submitEmployeeOnboardingAction(input: {
  workspaceId: string;
  token: string;
  fullName: string;
  phone?: string;
  address?: string;
  bio?: string;
  avatarUrl?: string;
  cvUrl?: string;
  cvFileName?: string;
  password?: string;
}): Promise<PeopleActionResult> {
  const { workspaceId, token, fullName, phone, address, bio, avatarUrl, cvUrl, cvFileName, password } = input;

  const { getInvitationByToken } = await import("@/lib/invitations/queries");
  const { invitation, error: invError } = await getInvitationByToken(token);

  if (invError || !invitation) {
    return { success: false, error: invError || "Invalid or expired invitation token." };
  }

  const email = invitation.email.toLowerCase().trim();
  const adminClient = createAdminClient();

  // 1. Find or create auth user
  const { data: usersList } = await adminClient.auth.admin.listUsers();
  let authUser = usersList?.users?.find((u) => u.email?.toLowerCase() === email);

  if (!authUser) {
    const { data: newUser, error: createError } = await adminClient.auth.admin.createUser({
      email,
      password: password || "RopimoWelcome2026!",
      email_confirm: true,
      user_metadata: {
        full_name: fullName,
        phone: phone || null,
        address: address || null,
        bio: bio || null,
        avatar_url: avatarUrl || null,
        cv_url: cvUrl || null,
        cv_file_name: cvFileName || null,
        employment_type: invitation.employment_type || "Full-time",
        employment_status: "Active",
      },
    });

    if (createError || !newUser.user) {
      return { success: false, error: createError?.message || "Failed to create user account." };
    }
    authUser = newUser.user;
  } else {
    // Update metadata & password
    await adminClient.auth.admin.updateUserById(authUser.id, {
      password: password || undefined,
      email_confirm: true,
      user_metadata: {
        ...authUser.user_metadata,
        full_name: fullName,
        phone: phone || authUser.user_metadata?.phone || null,
        address: address || authUser.user_metadata?.address || null,
        bio: bio || authUser.user_metadata?.bio || null,
        avatar_url: avatarUrl || authUser.user_metadata?.avatar_url || null,
        cv_url: cvUrl || authUser.user_metadata?.cv_url || null,
        cv_file_name: cvFileName || authUser.user_metadata?.cv_file_name || null,
        employment_status: "Active",
      },
    });
  }

  const { recruitmentStore } = await import("@/lib/recruitment/store");
  const employeeId = recruitmentStore.getNextEmployeeId(workspaceId);

  // 2. Add member directly to workspace_members table in Database
  await adminClient.from("workspace_members").upsert(
    {
      workspace_id: workspaceId,
      user_id: authUser.id,
      role: invitation.role || "member",
      full_name: fullName?.trim() || (authUser.user_metadata?.full_name as string) || authUser.email?.split("@")[0] || "Team Member",
      job_title: invitation.job_title || null,
      avatar_url: avatarUrl || null,
      phone: phone || null,
      location: address || null,
      bio: bio || null,
      employee_id: employeeId || null,
      employment_type: invitation.employment_type || "Full-time",
      employment_status: "Active",
      hire_date: new Date().toISOString().split("T")[0],
    },
    { onConflict: "workspace_id,user_id" }
  );

  // 3. Add to department_members if department was assigned
  if (invitation.department_id) {
    try {
      await adminClient.from("department_members").upsert(
        {
          workspace_id: workspaceId,
          department_id: invitation.department_id,
          user_id: authUser.id,
          job_title: invitation.job_title || null,
          role: invitation.role || "member",
        },
        { onConflict: "department_id,user_id" }
      );
    } catch (deptErr) {
      console.warn("Department member assignment warning:", deptErr);
    }
  }

  // 4. Mark invitation as accepted in database
  try {
    if (invitation.id) {
      await adminClient
        .from("workspace_invitations")
        .update({
          status: "accepted",
          accepted_at: new Date().toISOString(),
        })
        .eq("id", invitation.id);
    }
    if (token) {
      await adminClient
        .from("workspace_invitations")
        .update({
          status: "accepted",
          accepted_at: new Date().toISOString(),
        })
        .eq("token", token);
    }
    if (email) {
      await adminClient
        .from("workspace_invitations")
        .update({
          status: "accepted",
          accepted_at: new Date().toISOString(),
        })
        .eq("email", email);
    }
  } catch {}

  const updatedInv = {
    ...invitation,
    status: "Accepted" as any,
    accepted_at: new Date().toISOString(),
  };
  (recruitmentStore as any).saveInvitation?.(updatedInv);

  // 5. Complete recruitment onboarding record
  const completedChecklist = [
    {
      id: `chk-1-${authUser.id}`,
      title: "Accept Workspace Invitation",
      description: "Invitation confirmed and account profile created.",
      category: "profile",
      required: true,
      status: "completed",
      completed_at: new Date().toISOString(),
    },
    {
      id: `chk-2-${authUser.id}`,
      title: "Complete Profile & Contact Information",
      description: `Phone: ${phone || "Provided"}, Address: ${address || "Provided"}`,
      category: "profile",
      required: true,
      status: "completed",
      completed_at: new Date().toISOString(),
    },
    {
      id: `chk-3-${authUser.id}`,
      title: "Upload Profile Photo",
      description: avatarUrl ? "Profile photo uploaded." : "Default avatar used.",
      category: "profile",
      required: false,
      status: avatarUrl ? "completed" : "pending",
      completed_at: avatarUrl ? new Date().toISOString() : undefined,
    },
    {
      id: `chk-4-${authUser.id}`,
      title: "Upload Resume / CV Document",
      description: cvFileName ? `Uploaded file: ${cvFileName}` : "Profile setup complete.",
      category: "documents",
      required: false,
      status: cvUrl ? "completed" : "pending",
      completed_at: cvUrl ? new Date().toISOString() : undefined,
    },
  ];

  const onboardingObj = {
    id: `onb-${authUser.id}`,
    workspace_id: workspaceId,
    user_id: authUser.id,
    employee_id: employeeId,
    status: "Completed" as const,
    progress_percentage: 100,
    checklist: completedChecklist as any,
    started_at: new Date().toISOString(),
    completed_at: new Date().toISOString(),
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };

  recruitmentStore.saveOnboarding(onboardingObj);

  // 6. Notify workspace owner / inviter
  try {
    const { notificationStore } = await import("@/lib/notifications/store");
    notificationStore.addNotification({
      workspace_id: workspaceId,
      user_id: invitation.invited_by || "admin",
      type: "invitation_accepted",
      title: "New Team Member Joined!",
      subtitle: `${fullName} (${email}) has completed onboarding and joined the workspace.`,
      action_url: `/app/people/${authUser.id}`,
      entity_type: "invitation",
      entity_id: invitation.id,
    });
  } catch {}

  // 7. Auto-sign-in the newly registered user so they can immediately access /app
  try {
    if (password) {
      const userClient = await createClient();
      await userClient.auth.signInWithPassword({
        email,
        password,
      });
    }
  } catch (authErr) {
    console.warn("[Onboarding Auto-login notice]", authErr);
  }

  // 8. Send Welcome Email via Resend
  try {
    const { sendWelcomeEmail } = await import("@/lib/email/resend");
    const { data: ws } = await adminClient
      .from("workspaces")
      .select("name")
      .eq("id", workspaceId)
      .maybeSingle();

    await sendWelcomeEmail({
      workspaceName: ws?.name || "Ropimo Workspace",
      recipientEmail: email,
      recipientName: fullName,
      dashboardUrl: `${getAppUrl()}/app`,
    });
  } catch {}

  try {
    revalidatePath("/app/people");
    revalidatePath("/app/team");
    revalidatePath("/app");
  } catch {}

  return {
    success: true,
    data: {
      directAccess: true,
      role: invitation.role || "member",
      employeeId,
      userId: authUser.id,
    },
  };
}

/**
 * Approve employee onboarding and activate their workspace access
 */
export async function approveEmployeeOnboardingAction(input: {
  workspaceId: string;
  userId: string;
  departmentId?: string;
  role?: WorkspaceRole;
  jobTitle?: string;
}): Promise<PeopleActionResult> {
  const { workspaceId, userId, departmentId, role = "member", jobTitle } = input;

  const authClient = await createClient();
  const {
    data: { user },
    error: authError,
  } = await authClient.auth.getUser();

  if (authError || !user) {
    return { success: false, error: "You must be logged in." };
  }

  const adminClient = createAdminClient();

  // 1. Verify caller is owner/admin
  const { data: callerMember } = await adminClient
    .from("workspace_members")
    .select("role")
    .eq("workspace_id", workspaceId)
    .eq("user_id", user.id)
    .maybeSingle();

  if (!callerMember || !["owner", "admin"].includes(callerMember.role)) {
    return { success: false, error: "Only owners and admins can approve employee onboardings." };
  }

  // 2. Activate member in workspace_members
  await adminClient.from("workspace_members").upsert(
    {
      workspace_id: workspaceId,
      user_id: userId,
      role,
      job_title: jobTitle?.trim() || null,
    },
    { onConflict: "workspace_id,user_id" }
  );

  // 3. Assign Department if provided
  if (departmentId) {
    await adminClient.from("department_members").upsert(
      {
        workspace_id: workspaceId,
        department_id: departmentId,
        user_id: userId,
        job_title: jobTitle?.trim() || null,
      },
      { onConflict: "department_id,user_id" }
    );
  }

  // 4. Update auth metadata to Active
  try {
    const { data: targetUser } = await adminClient.auth.admin.getUserById(userId);
    if (targetUser?.user) {
      await adminClient.auth.admin.updateUserById(userId, {
        user_metadata: {
          ...targetUser.user.user_metadata,
          employment_status: "Active",
          job_title: jobTitle?.trim() || targetUser.user.user_metadata?.job_title || null,
        },
      });
    }
  } catch {}

  // 5. Update Onboarding status in store to Completed
  const { recruitmentStore } = await import("@/lib/recruitment/store");
  const onboarding = recruitmentStore.getOnboardingByUserId(userId, workspaceId);
  if (onboarding) {
    onboarding.status = "Completed";
    onboarding.progress_percentage = 100;
    onboarding.completed_at = new Date().toISOString();
    onboarding.checklist = (onboarding.checklist || []).map((c) => ({
      ...c,
      status: "completed",
      completed_at: c.completed_at || new Date().toISOString(),
    }));
    recruitmentStore.saveOnboarding(onboarding);
  }

  // 6. Update invitations table
  try {
    await adminClient
      .from("workspace_invitations")
      .update({ status: "accepted", accepted_at: new Date().toISOString() })
      .eq("workspace_id", workspaceId)
      .eq("user_id", userId);
  } catch {}

  // 7. Dispatch welcome notification
  try {
    const { notificationStore } = await import("@/lib/notifications/store");
    notificationStore.addNotification({
      workspace_id: workspaceId,
      user_id: userId,
      type: "system",
      title: "Onboarding Approved! 🎉",
      subtitle: "Your onboarding application has been approved. Welcome to the team!",
      action_url: "/app",
      entity_type: "system",
    });
  } catch {}

  try {
    revalidatePath("/app/people");
    revalidatePath("/app/team");
    revalidatePath(`/app/people/onboarding/${userId}`);
    if (departmentId) revalidatePath(`/app/departments/${departmentId}`);
  } catch {}

  return { success: true };
}

/**
 * Reject employee onboarding application
 */
export async function rejectEmployeeOnboardingAction(input: {
  workspaceId: string;
  userId: string;
  reason?: string;
}): Promise<PeopleActionResult> {
  const { workspaceId, userId } = input;

  const authClient = await createClient();
  const { data: { user } } = await authClient.auth.getUser();
  if (!user) return { success: false, error: "Unauthorized." };

  const { recruitmentStore } = await import("@/lib/recruitment/store");
  const onboarding = recruitmentStore.getOnboardingByUserId(userId, workspaceId);
  if (onboarding) {
    onboarding.status = "Documents Pending";
    recruitmentStore.saveOnboarding(onboarding);
  }

  try {
    revalidatePath("/app/people");
    revalidatePath(`/app/people/onboarding/${userId}`);
  } catch {}

  return { success: true };
}

import { cache } from "react";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import {
  WorkspacePerson,
  DepartmentMember,
  PersonDepartmentRef,
  EmploymentType,
  EmploymentStatus,
} from "@/types/people";

import { recruitmentStore } from "@/lib/recruitment/store";
import { EmployeeOnboarding, OnboardingStatus } from "@/types/people";

/**
 * Fetch all people in a workspace, including their assigned departments and job titles (deduplicated per request)
 */
export const getWorkspacePeople = cache(
  async (workspaceId: string): Promise<WorkspacePerson[]> => {
    if (!workspaceId) return [];

    let isAuthed = true;
    try {
      const supabase = await createClient();
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) isAuthed = false;
    } catch {
      // CLI / background script context
    }

    if (!isAuthed) return [];

    const adminClient = createAdminClient();

    // 1. Fetch workspace members
    const { data: members } = await adminClient
      .from("workspace_members")
      .select("*")
      .eq("workspace_id", workspaceId)
      .order("created_at", { ascending: true });

    // 2. Fetch department memberships
    const { data: deptMemberships } = await adminClient
      .from("department_members")
      .select(`
        department_id,
        user_id,
        job_title,
        departments:department_id (
          id,
          name,
          icon,
          color
        )
      `)
      .eq("workspace_id", workspaceId);

    interface DeptMembershipRow {
      department_id: string;
      user_id: string;
      job_title: string | null;
      departments: {
        id: string;
        name: string;
        icon: string;
        color: string;
      } | null;
    }

    const userDeptsMap = new Map<string, PersonDepartmentRef[]>();
    ((deptMemberships as unknown as DeptMembershipRow[]) || []).forEach((dm) => {
      if (dm.departments) {
        const list = userDeptsMap.get(dm.user_id) || [];
        list.push({
          id: dm.departments.id,
          name: dm.departments.name,
          icon: dm.departments.icon,
          color: dm.departments.color,
          job_title: dm.job_title,
        });
        userDeptsMap.set(dm.user_id, list);
      }
    });

    const userIds = (members || []).map((m) => m.user_id);
    const userProfilesMap = new Map<
      string,
      {
        email: string;
        fullName: string | null;
        avatarUrl: string | null;
        phone: string | null;
        location: string | null;
        jobTitle: string | null;
        employeeId: string | null;
        employmentType: string | null;
        employmentStatus: string | null;
        bio: string | null;
        skills: string[];
      }
    >();

    try {
      const userResults = await Promise.all(
        userIds.map((id) => adminClient.auth.admin.getUserById(id))
      );
      userResults.forEach((res) => {
        const u = res.data?.user;
        if (u) {
          const meta = u.user_metadata || {};
          userProfilesMap.set(u.id, {
            email: u.email || "",
            fullName: meta.full_name || meta.name || null,
            avatarUrl: meta.avatar_url || null,
            phone: meta.phone || null,
            location: meta.location || null,
            jobTitle: meta.job_title || null,
            employeeId: meta.employee_id || null,
            employmentType: meta.employment_type || null,
            employmentStatus: meta.employment_status || null,
            bio: meta.bio || null,
            skills: Array.isArray(meta.skills) ? meta.skills : [],
          });
        }
      });
    } catch {
      // Ignored
    }

    // 3. Candidate and Onboarding cross-referencing
    const candidates = recruitmentStore.getCandidates(workspaceId);
    const candidateByUserMap = new Map<string, (typeof candidates)[0]>();
    candidates.forEach((c) => {
      if (c.converted_user_id) candidateByUserMap.set(c.converted_user_id, c);
    });

    const onboardings = recruitmentStore.getOnboardings(workspaceId);
    const onboardingByUserMap = new Map<string, EmployeeOnboarding>();
    onboardings.forEach((o) => {
      onboardingByUserMap.set(o.user_id, o);
    });

    const dbPeople: WorkspacePerson[] = (members || []).map((m) => {
      const profile = userProfilesMap.get(m.user_id);
      const email = profile?.email || m.email || "team@ropimo.com";
      const full_name = m.full_name || profile?.fullName || email.split("@")[0] || "Team Member";
      const departments = userDeptsMap.get(m.user_id) || [];
      const linkedCandidate = candidateByUserMap.get(m.user_id);
      const linkedOnboarding = onboardingByUserMap.get(m.user_id);

      const employeeId =
        linkedCandidate?.employee_id ||
        linkedOnboarding?.employee_id ||
        profile?.employeeId ||
        null;

      // Derive employment status: prioritize explicit workspace_member status, then candidate/profile
      let rawStatus: string = (m.employment_status as string) || (profile?.employmentStatus as string) || (linkedCandidate?.employment_status as string) || "Active";
      let employmentStatus: EmploymentStatus = "Active";
      const s = rawStatus.toLowerCase();
      if (s === "active") {
        employmentStatus = "Active";
      } else if (s === "pending" || s === "invited") {
        employmentStatus = "Pending";
      } else if (s.includes("leave")) {
        employmentStatus = "On Leave";
      } else if (s.includes("probation")) {
        employmentStatus = "Probation";
      } else if (s === "inactive" || s === "terminated") {
        employmentStatus = "Inactive";
      } else {
        // Any other state (like "pending approval" for a joined workspace member) is Active
        employmentStatus = "Active";
      }

      const onboardingStatus =
        (linkedOnboarding?.status as OnboardingStatus | undefined) ||
        (linkedCandidate?.onboarding_status as OnboardingStatus | undefined) ||
        "Completed";

      return {
        id: m.id,
        user_id: m.user_id,
        workspace_id: m.workspace_id,
        role: m.role || "member",
        job_title: m.job_title || profile?.jobTitle || linkedCandidate?.hired_job_title || null,
        full_name,
        email,
        avatar_url: m.avatar_url || profile?.avatarUrl || null,
        phone: profile?.phone || linkedCandidate?.phone || null,
        location: profile?.location || linkedCandidate?.location || null,
        employee_id: employeeId,
        employment_type: (profile?.employmentType as EmploymentType | undefined) ?? "Full-time",
        employment_status: employmentStatus,
        onboarding_status: onboardingStatus,
        candidate_id: linkedCandidate?.id || linkedOnboarding?.candidate_id || null,
        candidate_application_id: linkedCandidate?.latest_application_id || linkedOnboarding?.application_id || null,
        hire_date: linkedCandidate?.hired_start_date || m.created_at,
        bio: profile?.bio || linkedCandidate?.bio || null,
        skills: profile?.skills || linkedCandidate?.skills || [],
        departments,
        created_at: m.created_at,
      };
    });

    return dbPeople;
  }
);

/**
 * Fetch all members belonging to a specific department
 */
export async function getDepartmentMembers(
  departmentId: string,
  workspaceId: string
): Promise<DepartmentMember[]> {
  if (!departmentId || !workspaceId) return [];

  const adminClient = createAdminClient();

  const { data: dmRows } = await adminClient
    .from("department_members")
    .select("*")
    .eq("department_id", departmentId)
    .eq("workspace_id", workspaceId)
    .order("created_at", { ascending: true });

  if (!dmRows || dmRows.length === 0) {
    return [];
  }

  const allPeople = await getWorkspacePeople(workspaceId);
  const peopleMap = new Map(allPeople.map((p) => [p.user_id, p]));

  const departmentMembers: DepartmentMember[] = [];

  for (const row of dmRows) {
    const person = peopleMap.get(row.user_id);
    if (person) {
      departmentMembers.push({
        id: row.id,
        department_id: row.department_id,
        user_id: row.user_id,
        workspace_id: row.workspace_id,
        job_title: row.job_title || person.job_title,
        role: row.role || person.role,
        created_at: row.created_at,
        person,
      });
    }
  }

  return departmentMembers;
}

/**
 * Fetch a single person by user_id and workspace_id
 */
export async function getWorkspacePersonById(
  personId: string,
  workspaceId: string
): Promise<WorkspacePerson | null> {
  if (!personId || !workspaceId) return null;

  const people = await getWorkspacePeople(workspaceId);
  const person = people.find(
    (p) =>
      p.id === personId ||
      p.user_id === personId ||
      p.email.toLowerCase() === personId.toLowerCase() ||
      p.full_name?.toLowerCase().replace(/\s+/g, "-") === personId.toLowerCase()
  );

  if (person) return person;

  // Fallback: check workspace invitations for pending teammates
  const { getWorkspaceInvitations } = await import("@/lib/invitations/queries");
  const invitations = await getWorkspaceInvitations(workspaceId);
  const inv = invitations.find(
    (i) =>
      i.id === personId ||
      i.user_id === personId ||
      i.employee_id === personId ||
      i.token === personId ||
      i.email.toLowerCase() === personId.toLowerCase()
  );

  if (inv) {
    const targetDept = inv.department_id ? { id: inv.department_id, name: "Department", icon: "departments", color: "blue", job_title: inv.job_title || undefined } : null;
    return {
      id: inv.id,
      workspace_id: workspaceId,
      user_id: inv.user_id || inv.id,
      email: inv.email,
      full_name: inv.full_name || inv.email.split("@")[0],
      avatar_url: null,
      role: inv.role,
      departments: targetDept ? [targetDept] : [],
      job_title: inv.job_title || "Team Member",
      employee_id: inv.employee_id || "EMP-INV",
      employment_type: inv.employment_type || "Full-time",
      employment_status: "Pending",
      created_at: inv.created_at,
    };
  }

  return null;
}

export interface MemberProjectSummary {
  id: string;
  name: string;
  role: string;
  status: string;
  progress: number;
  completedTasks: number;
  totalTasks: number;
}

export interface MemberActivitySummary {
  id: string;
  action: string;
  target: string;
  timeAgo: string;
  createdAt: string;
}

/**
 * Fetch real task activities for a specific team member
 */
export async function getMemberActivities(
  userId: string,
  workspaceId: string
): Promise<MemberActivitySummary[]> {
  if (!userId || !workspaceId) return [];

  const adminClient = createAdminClient();

  const { data: rows } = await adminClient
    .from("task_activities")
    .select("id, action_type, created_at, task_id, tasks:task_id(title)")
    .eq("workspace_id", workspaceId)
    .eq("user_id", userId)
    .order("created_at", { ascending: false })
    .limit(20);

  if (!rows || rows.length === 0) return [];

  return rows.map((r) => {
    const createdTime = new Date(r.created_at);
    const diffMin = Math.round((Date.now() - createdTime.getTime()) / 60000);
    const timeAgo =
      diffMin < 1
        ? "Just now"
        : diffMin < 60
        ? `${diffMin}m ago`
        : diffMin < 1440
        ? `${Math.round(diffMin / 60)}h ago`
        : `${Math.round(diffMin / 1440)}d ago`;

    const task = r.tasks as unknown as { title?: string } | null;
    const actionLabel = (r.action_type || "updated").replace(/_/g, " ");

    return {
      id: r.id,
      action: actionLabel,
      target: task?.title ? `"${task.title}"` : "Task",
      timeAgo,
      createdAt: r.created_at,
    };
  });
}

/**
 * Fetch real projects associated with a team member
 */
export async function getMemberProjects(
  userId: string,
  workspaceId: string
): Promise<MemberProjectSummary[]> {
  if (!userId || !workspaceId) return [];

  const adminClient = createAdminClient();

  const [{ data: allProjects }, { data: userTasks }, { data: allTasks }] = await Promise.all([
    adminClient
      .from("projects")
      .select("id, name, status, created_by")
      .eq("workspace_id", workspaceId),
    adminClient
      .from("tasks")
      .select("project_id")
      .eq("workspace_id", workspaceId)
      .eq("created_by", userId)
      .not("project_id", "is", null),
    adminClient
      .from("tasks")
      .select("id, project_id, status")
      .eq("workspace_id", workspaceId)
      .not("project_id", "is", null),
  ]);

  if (!allProjects || allProjects.length === 0) return [];

  const userProjectIds = new Set<string>();
  allProjects.forEach((p) => {
    if (p.created_by === userId) userProjectIds.add(p.id);
  });
  (userTasks || []).forEach((t) => {
    if (t.project_id) userProjectIds.add(t.project_id);
  });

  const projectTasksMap = new Map<string, { total: number; completed: number }>();
  (allTasks || []).forEach((t) => {
    if (!t.project_id) return;
    const curr = projectTasksMap.get(t.project_id) || { total: 0, completed: 0 };
    curr.total += 1;
    if (t.status === "completed") curr.completed += 1;
    projectTasksMap.set(t.project_id, curr);
  });

  return allProjects
    .filter((p) => userProjectIds.has(p.id))
    .map((p) => {
      const counts = projectTasksMap.get(p.id) || { total: 0, completed: 0 };
      const progress = counts.total > 0 ? Math.round((counts.completed / counts.total) * 100) : 0;
      const isLead = p.created_by === userId;

      return {
        id: p.id,
        name: p.name,
        role: isLead ? "Project Lead" : "Contributor",
        status: p.status === "active" ? "Active" : p.status || "Active",
        progress,
        completedTasks: counts.completed,
        totalTasks: counts.total,
      };
    });
}

/**
 * Efficiently batch-fetch activities and project summaries for all workspace members in 3 optimized queries
 */
export async function getWorkspaceMemberProjectsAndActivitiesMaps(workspaceId: string): Promise<{
  memberActivitiesMap: Record<string, MemberActivitySummary[]>;
  memberProjectsMap: Record<string, MemberProjectSummary[]>;
}> {
  if (!workspaceId) {
    return { memberActivitiesMap: {}, memberProjectsMap: {} };
  }

  const adminClient = createAdminClient();

  const [
    { data: activitiesRows },
    { data: allProjects },
    { data: allTasks },
  ] = await Promise.all([
    adminClient
      .from("task_activities")
      .select("id, user_id, action_type, created_at, task_id, tasks:task_id(title)")
      .eq("workspace_id", workspaceId)
      .order("created_at", { ascending: false })
      .limit(200),
    adminClient
      .from("projects")
      .select("id, name, status, created_by")
      .eq("workspace_id", workspaceId),
    adminClient
      .from("tasks")
      .select("id, project_id, status, created_by")
      .eq("workspace_id", workspaceId)
      .not("project_id", "is", null),
  ]);

  // Build activities map
  const memberActivitiesMap: Record<string, MemberActivitySummary[]> = {};
  (activitiesRows || []).forEach((r) => {
    if (!r.user_id) return;
    if (!memberActivitiesMap[r.user_id]) {
      memberActivitiesMap[r.user_id] = [];
    }
    if (memberActivitiesMap[r.user_id].length < 20) {
      const createdTime = new Date(r.created_at);
      const diffMin = Math.round((Date.now() - createdTime.getTime()) / 60000);
      const timeAgo =
        diffMin < 1
          ? "Just now"
          : diffMin < 60
          ? `${diffMin}m ago`
          : diffMin < 1440
          ? `${Math.round(diffMin / 60)}h ago`
          : `${Math.round(diffMin / 1440)}d ago`;

      const task = r.tasks as unknown as { title?: string } | null;
      const actionLabel = (r.action_type || "updated").replace(/_/g, " ");

      memberActivitiesMap[r.user_id].push({
        id: r.id,
        action: actionLabel,
        target: task?.title ? `"${task.title}"` : "Task",
        timeAgo,
        createdAt: r.created_at,
      });
    }
  });

  // Build projects map
  const projectTasksMap = new Map<string, { total: number; completed: number }>();
  const userProjectsSetMap = new Map<string, Set<string>>();

  (allProjects || []).forEach((p) => {
    if (p.created_by) {
      const set = userProjectsSetMap.get(p.created_by) || new Set();
      set.add(p.id);
      userProjectsSetMap.set(p.created_by, set);
    }
  });

  (allTasks || []).forEach((t) => {
    if (!t.project_id) return;
    const curr = projectTasksMap.get(t.project_id) || { total: 0, completed: 0 };
    curr.total += 1;
    if (t.status === "completed") curr.completed += 1;
    projectTasksMap.set(t.project_id, curr);

    if (t.created_by) {
      const set = userProjectsSetMap.get(t.created_by) || new Set();
      set.add(t.project_id);
      userProjectsSetMap.set(t.created_by, set);
    }
  });

  const memberProjectsMap: Record<string, MemberProjectSummary[]> = {};
  userProjectsSetMap.forEach((pIds, uId) => {
    memberProjectsMap[uId] = (allProjects || [])
      .filter((p) => pIds.has(p.id))
      .map((p) => {
        const counts = projectTasksMap.get(p.id) || { total: 0, completed: 0 };
        const progress = counts.total > 0 ? Math.round((counts.completed / counts.total) * 100) : 0;
        const isLead = p.created_by === uId;
        return {
          id: p.id,
          name: p.name,
          role: isLead ? "Project Lead" : "Contributor",
          status: p.status === "active" ? "Active" : p.status || "Active",
          progress,
          completedTasks: counts.completed,
          totalTasks: counts.total,
        };
      });
  });

  return { memberActivitiesMap, memberProjectsMap };
}

/**
 * Fetch employee onboarding record by employee/user ID
 */
export async function getEmployeeOnboarding(
  userIdOrEmpId: string,
  workspaceId: string
): Promise<EmployeeOnboarding | null> {
  if (!userIdOrEmpId || !workspaceId) return null;

  const person = await getWorkspacePersonById(userIdOrEmpId, workspaceId);
  const realUserId = person ? person.user_id : userIdOrEmpId;
  const onboarding = recruitmentStore.getOnboardingByUserId(realUserId, workspaceId);

  if (!onboarding) {
    if (person) {
      const isPending = person.employment_status === "Pending";
      const defaultChecklist = [
        {
          id: `chk-1-${person.user_id}`,
          title: "Accept Workspace Invitation",
          description: "Invitation confirmed and account activated.",
          category: "profile",
          required: true,
          status: isPending ? "pending" : "completed",
          completed_at: isPending ? undefined : person.created_at,
        },
        {
          id: `chk-2-${person.user_id}`,
          title: "Complete Profile & Contact Information",
          description: "Verify phone number, emergency contacts, and personal details.",
          category: "profile",
          required: true,
          status: "pending",
        },
        {
          id: `chk-3-${person.user_id}`,
          title: "Upload Profile Photo",
          description: "Add team directory avatar for workspace visibility.",
          category: "profile",
          required: false,
          status: "pending",
        },
        {
          id: `chk-4-${person.user_id}`,
          title: "Verify Employment Details & Role",
          description: `Confirm job title (${person.job_title || "Team Member"}) and employment tier.`,
          category: "employment",
          required: true,
          status: isPending ? "pending" : "completed",
        },
        {
          id: `chk-5-${person.user_id}`,
          title: "Sign Offer Letter & NDA",
          description: "Review and e-sign standard employment agreements.",
          category: "documents",
          required: true,
          status: isPending ? "pending" : "completed",
        },
        {
          id: `chk-6-${person.user_id}`,
          title: "Workspace & Department Access Setup",
          description: "Configure role permissions and department task boards.",
          category: "workspace",
          required: true,
          status: isPending ? "pending" : "completed",
        },
        {
          id: `chk-7-${person.user_id}`,
          title: "First Day Team Intro & Orientation",
          description: "Complete intro meeting with workspace administrator.",
          category: "profile",
          required: false,
          status: "pending",
        },
      ];

      const completedCount = defaultChecklist.filter((c) => c.status === "completed").length;
      const progress = Math.round((completedCount / defaultChecklist.length) * 100);

      return {
        id: `onb-${person.user_id}`,
        workspace_id: workspaceId,
        user_id: person.user_id,
        employee_id: person.employee_id || "EMP-001",
        status: isPending ? "In Progress" : "Completed",
        progress_percentage: progress,
        checklist: defaultChecklist as any,
        started_at: person.created_at,
        completed_at: isPending ? null : person.created_at,
        created_at: person.created_at,
        updated_at: person.created_at,
        person,
      };
    }
    return null;
  }

  return {
    ...onboarding,
    person: person || undefined,
  };
}

/**
 * Fetch recruitment history and candidate record for an employee
 */
export async function getEmployeeRecruitmentHistory(
  userIdOrEmpId: string,
  workspaceId: string
) {
  if (!userIdOrEmpId || !workspaceId) return null;

  const people = await getWorkspacePeople(workspaceId);
  const person = people.find(
    (p) =>
      p.id === userIdOrEmpId ||
      p.user_id === userIdOrEmpId ||
      p.employee_id?.toLowerCase() === userIdOrEmpId.toLowerCase()
  );

  const realUserId = person ? person.user_id : userIdOrEmpId;
  const candidates = recruitmentStore.getCandidates(workspaceId);
  const candidate = candidates.find(
    (c) =>
      c.converted_user_id === realUserId ||
      (person?.email && c.email.toLowerCase() === person.email.toLowerCase())
  );

  if (!candidate) return null;

  const applications = recruitmentStore.getCandidateApplications(candidate.id, workspaceId);
  const interviews = recruitmentStore.getInterviews(workspaceId).filter((i) => i.candidate_id === candidate.id);
  const offers = recruitmentStore.getOffers(workspaceId).filter((o) => o.candidate_id === candidate.id);
  const activities = recruitmentStore.getActivities(candidate.id, workspaceId);

  return {
    candidate,
    applications,
    interviews,
    offers,
    activities,
  };
}

"use server";

import { requireUser } from "@/lib/auth/require-user";
import { createAdminClient } from "@/lib/supabase/admin";
import { createClient } from "@/lib/supabase/server";
import { revalidatePath } from "next/cache";

export interface ProfileActionResult {
  success: boolean;
  error?: string;
  data?: any;
}

/**
 * Update user's display name across profiles and auth metadata
 */
export async function updateProfileNameAction(params: {
  fullName: string;
}): Promise<ProfileActionResult> {
  try {
    const user = await requireUser();
    const trimmedName = params.fullName?.trim();

    if (!trimmedName || trimmedName.length < 2) {
      return { success: false, error: "Full name must be at least 2 characters." };
    }
    if (trimmedName.length > 100) {
      return { success: false, error: "Full name cannot exceed 100 characters." };
    }

    const adminClient = createAdminClient();

    // 1. Update public.profiles
    const { error: profileError } = await adminClient
      .from("profiles")
      .update({
        full_name: trimmedName,
        updated_at: new Date().toISOString(),
      })
      .eq("id", user.id);

    if (profileError) {
      return { success: false, error: profileError.message || "Failed to update profile." };
    }

    // 2. Update auth.users metadata
    try {
      await adminClient.auth.admin.updateUserById(user.id, {
        user_metadata: {
          ...user.user_metadata,
          full_name: trimmedName,
        },
      });
    } catch (authErr) {
      console.warn("Auth metadata update note:", authErr);
    }

    // 3. Update public.workspace_members full_name for consistency
    try {
      await adminClient
        .from("workspace_members")
        .update({ full_name: trimmedName })
        .eq("user_id", user.id);
    } catch {}

    revalidatePath("/app/profile");
    revalidatePath("/app");

    return { success: true, data: { fullName: trimmedName } };
  } catch (err: any) {
    return { success: false, error: err.message || "Failed to update profile name." };
  }
}

/**
 * Update user's avatar URL across profiles and auth metadata
 */
export async function updateProfileAvatarAction(params: {
  avatarUrl: string;
}): Promise<ProfileActionResult> {
  try {
    const user = await requireUser();
    const avatarUrl = params.avatarUrl?.trim();

    if (!avatarUrl) {
      return { success: false, error: "Avatar URL is required." };
    }

    const adminClient = createAdminClient();

    // 1. Update public.profiles
    const { error: profileError } = await adminClient
      .from("profiles")
      .update({
        avatar_url: avatarUrl,
        updated_at: new Date().toISOString(),
      })
      .eq("id", user.id);

    if (profileError) {
      return { success: false, error: profileError.message || "Failed to update avatar in profile." };
    }

    // 2. Update auth metadata
    try {
      await adminClient.auth.admin.updateUserById(user.id, {
        user_metadata: {
          ...user.user_metadata,
          avatar_url: avatarUrl,
        },
      });
    } catch {}

    revalidatePath("/app/profile");
    revalidatePath("/app");

    return { success: true, data: { avatarUrl } };
  } catch (err: any) {
    return { success: false, error: err.message || "Failed to update avatar." };
  }
}

/**
 * Change the authenticated user's account password
 */
export async function changePasswordAction(params: {
  newPassword: string;
  confirmPassword?: string;
}): Promise<ProfileActionResult> {
  try {
    await requireUser();

    const { newPassword, confirmPassword } = params;

    if (!newPassword || newPassword.length < 6) {
      return { success: false, error: "Password must be at least 6 characters long." };
    }

    if (confirmPassword !== undefined && newPassword !== confirmPassword) {
      return { success: false, error: "New password and confirmation do not match." };
    }

    const supabase = await createClient();
    const { error } = await supabase.auth.updateUser({
      password: newPassword,
    });

    if (error) {
      return { success: false, error: error.message || "Failed to change password." };
    }

    return { success: true };
  } catch (err: any) {
    return { success: false, error: err.message || "Failed to change password." };
  }
}

"use server";

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { CreateProjectInput, Project, ProjectStatus } from "@/types/project";
import { revalidatePath } from "next/cache";
import { dispatchProjectMemberAddedEvent } from "@/lib/notifications/service";

export interface CreateProjectResult {
  success: boolean;
  project?: Project;
  error?: string;
}

export interface UpdateProjectInput {
  projectId: string;
  workspaceId: string;
  name?: string;
  description?: string;
  status?: ProjectStatus;
  color?: string;
  icon?: string;
}

function generateSlug(name: string): string {
  const base = name
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return base || "project";
}

export async function createProjectAction(
  input: CreateProjectInput
): Promise<CreateProjectResult> {
  const {
    workspaceId,
    departmentId,
    name,
    description,
    status,
    priority,
    color,
    icon,
    leadId,
    startDate,
    dueDate,
  } = input;

  // 1. Verify User Authentication
  const authClient = await createClient();
  const {
    data: { user },
    error: authError,
  } = await authClient.auth.getUser();

  if (authError || !user) {
    return { success: false, error: "You must be logged in to create a project." };
  }

  const trimmedName = name?.trim();
  if (!trimmedName || trimmedName.length < 2) {
    return { success: false, error: "Project name must be at least 2 characters." };
  }

  if (!workspaceId) {
    return { success: false, error: "Workspace ID is required." };
  }

  const adminClient = createAdminClient();

  // 2. Verify user has owner/admin/manager permission in this workspace
  const { data: member, error: memberError } = await adminClient
    .from("workspace_members")
    .select("role")
    .eq("workspace_id", workspaceId)
    .eq("user_id", user.id)
    .maybeSingle();

  if (memberError || !member) {
    return { success: false, error: "You are not a member of this workspace." };
  }

  // 3. Generate unique slug within workspace
  let slug = generateSlug(trimmedName);
  const { data: existingProject } = await adminClient
    .from("projects")
    .select("id")
    .eq("workspace_id", workspaceId)
    .eq("slug", slug)
    .maybeSingle();

  if (existingProject) {
    const randomSuffix = Math.random().toString(36).substring(2, 6);
    slug = `${slug}-${randomSuffix}`;
  }

  const projectIcon = icon || trimmedName[0].toUpperCase();

  let validDepartmentId: string | null = null;
  if (departmentId) {
    const isUUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(departmentId);
    if (isUUID) {
      validDepartmentId = departmentId;
    }
  }

  let validLeadId: string | null = null;
  if (leadId) {
    const isUUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(leadId);
    if (isUUID) {
      validLeadId = leadId;
    }
  }

  // 4. Insert project
  const dbStatus = (status === "in_progress" || !status) ? "active" : status;

  const insertPayload: Record<string, unknown> = {
    workspace_id: workspaceId,
    name: trimmedName,
    slug,
    description: description?.trim() || null,
    status: dbStatus,
    color: color || "#10251F",
    icon: projectIcon,
    created_by: user.id,
  };

  if (validDepartmentId) insertPayload.department_id = validDepartmentId;
  if (validLeadId) insertPayload.lead_id = validLeadId;
  if (priority) insertPayload.priority = priority;
  if (startDate) insertPayload.start_date = startDate;
  if (dueDate) insertPayload.due_date = dueDate;

  let { data: newProject, error: insertError } = await adminClient
    .from("projects")
    .insert(insertPayload)
    .select()
    .single();

  // If column doesn't exist yet (e.g. department_id, lead_id), retry with guaranteed base columns
  if (insertError) {
    console.warn("Retrying project insert with safe base columns:", insertError.message);
    const pureBasePayload: Record<string, unknown> = {
      workspace_id: workspaceId,
      name: trimmedName,
      slug,
      description: description?.trim() || null,
      status: dbStatus,
      color: color || "#10251F",
      icon: projectIcon,
      created_by: user.id,
    };

    const retry = await adminClient
      .from("projects")
      .insert(pureBasePayload)
      .select()
      .single();
    newProject = retry.data;
    insertError = retry.error;
  }

  if (insertError || !newProject) {
    console.error("Project creation error:", insertError);
    return {
      success: false,
      error: insertError?.message || "Failed to create project. Please try again.",
    };
  }

  // Anchor department association via initial task if department_id was specified
  if (validDepartmentId && newProject?.id) {
    try {
      await adminClient.from("tasks").insert({
        workspace_id: workspaceId,
        project_id: newProject.id,
        department_id: validDepartmentId,
        title: "Project Kickoff",
        status: "todo",
        created_by: user.id,
      });
    } catch (taskErr) {
      console.warn("Could not insert anchor task:", taskErr);
    }
  }

  // Insert project members if memberIds provided
  if (input.memberIds && input.memberIds.length > 0 && newProject?.id) {
    try {
      const memberRows = input.memberIds.map((uId) => ({
        project_id: newProject.id,
        workspace_id: workspaceId,
        user_id: uId,
        role: "member",
        added_by: user.id,
      }));
      // Dispatch unified event notifications for project members
      for (const uId of input.memberIds) {
        dispatchProjectMemberAddedEvent({
          workspaceId,
          projectId: newProject.id,
          projectName: trimmedName,
          projectSlug: newProject.slug || newProject.id,
          addedByUserId: user.id,
          memberUserId: uId,
          memberRole: "member",
        }).catch((err) => console.error("[Project Actions] Member event dispatch error:", err));
      }
    } catch (memberErr) {
      console.warn("Could not insert/notify project members:", memberErr);
    }
  }

  revalidatePath("/app");
  revalidatePath("/app/projects");
  revalidatePath("/app/overview");
  if (validDepartmentId) {
    revalidatePath(`/app/departments/${validDepartmentId}`);
  }

  return {
    success: true,
    project: {
      ...newProject,
      department_id: validDepartmentId || (newProject as Record<string, unknown>).department_id || null,
    } as Project,
  };
}

export async function addProjectMemberAction(params: {
  workspaceId: string;
  projectId: string;
  userId: string;
  role?: string;
}): Promise<{ success: boolean; error?: string }> {
  try {
    const authClient = await createClient();
    const {
      data: { user },
    } = await authClient.auth.getUser();

    if (!user) {
      return { success: false, error: "Not authenticated" };
    }

    const adminClient = createAdminClient();

    // Verify workspace membership
    const { data: caller } = await adminClient
      .from("workspace_members")
      .select("role, full_name")
      .eq("workspace_id", params.workspaceId)
      .eq("user_id", user.id)
      .maybeSingle();

    if (!caller) {
      return { success: false, error: "You are not a member of this workspace." };
    }

    // Insert project member
    await adminClient.from("project_members").upsert(
      {
        project_id: params.projectId,
        workspace_id: params.workspaceId,
        user_id: params.userId,
        role: params.role || "member",
        added_by: user.id,
      },
      { onConflict: "project_id,user_id" }
    );

    // Dispatch unified event notification (in-app notification + email)
    try {
      const { data: projectData } = await adminClient
        .from("projects")
        .select("name, slug")
        .eq("id", params.projectId)
        .maybeSingle();

      if (projectData) {
        dispatchProjectMemberAddedEvent({
          workspaceId: params.workspaceId,
          projectId: params.projectId,
          projectName: projectData.name,
          projectSlug: projectData.slug || params.projectId,
          addedByUserId: user.id,
          memberUserId: params.userId,
          memberRole: params.role || "member",
        }).catch((err) => console.error("[Project Actions] Dispatch event error:", err));
      }
    } catch (pipelineErr) {
      console.error("[Project Actions] Event pipeline notice:", pipelineErr);
    }

    revalidatePath("/app/projects");
    revalidatePath(`/app/projects/${params.projectId}`);

    return { success: true };
  } catch (err: any) {
    return { success: false, error: err?.message || "Failed to add project member." };
  }
}

export async function updateProjectAction(
  input: UpdateProjectInput
): Promise<CreateProjectResult> {
  const { projectId, workspaceId, name, description, status, color, icon } = input;

  const authClient = await createClient();
  const {
    data: { user },
  } = await authClient.auth.getUser();

  if (!user) {
    return { success: false, error: "Not authenticated" };
  }

  const adminClient = createAdminClient();

  const updates: Record<string, string | null> = {
    updated_at: new Date().toISOString(),
  };

  if (name !== undefined) updates.name = name.trim();
  if (description !== undefined) updates.description = description?.trim() || null;
  if (status !== undefined) updates.status = status;
  if (color !== undefined) updates.color = color;
  if (icon !== undefined) updates.icon = icon;

  const { data: updated, error } = await adminClient
    .from("projects")
    .update(updates)
    .eq("id", projectId)
    .eq("workspace_id", workspaceId)
    .select()
    .single();

  if (error || !updated) {
    return { success: false, error: error?.message || "Failed to update project." };
  }

  revalidatePath("/app");
  revalidatePath("/app/projects");
  revalidatePath(`/app/projects/${projectId}`);

  return { success: true, project: updated as Project };
}

export async function deleteProjectAction(
  projectId: string,
  workspaceId: string
): Promise<{ success: boolean; error?: string }> {
