/**
 * Fetch all projects for a specific workspace (deduplicated per request).
 * Returns ONLY real Supabase data — no fake fallbacks.
 * Returns empty array when the workspace genuinely has no projects.
 * Returns empty array when the user is not authenticated.
 */
export const getWorkspaceProjects = cache(
  async (workspaceId: string): Promise<Project[]> => {
    if (!workspaceId) return [];

    let isAuthed = true;
    try {
      const supabase = await createClient();
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) isAuthed = false;
    } catch {
      // CLI / background script context
    }

    if (!isAuthed) return [];

    const adminClient = createAdminClient();

    const { data, error } = await adminClient
      .from("projects")
      .select("*")
      .eq("workspace_id", workspaceId)
      .order("created_at", { ascending: false });

    if (error) {
      console.error("Error fetching workspace projects:", error?.message || error);
      return [];
    }

    if (!data || data.length === 0) {
      return [];
    }

    const rows = data as unknown as DBProjectRow[];

    // Fetch departments separately to map names and colors safely
    const deptMap = new Map<string, { id: string; name: string; color: string; icon: string }>();
    const projDeptFromTasksMap = new Map<string, string>();
    try {
      const [{ data: depts }, { data: tasksWithDept }] = await Promise.all([
        adminClient
          .from("departments")
          .select("id, name, color, icon")
          .eq("workspace_id", workspaceId),
        adminClient
          .from("tasks")
          .select("project_id, department_id")
          .eq("workspace_id", workspaceId)
          .not("department_id", "is", null)
          .not("project_id", "is", null),
      ]);

      if (depts) {
        depts.forEach((d) => deptMap.set(d.id, d));
      }
      (tasksWithDept || []).forEach((t) => {
        if (t.project_id && t.department_id) {
          projDeptFromTasksMap.set(t.project_id, t.department_id);
        }
      });
    } catch {
      // ignore
    }

    return rows.map((r) => {
      const resolvedDeptId = r.department_id || projDeptFromTasksMap.get(r.id) || null;
      const dept = resolvedDeptId ? deptMap.get(resolvedDeptId) : undefined;
      const deptName = r.departments?.name ?? dept?.name ?? null;
      const deptColor = r.departments?.color ?? dept?.color ?? null;
      // Normalize "active" → "in_progress" since the DB uses "active" but the type uses "in_progress"
      const status = (r.status === "active" ? "in_progress" : r.status) as Project["status"];

      return {
        id: r.id,
        workspace_id: r.workspace_id,
        department_id: resolvedDeptId,
        department_name: deptName,
        department_color: deptColor,
        name: r.name,
        slug: r.slug,
        description: r.description ?? null,
        status: status || "in_progress",
        priority: (r.priority || "medium") as Project["priority"],
        color: r.color || "#10251F",
        icon: r.icon || (r.name ? r.name[0].toUpperCase() : "P"),
        manager_id: r.lead_id || r.manager_id || null,
        manager_name: null,
        client_name: r.client_name ?? null,
        budget: r.budget ?? null,
        start_date: r.start_date ?? null,
        due_date: r.due_date ?? r.deadline ?? null,
        deadline: r.due_date ?? r.deadline ?? null,
        // task counts start at 0 — getOverviewData enriches them from real task data
        progress: 0,
        completed_tasks: 0,
        total_tasks: 0,
        // member_ids start empty — getOverviewData fills from task assignees
        member_ids: [],
        created_by: r.created_by ?? null,
        created_at: r.created_at,
        updated_at: r.updated_at,
      };
    });
  }
);

/**
 * Fetch a specific project by ID and verify it belongs to the workspace.
 * Resolves department and manager names accurately.
 */
export async function getProjectById(
  projectId: string,
  workspaceId: string
): Promise<Project | null> {
  if (!projectId || !workspaceId) return null;

  const adminClient = createAdminClient();

  const isUUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(projectId);

  let query = adminClient
    .from("projects")
    .select("*")
    .eq("workspace_id", workspaceId);

  if (isUUID) {
    query = query.eq("id", projectId);
  } else {
    query = query.eq("slug", projectId);
  }

  const { data, error } = await query.maybeSingle();

  if (!error && data) {
    const r = data as unknown as DBProjectRow;
    let deptName: string | null = null;
    let deptColor: string | null = null;

    if (r.department_id) {
      try {
        const { data: dept } = await adminClient
          .from("departments")
          .select("name, color")
          .eq("id", r.department_id)
          .maybeSingle();
        if (dept) {
          deptName = dept.name;
          deptColor = dept.color;
        }
      } catch {
        // ignore
      }
    }

    let managerName: string | null = null;
    const leadUserId = r.lead_id || r.created_by;
    if (leadUserId) {
      try {
        const { data: profile } = await adminClient
          .from("profiles")
          .select("full_name")
          .eq("id", leadUserId)
          .maybeSingle();
        if (profile?.full_name) {
          managerName = profile.full_name;
        }
      } catch {
        // Safe ignore if profiles table or row does not exist
      }

      // Safe fallback to workspace_members if profile row is missing
      if (!managerName) {
        try {
          const { data: member } = await adminClient
            .from("workspace_members")
            .select("full_name")
            .eq("workspace_id", r.workspace_id)
            .eq("user_id", leadUserId)
            .maybeSingle();
          if (member?.full_name) {
            managerName = member.full_name;
          }
        } catch {
          // Safe ignore
        }
      }
    }

    const status = (r.status === "active" ? "in_progress" : r.status) as Project["status"];

    return {
      id: r.id,
      workspace_id: r.workspace_id,
      department_id: r.department_id ?? null,
      department_name: deptName,
      department_color: deptColor,
      name: r.name,
      slug: r.slug,
      description: r.description ?? null,
      status: status || "in_progress",
      priority: (r.priority || "medium") as Project["priority"],
      color: r.color || "#10251F",
      icon: r.icon || (r.name ? r.name[0].toUpperCase() : "P"),
      manager_id: r.lead_id || r.manager_id || null,
      manager_name: managerName,
      client_name: r.client_name ?? null,
      budget: r.budget ?? null,
      start_date: r.start_date ?? null,
      due_date: r.due_date ?? r.deadline ?? null,
      deadline: r.due_date ?? r.deadline ?? null,
      progress: 0,
      completed_tasks: 0,
      total_tasks: 0,
      member_ids: [],
      created_by: r.created_by ?? null,
      created_at: r.created_at,
      updated_at: r.updated_at,
    };
  }

  return null;
}

/**
 * Return only projects the given UserContext is allowed to see.
 * - OWNER/ADMIN: all workspace projects
 * - DEPT_LEAD: all workspace projects in their dept + projects they manage/created
 * - MEMBER: projects in their dept + projects they're assigned to (via task_assignees or project_members)
 */
export async function getAccessibleProjects(
  ctx: { userId: string; workspaceId: string; isOwnerOrAdmin: boolean; deptIds: string[]; ledDeptIds: string[] },
  workspaceId: string
): Promise<Project[]> {
  const allProjects = await getWorkspaceProjects(workspaceId);

  if (ctx.isOwnerOrAdmin) return allProjects;

  const adminClient = createAdminClient();

  // Fetch projects user is explicitly a member of
  const { data: projMemberRows } = await adminClient
    .from("project_members")
    .select("project_id")
    .eq("workspace_id", workspaceId)
    .eq("user_id", ctx.userId);

  const explicitProjectIds = new Set((projMemberRows || []).map((r: any) => r.project_id));

  return allProjects.filter((p) => {
    // Project in user's dept
    if (p.department_id && ctx.deptIds.includes(p.department_id)) return true;
    // User is project lead/manager
    if (p.manager_id === ctx.userId) return true;
    // User created it
    if (p.created_by === ctx.userId) return true;
    // User is explicit project member
    if (explicitProjectIds.has(p.id)) return true;
    // User is assigned tasks on this project
    if (p.member_ids?.includes(ctx.userId)) return true;
    return false;
  });
}

import "server-only";

/**
 * Server-side Cloudflare Turnstile verification helper.
 * If TURNSTILE_SECRET_KEY is not configured in development, passes through gracefully.
 */
export async function verifyTurnstileToken(
  token?: string | null,
  ip?: string
): Promise<{ success: boolean; error?: string }> {
  const secretKey = process.env.TURNSTILE_SECRET_KEY;

  // In development without secret key, allow test bypass
  if (!secretKey) {
    return { success: true };
  }

  if (!token || !token.trim()) {
    return {
      success: false,
      error: "Cloudflare Turnstile verification token is missing. Please complete the captcha.",
    };
  }

  try {
    const formData = new URLSearchParams();
    formData.append("secret", secretKey);
    formData.append("response", token.trim());
    if (ip) {
      formData.append("remoteip", ip);
    }

    const res = await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify", {
      method: "POST",
      body: formData,
    });

    if (!res.ok) {
      return { success: false, error: "Failed to communicate with Cloudflare Turnstile verification service." };
    }

    const outcome = await res.json();
    if (!outcome.success) {
      return {
        success: false,
        error: "Captcha verification failed. Please verify that you are human and try again.",
      };
    }

    return { success: true };
  } catch (error: any) {
    console.error("[Turnstile] Verification error:", error);
    return {
      success: false,
      error: "An unexpected error occurred during captcha verification.",
    };
  }
}

import { cache } from "react";
import { createAdminClient } from "@/lib/supabase/admin";
import {
  Task,
  CategorizedTasks,
  TaskProjectRef,
  TaskDepartmentRef,
  TaskAttachment,
  TaskActivity,
  TaskComment,
  TaskSubmission,
  TaskStatus,
  TaskPriority,
} from "@/types/task";
import { getWorkspacePeople } from "@/lib/people/queries";
import { WorkspacePerson } from "@/types/people";

interface RawTaskRow {
  id: string;
  workspace_id: string;
  project_id: string | null;
  department_id: string | null;
  title: string;
  description: string | null;
  status: TaskStatus;
  priority: TaskPriority;
  due_date: string | null;
  deliverable_type?: string | null;
  expected_outcome?: string | null;
  requires_approval?: boolean;
  approver_id?: string | null;
  notify_assignees?: boolean;
  notify_department?: boolean;
  is_draft?: boolean;
  created_by: string | null;
  created_at: string;
  updated_at: string;
  projects?: {
    id: string;
    name: string;
    color: string;
    icon: string;
  } | null;
  departments?: {
    id: string;
    name: string;
    color: string;
    icon: string;
  } | null;
}

interface AssigneeRow {
  task_id: string;
  user_id: string;
}

/**
 * Helper to enrich tasks with assignees, references, attachments, activities, comments, and submissions
 */
async function enrichTasks(
  rawTasks: RawTaskRow[],
  workspaceId: string,
  includeDetails: boolean = true
): Promise<Task[]> {
  if (!rawTasks || rawTasks.length === 0) return [];

  const taskIds = rawTasks.map((t) => t.id);
  const adminClient = createAdminClient();

  // Fetch in parallel: assignees and people (and deep collections only if requested)
  const [
    { data: assigneeRows },
    allPeople,
    attachmentResult,
    activityResult,
    commentResult,
    submissionResult,
  ] = await Promise.all([
    adminClient.from("task_assignees").select("task_id, user_id").in("task_id", taskIds),
    getWorkspacePeople(workspaceId),
    includeDetails
      ? adminClient.from("task_attachments").select("*").in("task_id", taskIds).order("created_at", { ascending: true })
      : Promise.resolve({ data: [] }),
    includeDetails
      ? adminClient.from("task_activities").select("*").in("task_id", taskIds).order("created_at", { ascending: false })
      : Promise.resolve({ data: [] }),
    includeDetails
      ? adminClient.from("task_comments").select("*").in("task_id", taskIds).order("created_at", { ascending: true })
      : Promise.resolve({ data: [] }),
    includeDetails
      ? adminClient.from("task_submissions").select("*").in("task_id", taskIds).order("created_at", { ascending: false })
      : Promise.resolve({ data: [] }),
  ]);

  const attachmentRows = attachmentResult.data || [];
  const activityRows = activityResult.data || [];
  const commentRows = commentResult.data || [];
  const submissionRows = submissionResult.data || [];

  const peopleMap = new Map<string, WorkspacePerson>(
    allPeople.map((p) => [p.user_id, p])
  );

  // Group assignees by task_id
  const taskAssigneesMap = new Map<string, WorkspacePerson[]>();
  (assigneeRows as AssigneeRow[] || []).forEach((row) => {
    const person = peopleMap.get(row.user_id);
    if (person) {
      const list = taskAssigneesMap.get(row.task_id) || [];
      list.push(person);
      taskAssigneesMap.set(row.task_id, list);
    }
  });

  // Group attachments by task_id
  const taskAttachmentsMap = new Map<string, TaskAttachment[]>();
  (attachmentRows || []).forEach((att) => {
    const uploader = att.uploaded_by ? peopleMap.get(att.uploaded_by) || null : null;
    const item: TaskAttachment = {
      id: att.id,
      task_id: att.task_id,
      workspace_id: att.workspace_id,
      file_name: att.file_name,
      file_size: att.file_size,
      file_type: att.file_type,
      file_url: att.file_url,
      uploaded_by: att.uploaded_by,
      uploader,
      created_at: att.created_at,
    };
    const list = taskAttachmentsMap.get(att.task_id) || [];
    list.push(item);
    taskAttachmentsMap.set(att.task_id, list);
  });

  // Group activities by task_id
  const taskActivitiesMap = new Map<string, TaskActivity[]>();
  (activityRows || []).forEach((act) => {
    const actor = act.user_id ? peopleMap.get(act.user_id) : null;
    const item: TaskActivity = {
      id: act.id,
      task_id: act.task_id,
      workspace_id: act.workspace_id,
      user_id: act.user_id,
      user_name: actor ? actor.full_name || actor.email : "Workspace Member",
      action_type: act.action_type,
      details: act.details || {},
      created_at: act.created_at,
    };
    const list = taskActivitiesMap.get(act.task_id) || [];
    list.push(item);
    taskActivitiesMap.set(act.task_id, list);
  });

  // Group comments by task_id
  const taskCommentsMap = new Map<string, TaskComment[]>();
  (commentRows || []).forEach((c) => {
    const author = c.user_id ? peopleMap.get(c.user_id) || null : null;
    const item: TaskComment = {
      id: c.id,
      task_id: c.task_id,
      workspace_id: c.workspace_id,
      user_id: c.user_id,
      author,
      content: c.content,
      attachment_url: c.attachment_url,
      attachment_name: c.attachment_name,
      created_at: c.created_at,
    };
    const list = taskCommentsMap.get(c.task_id) || [];
    list.push(item);
    taskCommentsMap.set(c.task_id, list);
  });

  // Group submissions by task_id
  const taskSubmissionsMap = new Map<string, TaskSubmission[]>();
  (submissionRows || []).forEach((s) => {
    const submitter = s.submitted_by ? peopleMap.get(s.submitted_by) || null : null;
    const reviewer = s.reviewed_by ? peopleMap.get(s.reviewed_by) || null : null;
    const item: TaskSubmission = {
      id: s.id,
      task_id: s.task_id,
      workspace_id: s.workspace_id,
      submitted_by: s.submitted_by,
      submitter,
      note: s.note,
      file_url: s.file_url,
      file_name: s.file_name,
      file_size: s.file_size,
      status: s.status,
      feedback: s.feedback,
      reviewed_by: s.reviewed_by,
      reviewer,
      reviewed_at: s.reviewed_at,
      created_at: s.created_at,
    };
    const list = taskSubmissionsMap.get(s.task_id) || [];
    list.push(item);
    taskSubmissionsMap.set(s.task_id, list);
  });

  return rawTasks.map((t) => {
    const project: TaskProjectRef | null = t.projects
      ? {
          id: t.projects.id,
          name: t.projects.name,
          color: t.projects.color,
          icon: t.projects.icon,
        }
      : null;

    const department: TaskDepartmentRef | null = t.departments
      ? {
          id: t.departments.id,
          name: t.departments.name,
          color: t.departments.color,
          icon: t.departments.icon,
        }
      : null;

    const assignees = taskAssigneesMap.get(t.id) || [];
    const attachments = taskAttachmentsMap.get(t.id) || [];
    const activities = taskActivitiesMap.get(t.id) || [];
    const comments = taskCommentsMap.get(t.id) || [];
    const submissions = taskSubmissionsMap.get(t.id) || [];
    const approver = t.approver_id ? peopleMap.get(t.approver_id) || null : null;
    const creator = t.created_by ? peopleMap.get(t.created_by) || null : null;

    return {
      id: t.id,
      workspace_id: t.workspace_id,
      project_id: t.project_id,
      department_id: t.department_id,
      title: t.title,
      description: t.description,
      status: t.status,
      priority: t.priority,
      due_date: t.due_date,
      deliverable_type: t.deliverable_type || null,
      expected_outcome: t.expected_outcome || null,
      requires_approval: t.requires_approval || false,
      approver_id: t.approver_id || null,
      approver,
      notify_assignees: t.notify_assignees ?? true,
      notify_department: t.notify_department ?? true,
      is_draft: t.is_draft || false,
      created_by: t.created_by,
      creator,
      created_at: t.created_at,
      updated_at: t.updated_at,
      assignees,
      project,
      department,
      attachments,
      activities,
      comments,
      submissions,
    };
  });
}

/**
 * Fetch all non-draft tasks in a workspace (deduplicated per request)
 */
export const getWorkspaceTasks = cache(
  async (workspaceId: string): Promise<Task[]> => {
    if (!workspaceId) return [];

    const adminClient = createAdminClient();

    let { data, error } = await adminClient
      .from("tasks")
      .select(`
        *,
        projects:project_id(id, name, color, icon),
        departments:department_id(id, name, color, icon)
      `)
      .eq("workspace_id", workspaceId)
      .eq("is_draft", false)
      .order("created_at", { ascending: false });

    if (error) {
      const retry = await adminClient
        .from("tasks")
        .select("*")
        .eq("workspace_id", workspaceId)
        .eq("is_draft", false)
        .order("created_at", { ascending: false });

      data = retry.data;
      error = retry.error;
    }

    if (error || !data) {
      if (error) console.error("Error fetching workspace tasks:", error.message || error);
      return [];
    }

    return enrichTasks(data as unknown as RawTaskRow[], workspaceId);
  }
);

/**
 * Fetch categorized tasks for the current user (My Tasks - deduplicated per request)
 */
export const getMyTasks = cache(
  async (userId: string, workspaceId: string): Promise<CategorizedTasks> => {
    const empty: CategorizedTasks = {
      overdue: [],
      today: [],
      upcoming: [],
      noDueDate: [],
      completed: [],
    };

    if (!userId || !workspaceId) return empty;

    const adminClient = createAdminClient();

    // Find task IDs assigned to this user
    const { data: userAssignments } = await adminClient
      .from("task_assignees")
      .select("task_id")
      .eq("user_id", userId);

    const assignedTaskIds = (userAssignments || []).map((a) => a.task_id);

    if (assignedTaskIds.length === 0) {
      return empty;
    }

    let { data: rawTasks, error } = await adminClient
      .from("tasks")
      .select(`
        *,
        projects:project_id(id, name, color, icon),
        departments:department_id(id, name, color, icon)
      `)
      .eq("workspace_id", workspaceId)
      .in("id", assignedTaskIds)
      .order("created_at", { ascending: false });

    if (error) {
      const retry = await adminClient
        .from("tasks")
        .select("*")
        .eq("workspace_id", workspaceId)
        .in("id", assignedTaskIds)
        .order("created_at", { ascending: false });

      rawTasks = retry.data;
      error = retry.error;
    }

    if (error || !rawTasks) {
      return empty;
    }

    const tasks = await enrichTasks(rawTasks as unknown as RawTaskRow[], workspaceId);

    const now = new Date();
    const todayStr = now.toISOString().split("T")[0];

    const categorized: CategorizedTasks = {
      overdue: [],
      today: [],
      upcoming: [],
      noDueDate: [],
      completed: [],
    };

    tasks.forEach((task) => {
      if (task.status === "completed") {
        categorized.completed.push(task);
        return;
      }

      if (!task.due_date) {
        categorized.noDueDate.push(task);
        return;
      }

      const taskDateStr = new Date(task.due_date).toISOString().split("T")[0];

      if (taskDateStr < todayStr) {
        categorized.overdue.push(task);
      } else if (taskDateStr === todayStr) {
        categorized.today.push(task);
      } else {
        categorized.upcoming.push(task);
      }
    });

    return categorized;
  }
);


