/**
 * Real task metrics for Overview dashboard (deduplicated per request)
 */
export const getOverviewTaskMetrics = cache(
  async (userId: string, workspaceId: string) => {
    const categorized = await getMyTasks(userId, workspaceId);

    const openTasksCount =
      categorized.overdue.length +
      categorized.today.length +
      categorized.upcoming.length +
      categorized.noDueDate.length;

    const dueTodayCount = categorized.today.length;
    const overdueCount = categorized.overdue.length;
    const completedCount = categorized.completed.length;

    const myOpenTasks = [
      ...categorized.overdue,
      ...categorized.today,
      ...categorized.upcoming,
      ...categorized.noDueDate,
    ].slice(0, 5);

    return {
      openTasksCount,
      dueTodayCount,
      overdueCount,
      completedCount,
      myOpenTasks,
      recentlyCompleted: categorized.completed.slice(0, 5),
    };
  }
);

export interface WorkspaceActivityItem {
  id: string;
  type: "project_created" | "task_created" | "task_completed" | "activity";
  targetName: string;
  createdAt: string;
  actorName: string;
  details?: string;
}

/**
 * Fetch recent activity across the workspace (projects, tasks, activities - deduplicated per request)
 */
export const getWorkspaceRecentActivities = cache(
  async (workspaceId: string): Promise<WorkspaceActivityItem[]> => {
    if (!workspaceId) return [];

    const adminClient = createAdminClient();

    // Fetch projects, tasks, and people in parallel!
    const [{ data: projects }, { data: tasks }, people] = await Promise.all([
      adminClient
        .from("projects")
        .select("id, name, created_by, created_at")
        .eq("workspace_id", workspaceId)
        .order("created_at", { ascending: false })
        .limit(5),
      adminClient
        .from("tasks")
        .select("id, title, created_by, created_at, status")
        .eq("workspace_id", workspaceId)
        .order("created_at", { ascending: false })
        .limit(10),
      getWorkspacePeople(workspaceId),
    ]);

    const peopleMap = new Map(people.map((p) => [p.user_id, p.full_name || p.email]));
    const activities: WorkspaceActivityItem[] = [];

    if (projects) {
      projects.forEach((proj) => {
        const actorName = proj.created_by ? peopleMap.get(proj.created_by) || "You" : "You";
        activities.push({
          id: `proj-${proj.id}`,
          type: "project_created",
          targetName: proj.name,
          createdAt: proj.created_at,
          actorName,
        });
      });
    }

    if (tasks) {
      tasks.forEach((t) => {
        const actorName = t.created_by ? peopleMap.get(t.created_by) || "You" : "You";
        activities.push({
          id: `task-${t.id}`,
          type: t.status === "completed" ? "task_completed" : "task_created",
          targetName: t.title,
          createdAt: t.created_at,
          actorName,
        });
      });
    }

    // Sort all activities by createdAt descending and take top 5
    activities.sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );

    return activities.slice(0, 5);
  }
);

/**
 * Fetch upcoming deadlines for the workspace/user (deduplicated per request)
 */
export const getUpcomingDeadlines = cache(
  async (workspaceId: string, userId?: string): Promise<Task[]> => {
    if (!workspaceId) return [];

    const allTasks = await getWorkspaceTasks(workspaceId);
    const now = new Date();
    const todayStr = now.toISOString().split("T")[0];

    const upcoming = allTasks.filter((t) => {
      if (t.status === "completed" || !t.due_date) return false;
      const taskDateStr = new Date(t.due_date).toISOString().split("T")[0];
      if (userId) {
        const isAssigned = t.assignees.some((a) => a.user_id === userId);
        return taskDateStr >= todayStr && isAssigned;
      }
      return taskDateStr >= todayStr;
    });

    return upcoming.sort(
      (a, b) => new Date(a.due_date!).getTime() - new Date(b.due_date!).getTime()
    );
  }
);



/**
 * Return only tasks the given UserContext is allowed to see.
 * - OWNER/ADMIN: all workspace tasks
 * - DEPT_LEAD: tasks in their dept + assigned tasks
 * - MEMBER: tasks assigned to them + tasks on accessible projects (their dept)
 */
export async function getAccessibleTasks(
  ctx: { userId: string; isOwnerOrAdmin: boolean; deptIds: string[]; ledDeptIds: string[]; isDeptLead: boolean },
  workspaceId: string,
  accessibleProjectIds: string[]
): Promise<Task[]> {
  if (!workspaceId) return [];

  const adminClient = createAdminClient();

  if (ctx.isOwnerOrAdmin) {
    return getWorkspaceTasks(workspaceId);
  }

  // Find tasks assigned to user
  const { data: userAssignments } = await adminClient
    .from("task_assignees")
    .select("task_id")
    .eq("user_id", ctx.userId);

  const assignedTaskIds = new Set((userAssignments || []).map((a: any) => a.task_id));

  // Fetch all tasks for accessible projects + user's depts
  let query = adminClient
    .from("tasks")
    .select(`
      *,
      projects:project_id(id, name, color, icon),
      departments:department_id(id, name, color, icon)
    `)
    .eq("workspace_id", workspaceId)
    .eq("is_draft", false);

  const { data, error } = await query.order("created_at", { ascending: false });

  if (error || !data) return [];

  // Filter to visible tasks
  const rawFiltered = (data as unknown as RawTaskRow[]).filter((t) => {
    if (assignedTaskIds.has(t.id)) return true;
    if (t.created_by === ctx.userId) return true;
    if (t.department_id && ctx.ledDeptIds.includes(t.department_id)) return true;
    if (t.project_id && accessibleProjectIds.includes(t.project_id)) return true;
    if (t.department_id && ctx.deptIds.includes(t.department_id)) return true;
    return false;
  });

  return enrichTasks(rawFiltered, workspaceId);
}

"use server";

import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { revalidatePath } from "next/cache";
import { cookies } from "next/headers";

export interface CreateWorkspaceResult {
  success: boolean;
  workspaceId?: string;
  slug?: string;
  error?: string;
}

function generateBaseSlug(name: string): string {
  const sanitized = name
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return sanitized || "workspace";
}

export async function createWorkspaceAction(
  name: string,
  icon: string = "W"
): Promise<CreateWorkspaceResult> {
  // 1. Verify Authentication using user session cookies
  const authClient = await createClient();
  const {
    data: { user },
    error: authError,
  } = await authClient.auth.getUser();

  if (authError || !user) {
    return { success: false, error: "You must be logged in to create a workspace." };
  }

  const trimmedName = name.trim();
  if (!trimmedName || trimmedName.length < 2) {
    return { success: false, error: "Workspace name must be at least 2 characters long." };
  }

  // 2. Generate unique slug
  let slug = generateBaseSlug(trimmedName);
  const adminClient = createAdminClient();

  // Check if slug already exists
  const { data: existingSlug } = await adminClient
    .from("workspaces")
    .select("id")
    .eq("slug", slug)
    .maybeSingle();

  if (existingSlug) {
    const randomSuffix = Math.random().toString(36).substring(2, 6);
    slug = `${slug}-${randomSuffix}`;
  }

  // 3. Atomically insert Workspace and Owner Membership using verified user.id
  const { data: wsData, error: wsError } = await adminClient
    .from("workspaces")
    .insert({
      name: trimmedName,
      slug,
      icon,
      created_by: user.id,
    })
    .select("id, slug")
    .single();

  if (wsError || !wsData) {
    console.error("Workspace creation error:", wsError);
    return {
      success: false,
      error: wsError?.message || "Failed to create workspace. Please try again.",
    };
  }

  // Add user as owner in workspace_members
  const { error: memberError } = await adminClient
    .from("workspace_members")
    .insert({
      workspace_id: wsData.id,
      user_id: user.id,
      role: "owner",
    });

  if (memberError) {
    console.error("Workspace member assignment error:", memberError);
    return {
      success: false,
      error: "Workspace created, but could not set membership. Please try again.",
    };
  }

  revalidatePath("/app");
  revalidatePath("/onboarding");

  return {
    success: true,
    workspaceId: wsData.id,
    slug: wsData.slug,
  };
}

export interface SmartOnboardingDepartmentInput {
  name: string;
  description?: string;
  color?: string;
  icon?: string;
}

export interface CompleteSmartOnboardingInput {
  fullName: string;
  organizationType?: string;
  workspaceName: string;
  monogram?: string;
  companyWebsite?: string;
  companySummary?: string;
  role?: string;
  departments?: SmartOnboardingDepartmentInput[];
  inviteEmails?: string[];
}

export async function completeSmartOnboardingAction(
  input: CompleteSmartOnboardingInput
): Promise<CreateWorkspaceResult> {
  const authClient = await createClient();
  const {
    data: { user },
    error: authError,
  } = await authClient.auth.getUser();

  if (authError || !user) {
    return { success: false, error: "You must be logged in to set up your workspace." };
  }

  const trimmedName = input.workspaceName?.trim() || "My Workspace";
  if (trimmedName.length < 2) {
    return { success: false, error: "Workspace name must be at least 2 characters long." };
  }

  // 1. Update user auth metadata
  if (input.fullName?.trim() || input.role?.trim()) {
    try {
      await authClient.auth.updateUser({
        data: {
          full_name: input.fullName.trim() || user.user_metadata?.full_name,
          role: input.role?.trim() || "Founder",
          onboarding_completed: true,
        },
      });
    } catch (err) {
      console.warn("Auth user metadata update note:", err);
    }
  }

  const adminClient = createAdminClient();

  // 2. Generate unique slug
  let slug = generateBaseSlug(trimmedName);
  const { data: existingSlug } = await adminClient
    .from("workspaces")
    .select("id")
    .eq("slug", slug)
    .maybeSingle();

  if (existingSlug) {
    const randomSuffix = Math.random().toString(36).substring(2, 6);
    slug = `${slug}-${randomSuffix}`;
  }

  const icon = input.monogram || (trimmedName ? trimmedName[0].toUpperCase() : "W");

  // 3. Insert Workspace
  const { data: wsData, error: wsError } = await adminClient
    .from("workspaces")
    .insert({
      name: trimmedName,
      slug,
      icon,
      created_by: user.id,
    })
    .select("id, slug")
    .single();

  if (wsError || !wsData) {
    console.error("Workspace creation error:", wsError);
    return {
      success: false,
      error: wsError?.message || "Failed to create workspace. Please try again.",
    };
  }

  // 4. Set user as Owner
  await adminClient.from("workspace_members").insert({
    workspace_id: wsData.id,
    user_id: user.id,
    role: "owner",
  });

  // 5. Upsert into people table if available
  try {
    await adminClient.from("people").upsert(
      {
        workspace_id: wsData.id,
        user_id: user.id,
        email: user.email,
        full_name: input.fullName?.trim() || user.user_metadata?.full_name || "Workspace Owner",
        role: "owner",
        job_title: input.role?.trim() || "Founder / Executive",
        status: "active",
      },
      { onConflict: "workspace_id,user_id" }
    );
  } catch (err) {
    console.warn("People upsert note:", err);
  }

  // 6. Provision approved starter departments
  if (input.departments && input.departments.length > 0) {
    for (const dept of input.departments) {
      if (!dept.name?.trim()) continue;
      const deptName = dept.name.trim();
      let deptSlug = deptName.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
      if (!deptSlug) deptSlug = "department";

      try {
        const { data: createdDept } = await adminClient
          .from("departments")
          .insert({
            workspace_id: wsData.id,
            name: deptName,
            slug: deptSlug,
            description: dept.description?.trim() || null,
            icon: dept.icon || "building",
            color: dept.color || "#10251F",
            created_by: user.id,
          })
          .select("id")
          .single();

        if (createdDept) {
          await adminClient.from("department_members").insert({
            workspace_id: wsData.id,
            department_id: createdDept.id,
            user_id: user.id,
            job_title: input.role?.trim() || "Department Lead",
          });
        }
      } catch (deptErr) {
        console.warn("Department provisioning note:", deptErr);
      }
    }
  }

  // 7. Dispatch team invitations if emails provided
  if (input.inviteEmails && input.inviteEmails.length > 0) {
    try {
      const { inviteEmployeeAction } = await import("@/lib/invitations/actions");
      for (const email of input.inviteEmails) {
        const cleanEmail = email.trim().toLowerCase();
        if (cleanEmail && cleanEmail.includes("@")) {
          await inviteEmployeeAction({
            workspaceId: wsData.id,
            email: cleanEmail,
            role: "member",
            jobTitle: "Team Member",
          });
        }
      }
    } catch (invErr) {
      console.warn("Invitation dispatch note:", invErr);
    }
  }

  revalidatePath("/app");
  revalidatePath("/onboarding");
  revalidatePath("/app/departments");

  return {
    success: true,
    workspaceId: wsData.id,
    slug: wsData.slug,
  };
}

/**
 * Switch the user's active workspace by storing preference in cookie
 */
export async function switchActiveWorkspaceAction(
  workspaceId: string
): Promise<{ success: boolean; error?: string }> {
  try {
    const cookieStore = await cookies();
    cookieStore.set("ropimo_active_workspace", workspaceId, {
      path: "/",
      maxAge: 60 * 60 * 24 * 365,
      sameSite: "lax",
    });
    revalidatePath("/app");
    return { success: true };
  } catch (err: any) {
    return { success: false, error: err.message || "Failed to switch workspace." };
  }
}

/**
 * Update workspace name, slug, and logo/icon with owner/admin role verification
 */
export async function updateWorkspaceSettingsAction(params: {
  workspaceId: string;
  name: string;
  slug: string;
  logoUrl?: string | null;
  icon?: string | null;
}): Promise<{
  success: boolean;
  workspace?: { id: string; name: string; slug: string; logoUrl?: string | null; icon?: string | null };
  error?: string;
}> {
  try {
    const { requireWorkspaceRole } = await import("@/lib/auth/require-user");

    // 1. Enforce strict role check: owner or admin only
    await requireWorkspaceRole(params.workspaceId, ["owner", "admin"]);

    const trimmedName = params.name.trim();
    if (!trimmedName || trimmedName.length < 2) {
      return { success: false, error: "Workspace name must be at least 2 characters." };
    }
    if (trimmedName.length > 100) {
      return { success: false, error: "Workspace name cannot exceed 100 characters." };
    }

    const normalizedSlug = params.slug
      .toLowerCase()
      .trim()
      .replace(/[^a-z0-9-]+/g, "-")
      .replace(/^-+|-+$/g, "");

    if (!normalizedSlug || normalizedSlug.length < 3) {
      return { success: false, error: "Workspace slug must be at least 3 characters." };
    }
    if (normalizedSlug.length > 50) {
      return { success: false, error: "Workspace slug cannot exceed 50 characters." };
    }
    if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(normalizedSlug)) {
      return {
        success: false,
        error: "Slug may only contain lowercase letters, numbers, and hyphens (cannot start or end with a hyphen).",
      };
    }

    const adminClient = createAdminClient();

    // 2. Check slug uniqueness across workspaces
    const { data: existingWorkspace } = await adminClient
      .from("workspaces")
      .select("id")
      .eq("slug", normalizedSlug)
      .neq("id", params.workspaceId)
      .maybeSingle();

    if (existingWorkspace) {
      return { success: false, error: "This workspace slug is already taken. Please choose another." };
    }

    // 3. Update workspace details
    const updateData: Record<string, any> = {
      name: trimmedName,
      slug: normalizedSlug,
      updated_at: new Date().toISOString(),
    };
    if (params.logoUrl !== undefined) {
      updateData.logo_url = params.logoUrl;
    }
    if (params.icon !== undefined) {
      updateData.icon = params.icon;
    }

    const { data: updated, error } = await adminClient
      .from("workspaces")
      .update(updateData)
      .eq("id", params.workspaceId)
      .select("id, name, slug, logo_url, icon")
      .single();

    if (error || !updated) {
      return { success: false, error: error?.message || "Failed to update workspace settings." };
    }

    revalidatePath("/app/settings");
    revalidatePath("/app");

    return {
      success: true,
      workspace: {
        id: updated.id,
        name: updated.name,
        slug: updated.slug,
        logoUrl: updated.logo_url,
        icon: updated.icon,
      },
    };
  } catch (err: any) {
    return { success: false, error: err.message || "An unexpected error occurred." };
  }
}

